import { FastifyReply, FastifyRequest } from 'fastify';

import { env } from '../config/env';
import { loginSchema, refreshTokenSchema,registerSchema } from '../schemas';
import { AuthService } from '../services/auth.service';
import { RateLimitService } from '../services/rate-limit.service';
import { InferSchema } from '../types/fastify';

export class AuthController {
  private authService: AuthService;
  private rateLimitService: RateLimitService;

  constructor(authService: AuthService, rateLimitService: RateLimitService) {
    this.authService = authService;
    this.rateLimitService = rateLimitService;
  }

  async login(
    request: FastifyRequest<{ Body: InferSchema<typeof loginSchema> }>,
    reply: FastifyReply,
  ) {
    const { email, password } = request.body;
    const {ip} = request;

    // 1. Check rate limit and lockout
    const rateLimit = await this.rateLimitService.checkLimit(ip, email);
    if (!rateLimit.allowed) {
      return reply.status(429).send({
        error: rateLimit.isLocked
          ? 'Account locked due to multiple failed attempts. Please try again in 15 minutes.'
          : 'Too many login attempts. Please try again later.',
        retryAfter: Math.ceil((rateLimit.reset - Date.now()) / 1000),
      });
    }

    // 2. Find user
    const user = await request.server.prisma.user.findUnique({
      where: { email },
    });

    // 3. Verify user and password
    if (!user || !user.isActive) {
      await this.rateLimitService.recordAttempt(ip);
      return reply.status(401).send({ error: 'Invalid credentials' });
    }

    const isValid = await this.authService.comparePassword(
      password,
      user.passwordHash,
    );
    if (!isValid) {
      await this.rateLimitService.recordAttempt(ip);
      return reply.status(401).send({ error: 'Invalid credentials' });
    }

    // 4. Reset attempts on success
    await this.rateLimitService.reset(ip, email);

    // 5. Generate tokens
    const tokens = await this.authService.generateTokens({
      id: user.id,
      email: user.email,
      role: user.role,
      tenantId: (user as any).tenantId,
    }, request.ip, request.headers['user-agent'] || 'unknown');

    // 6. Set refresh token in httpOnly cookie
    void reply.setCookie('refreshToken', tokens.refreshToken, {      httpOnly: true,
      secure: env.NODE_ENV === 'production',
      sameSite: 'strict',
      expires: tokens.expiresAt,
      path: '/api/auth',
    });

    return {
      token: tokens.accessToken,
      refreshToken: tokens.refreshToken,
      expiresAt: new Date(Date.now() + 15 * 60 * 1000).toISOString(),
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
      },
    };
  }

  async register(
    request: FastifyRequest<{ Body: InferSchema<typeof registerSchema> }>,
    reply: FastifyReply,
  ) {
    const { email, password, name } = request.body;
    const {prisma} = request.server;

    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) {
      return reply.status(409).send({ error: 'Email already registered' });
    }

    const passwordHash = await this.authService.hashPassword(password);
    const user = await prisma.user.create({
      data: {
        email,
        passwordHash,
        name,
        role: 'VIEWER',
      },
    });

    return reply.status(201).send({
      id: user.id,
      email: user.email,
      name: user.name,
      role: user.role,
    });
  }

  async refresh(
    request: FastifyRequest<{ Body: InferSchema<typeof refreshTokenSchema> }>,
    reply: FastifyReply,
  ) {
    const refreshToken =
      request.body.refreshToken || request.cookies.refreshToken;

    if (!refreshToken) {
      return reply.status(401).send({ error: 'Refresh token required' });
    }

    try {
      const tokens = await this.authService.rotateRefreshToken(
        refreshToken,
        request.ip,
        request.headers['user-agent'] || 'unknown'
      );

      void reply.setCookie('refreshToken', tokens.refreshToken, {        httpOnly: true,
        secure: env.NODE_ENV === 'production',
        sameSite: 'strict',
        expires: tokens.expiresAt,
        path: '/api/auth',
      });

      return {
        token: tokens.accessToken,
        refreshToken: tokens.refreshToken,
        expiresAt: new Date(Date.now() + 15 * 60 * 1000).toISOString(),
      };
    } catch (error) {
      // If security alert or reuse detected, we might want to be more specific or generic
      const errorMessage = error instanceof Error ? error.message : String(error);
      const message = errorMessage.includes('reuse detected') 
        ? 'Security alert: Refresh token reuse detected. All sessions invalidated.'
        : 'Invalid or expired refresh token';
        
      return reply
        .status(401)
        .send({ error: message });
    }
  }

  async logout(request: FastifyRequest, reply: FastifyReply) {
    const {refreshToken} = request.cookies;
    if (refreshToken) {
      await this.authService.revokeSession(refreshToken);
    }
    void reply.clearCookie('refreshToken', { path: '/api/auth' });    return { success: true };
  }

  async me(request: FastifyRequest, _reply: FastifyReply) {
    const user = await request.server.prisma.user.findUnique({
      where: { id: request.user!.id },
      select: {
        id: true,
        email: true,
        name: true,
        role: true,
        createdAt: true,
        lastLoginAt: true,
      },
    });
    return user;
  }

  async listSessions(request: FastifyRequest, _reply: FastifyReply) {
    const userId = request.user!.id;
    const sessions = await this.authService.listUserSessions(userId);
    return sessions;
  }

  async revokeSession(request: FastifyRequest<{ Params: { id: string } }>, _reply: FastifyReply) {
    const userId = request.user!.id;
    const sessionId = request.params.id;
    await this.authService.revokeSessionById(sessionId, userId);
    return { success: true };
  }

  async revokeAllSessions(request: FastifyRequest, _reply: FastifyReply) {
    const userId = request.user!.id;
    await this.authService.revokeAllUserSessions(userId);
    return { success: true };
  }
}

import { trace } from '@opentelemetry/api';
import { PrismaClient } from '@prisma/client';

import { env } from '../config/env';

/**
 * Extension to record slow database queries in OpenTelemetry traces
 */
const slowQueryExtension = {
  query: {
    async $allOperations({ operation, model, args, query }: any) {
      const start = Date.now();
      const result = await query(args);
      const duration = Date.now() - start;

      if (duration > 500) {
        const span = trace.getActiveSpan();
        if (span) {
          span.addEvent('slow_db_query', {
            'db.operation': operation,
            'db.model': model || 'unknown',
            'db.duration_ms': duration,
          });
        }
      }
      return result;
    },
  },
};

class PrismaClientWithReplicas {
  private primary: any;
  private readReplica: any = null;
  private useReadReplica: boolean;

  constructor() {
    const primaryUrl = env.DATABASE_URL;
    const readReplicaUrl = env.DATABASE_READ_URL || primaryUrl;

    const basePrimary = new PrismaClient({
      log:
        env.NODE_ENV === 'development'
          ? ['query', 'error', 'warn']
          : ['error'],
    });
    this.primary = basePrimary.$extends(slowQueryExtension);

    // Only create read replica client if URL is different from primary
    this.useReadReplica = readReplicaUrl !== primaryUrl && !!readReplicaUrl;

    if (this.useReadReplica) {
      const baseReplica = new PrismaClient({
        datasources: {
          db: {
            url: readReplicaUrl,
          },
        },
        log:
          env.NODE_ENV === 'development'
            ? ['query', 'error', 'warn']
            : ['error'],
      });
      this.readReplica = baseReplica.$extends(slowQueryExtension);
    }
  }

  /**
   * Get client for write operations (always uses primary)
   */
  get write(): PrismaClient {
    return this.primary;
  }

  /**
   * Get client for read operations (uses replica if available)
   */
  get read(): PrismaClient {
    return this.readReplica || this.primary;
  }

  /**
   * Get primary client for transactions
   */
  get $transaction() {
    return this.primary.$transaction.bind(this.primary);
  }

  /**
   * Connect both clients
   */
  async $connect() {
    // Note: $extends clients don't have $connect themselves, use base
    // Actually they usually do, but let's be safe if they don't.
    // In Prisma 5+, they do have it.
    await this.primary.$connect();
    if (this.readReplica) {
      await this.readReplica.$connect();
    }
  }

  /**
   * Disconnect both clients
   */
  async $disconnect() {
    await this.primary.$disconnect();
    if (this.readReplica) {
      await this.readReplica.$disconnect();
    }
  }

  /**
   * Health check for both connections
   */
  async healthCheck(): Promise<{ primary: boolean; replica: boolean }> {
    const results = { primary: false, replica: false };

    try {
      await this.primary.$queryRaw`SELECT 1`;
      results.primary = true;
    } catch {
      results.primary = false;
    }

    if (this.readReplica) {
      try {
        await this.readReplica.$queryRaw`SELECT 1`;
        results.replica = true;
      } catch {
        results.replica = false;
      }
    } else {
      results.replica = results.primary; // Same as primary if no replica
    }

    return results;
  }
}

// Singleton instance
const globalForPrisma = global as unknown as {
  prisma: PrismaClientWithReplicas;
};

export const prisma = globalForPrisma.prisma || new PrismaClientWithReplicas();

if (env.NODE_ENV !== 'production') {
  globalForPrisma.prisma = prisma;
}

// Backward-compatible default export
export const prismaClient = prisma.write;
export default prismaClient;

/**
 * Production Seed Script
 *
 * This script seeds the database with production-ready data:
 * - Admin user
 * - Sample edge nodes
 * - Sample tasks
 * - API keys
 * - Webhooks
 */

// @ts-nocheck
// This file contains seed data that requires schema alignment for full type safety

import { PrismaClient } from '@prisma/client';
import bcrypt from 'bcryptjs';
import { v4 as uuidv4 } from 'uuid';

import { env } from '../config/env';
import { seedLogger as logger } from '../lib/logger';

const prisma = new PrismaClient();

// Enum values from Prisma schema
const Role = {
  ADMIN: 'ADMIN',
  OPERATOR: 'OPERATOR',
  VIEWER: 'VIEWER',
} as const;

const NodeStatus = {
  ONLINE: 'ONLINE',
  OFFLINE: 'OFFLINE',
  DEGRADED: 'DEGRADED',
  MAINTENANCE: 'MAINTENANCE',
} as const;

const TaskType = {
  IMAGE_CLASSIFICATION: 'IMAGE_CLASSIFICATION',
  DATA_AGGREGATION: 'DATA_AGGREGATION',
  MODEL_INFERENCE: 'MODEL_INFERENCE',
  SENSOR_FUSION: 'SENSOR_FUSION',
  VIDEO_PROCESSING: 'VIDEO_PROCESSING',
  LOG_ANALYSIS: 'LOG_ANALYSIS',
  ANOMALY_DETECTION: 'ANOMALY_DETECTION',
  CUSTOM: 'CUSTOM',
} as const;

const TaskStatus = {
  PENDING: 'PENDING',
  SCHEDULED: 'SCHEDULED',
  RUNNING: 'RUNNING',
  COMPLETED: 'COMPLETED',
  FAILED: 'FAILED',
  CANCELLED: 'CANCELLED',
} as const;

const Priority = {
  CRITICAL: 'CRITICAL',
  HIGH: 'HIGH',
  MEDIUM: 'MEDIUM',
  LOW: 'LOW',
} as const;

const ExecutionTarget = {
  EDGE: 'EDGE',
  CLOUD: 'CLOUD',
  HYBRID: 'HYBRID',
} as const;

async function main() {
  logger.info('Starting production seed...');

  // Create admin user
  const adminPassword = await bcrypt.hash(
    env.ADMIN_PASSWORD || 'admin123',
    10,
  );
  const admin = await prisma.user.upsert({
    where: { email: 'admin@example.com' },
    update: {},
    create: {
      id: uuidv4(),
      email: 'admin@example.com',
      passwordHash: adminPassword,
      name: 'System Administrator',
      role: Role.ADMIN,
      isActive: true,
      emailVerified: true,
    },
  });
  logger.info({ email: admin.email }, 'Admin user created');

  // Create operator user
  const operatorPassword = await bcrypt.hash(
    env.OPERATOR_PASSWORD || 'operator123',
    10,
  );
  const operator = await prisma.user.upsert({
    where: { email: 'operator@example.com' },
    update: {},
    create: {
      id: uuidv4(),
      email: 'operator@example.com',
      passwordHash: operatorPassword,
      name: 'System Operator',
      role: Role.OPERATOR,
      isActive: true,
      emailVerified: true,
    },
  });
  logger.info({ email: operator.email }, 'Operator user created');

  // Create viewer user
  const viewerPassword = await bcrypt.hash(
    env.VIEWER_PASSWORD || 'viewer123',
    10,
  );
  const viewer = await prisma.user.upsert({
    where: { email: 'viewer@example.com' },
    update: {},
    create: {
      id: uuidv4(),
      email: 'viewer@example.com',
      passwordHash: viewerPassword,
      name: 'System Viewer',
      role: Role.VIEWER,
      isActive: true,
      emailVerified: true,
    },
  });
  logger.info({ email: viewer.email }, 'Viewer user created');

  // Create sample edge nodes
  const nodes = [
    {
      id: uuidv4(),
      name: 'edge-us-east-01',
      location: 'New York, USA',
      region: 'us-east-1',
      status: NodeStatus.ONLINE,
      ipAddress: '10.0.1.10',
      port: 4001,
      url: 'http://10.0.1.10:4001',
      cpuCores: 8,
      memoryGB: 32,
      storageGB: 500,
      cpuUsage: 45.2,
      memoryUsage: 62.5,
      storageUsage: 78.3,
      latency: 15,
      tasksRunning: 3,
      maxTasks: 20,
      costPerHour: 0.05,
      bandwidthInMbps: 1000,
      bandwidthOutMbps: 1000,
      isMaintenanceMode: false,
    },
    {
      id: uuidv4(),
      name: 'edge-us-west-01',
      location: 'San Francisco, USA',
      region: 'us-west-1',
      status: NodeStatus.ONLINE,
      ipAddress: '10.0.2.10',
      port: 4001,
      url: 'http://10.0.2.10:4001',
      cpuCores: 8,
      memoryGB: 32,
      storageGB: 500,
      cpuUsage: 32.1,
      memoryUsage: 45.8,
      storageUsage: 65.2,
      latency: 25,
      tasksRunning: 2,
      maxTasks: 20,
      costPerHour: 0.06,
      bandwidthInMbps: 1000,
      bandwidthOutMbps: 1000,
      isMaintenanceMode: false,
    },
    {
      id: uuidv4(),
      name: 'edge-eu-west-01',
      location: 'London, UK',
      region: 'eu-west-1',
      status: NodeStatus.ONLINE,
      ipAddress: '10.0.3.10',
      port: 4001,
      url: 'http://10.0.3.10:4001',
      cpuCores: 8,
      memoryGB: 32,
      storageGB: 500,
      cpuUsage: 28.5,
      memoryUsage: 38.2,
      storageUsage: 55.1,
      latency: 45,
      tasksRunning: 1,
      maxTasks: 20,
      costPerHour: 0.04,
      bandwidthInMbps: 1000,
      bandwidthOutMbps: 1000,
      isMaintenanceMode: false,
    },
    {
      id: uuidv4(),
      name: 'edge-apac-south-01',
      location: 'Singapore',
      region: 'apac-south-1',
      status: NodeStatus.ONLINE,
      ipAddress: '10.0.4.10',
      port: 4001,
      url: 'http://10.0.4.10:4001',
      cpuCores: 8,
      memoryGB: 32,
      storageGB: 500,
      cpuUsage: 52.3,
      memoryUsage: 68.7,
      storageUsage: 82.5,
      latency: 80,
      tasksRunning: 4,
      maxTasks: 20,
      costPerHour: 0.03,
      bandwidthInMbps: 1000,
      bandwidthOutMbps: 1000,
      isMaintenanceMode: false,
    },
  ];

  for (const node of nodes) {
    await prisma.edgeNode.upsert({
      where: { name: node.name },
      update: {},
      create: node,
    });
    logger.info({ node: node.name }, 'Edge node created');
  }

  // Create sample completed tasks
  const tasks = [
    {
      id: uuidv4(),
      name: 'Image Classification - Batch 001',
      type: TaskType.IMAGE_CLASSIFICATION,
      priority: Priority.HIGH,
      status: TaskStatus.COMPLETED,
      target: ExecutionTarget.EDGE,
      nodeId: nodes[0]?.id || 'unknown',
      policy: 'latency-aware',
      reason: 'Completed successfully',
      input: { images: ['img1.jpg', 'img2.jpg', 'img3.jpg'] },
      output: { results: [{ class: 'cat', confidence: 0.95 }] },
      maxRetries: 3,
      retryCount: 0,
      submittedAt: new Date(Date.now() - 3600000),
      startedAt: new Date(Date.now() - 3500000),
      completedAt: new Date(Date.now() - 3400000),
      duration: 100000,
    },
    {
      id: uuidv4(),
      name: 'Model Training - v2.0',
      type: TaskType.MODEL_INFERENCE,
      priority: Priority.CRITICAL,
      status: TaskStatus.RUNNING,
      target: ExecutionTarget.CLOUD,
      policy: 'cost-aware',
      reason: 'Training in progress',
      input: { dataset: 'production-v2', epochs: 100 },
      maxRetries: 3,
      retryCount: 0,
      submittedAt: new Date(Date.now() - 7200000),
      startedAt: new Date(Date.now() - 7100000),
    },
    {
      id: uuidv4(),
      name: 'Data Aggregation - Daily Report',
      type: TaskType.DATA_AGGREGATION,
      priority: Priority.MEDIUM,
      status: TaskStatus.PENDING,
      target: ExecutionTarget.EDGE,
      policy: 'load-balanced',
      input: { sources: ['logs', 'metrics', 'events'] },
      maxRetries: 3,
      retryCount: 0,
      submittedAt: new Date(Date.now() - 1800000),
    },
  ];

  for (const task of tasks) {
    await prisma.task.upsert({
      where: { id: task.id },
      update: {},
      create: task,
    });
    logger.info({ task: task.name }, 'Task created');
  }

  // Create API key for automation
  const apiKey = await prisma.apiKey.upsert({
    where: { key: `prod-api-key-${uuidv4().slice(0, 8)}` },
    update: {},
    create: {
      id: uuidv4(),
      userId: admin.id,
      name: 'Production Automation',
      key: `prod-api-key-${uuidv4().slice(0, 8)}`,
      permissions: ['nodes:read', 'nodes:create', 'tasks:read', 'tasks:create'],
      expiresAt: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000), // 1 year
    },
  });
  logger.info({ apiKey: apiKey.name }, 'API key created');

  // Create sample webhook
  const webhook = await prisma.webhook.upsert({
    where: { id: uuidv4() },
    update: {},
    create: {
      id: uuidv4(),
      name: 'Production Alerts',
      url: 'https://hooks.example.com/alerts',
      events: ['task.completed', 'task.failed', 'node.offline'],
      secret: `whsec_${uuidv4().replace(/-/g, '')}`,
      enabled: true,
    },
  });
  logger.info({ webhook: webhook.name }, 'Webhook created');

  // Create audit log entries
  await prisma.auditLog.create({
    data: {
      id: uuidv4(),
      userId: admin.id,
      action: 'system.seed',
      details: {
        message: 'Production seed completed',
        resource: 'database',
        resourceId: 'production',
      },
      ipAddress: '127.0.0.1',
      userAgent: 'seed-script',
    },
  });
  logger.info('Audit log entry created');

  logger.info('Production seed completed successfully!');
  logger.info(
    {
      credentials: {
        admin: 'admin@example.com',
        operator: 'operator@example.com',
        viewer: 'viewer@example.com',
      },
    },
    'Login credentials - Please change default passwords before deploying to production!',
  );
}

main()
  .catch((e) => {
    logger.error({ err: e }, 'Seed failed');
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

