/**
 * Service Initializer Module
 *
 * Safely initializes advanced services without breaking existing functionality.
 * All services are lazily loaded to avoid TypeScript compilation issues.
 */

import type { PrismaClient } from '@prisma/client';
import type { FastifyInstance } from 'fastify';
import type Redis from 'ioredis';
import type { Logger } from 'pino';

import { env } from '../config/env';
import { register as globalRegister } from '../services/metrics-service.js';

// Service instances
let autoHealer: any = null;
let healthMonitor: any = null;
let slaMonitor: any = null;
let costOptimizer: any = null;
let sagaOrchestrator: any = null;
let k8sOperator: any = null;
let modelStorage: any = null;
let workflowEngine: any = null;


/**
 * Initialize all advanced services
 */
export async function initializeServices(
  app: FastifyInstance,
  prisma: PrismaClient,
  redis: Redis,
  logger: Logger,
  idempotencyService?: unknown,
) {
  logger.info('Initializing advanced services...');

  // 0. Alerting Service - Basic alerting (log-based + optional webhook)
  try {
    const { initializeAlerting } =
      await import('../services/alerting-service.js');

    const alertWebhookUrl = env.ALERT_WEBHOOK_URL;
    const alertThrottleMs = env.ALERT_THROTTLE_MS;

    const alerting = initializeAlerting(logger, {
      logAlerts: true,
      webhookUrl: alertWebhookUrl,
      throttleMs: alertThrottleMs,
    });
    app.decorate('alerting', alerting);
    logger.info('✅ Alerting Service initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Alerting Service not initialized');
  }

  // 1. Auto-Healer - Automatic node recovery
  try {
    const { AutoHealer } = await import('../services/auto-healer.js');
    autoHealer = new AutoHealer(prisma, redis, logger);
    if (env.NODE_ENV !== 'test') {
      await autoHealer.start();
    }
    app.decorate('autoHealer', autoHealer);
    logger.info('✅ Auto-Healer initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Auto-Healer not initialized');
  }

  // 2. Health Monitor - Comprehensive health checks
  try {
    const { HealthMonitor } = await import('../services/health-monitor.js');
    healthMonitor = new HealthMonitor(prisma, redis, logger, {}, globalRegister);
    if (env.NODE_ENV !== 'test') {
      healthMonitor.start();
    }
    app.decorate('healthMonitor', healthMonitor);
    logger.info('✅ Health Monitor initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Health Monitor not initialized');
  }

  // 3. SLA Monitor - Service level tracking
  try {
    const { SLAMonitor } = await import('../services/sla-monitor.js');
    slaMonitor = new SLAMonitor(prisma, redis);
    app.decorate('slaMonitor', slaMonitor);
    logger.info('✅ SLA Monitor initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ SLA Monitor not initialized');
  }

  // 4. Cost Optimizer - Cost-aware scheduling
  try {
    const { CostOptimizer } = await import('../services/cost-optimizer.js');
    costOptimizer = new CostOptimizer();
    app.decorate('costOptimizer', costOptimizer);
    logger.info('✅ Cost Optimizer initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Cost Optimizer not initialized');
  }

  // 5. Saga Orchestrator - Distributed transactions
  try {
    const { SagaOrchestrator } = await import('@edgecloud/saga');
    const { createTaskLifecycleSaga } =
      await import('../sagas/task-lifecycle-saga.js');

    sagaOrchestrator = new SagaOrchestrator(prisma, {}, redis);

    // Register task lifecycle saga
    const scheduler = (app as unknown as any).taskScheduler;
    const taskSaga = createTaskLifecycleSaga(
      prisma, 
      logger, 
      idempotencyService,
      redis,
      scheduler ? (taskId, durationMs, status) => scheduler.recordTaskOutcome(taskId, durationMs, status) : undefined
    );
    sagaOrchestrator.registerSaga(taskSaga);

    // Start saga recovery
    sagaOrchestrator.startRecovery();

    app.decorate('sagaOrchestrator', sagaOrchestrator);
    logger.info('✅ Saga Orchestrator initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Saga Orchestrator not initialized');
  }

  // 6. Kubernetes Operator - K8s integration (only if KUBECONFIG exists)
  const kubeconfig = env.KUBECONFIG;
  if (kubeconfig) {
    try {
      const { EdgeCloudOperator } =
        await import('../services/kubernetes-operator.js');
      k8sOperator = new EdgeCloudOperator('edge-cloud-orchestrator');
      app.decorate('k8sOperator', k8sOperator);
      logger.info('✅ Kubernetes Operator initialized');
    } catch (error: any) {
      logger.warn(
        { err: error.message },
        '⚠️ Kubernetes Operator not initialized',
      );
    }
  }

  // 7. Model Storage Service - S3/GCS weights storage
  try {
    const { ModelStorageService } = await import('@edgecloud/ml-scheduler');
    const { globalCircuitBreakerRegistry } = await import('../utils/circuit-breakers.js');
    modelStorage = new ModelStorageService(globalCircuitBreakerRegistry);
    app.decorate('modelStorage', modelStorage);
    logger.info('✅ Model Storage Service initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Model Storage Service not initialized');
  }

  // 8. Cold Start Handler - Hybrid scheduling for new nodes
  try {
    const { ColdStartHandler } = await import('../services/cold-start-handler.js');
    const coldStartHandler = new ColdStartHandler(redis, prisma, logger);
    app.decorate('coldStartHandler', coldStartHandler);
    
    const scheduler = (app as any).taskScheduler;
    if (scheduler && typeof scheduler.setColdStartHandler === 'function') {
      scheduler.setColdStartHandler(coldStartHandler);
      logger.info('✅ Cold Start Handler integrated with TaskScheduler');
    }
    
    logger.info('✅ Cold Start Handler initialized');
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Cold Start Handler not initialized');
  }

  // 9. Workflow Engine - DAG-based task orchestration
  try {
    const { WorkflowEngine } = await import('../services/workflow-engine.js');
    const scheduler = (app as any).taskScheduler;
    const {wsManager} = (app as any);

    if (scheduler && wsManager) {
      workflowEngine = new WorkflowEngine(prisma, logger, scheduler, wsManager);
      app.decorate('workflowEngine', workflowEngine);
      logger.info('✅ Workflow Engine initialized');
    } else {
      logger.warn('⚠️ Workflow Engine requires TaskScheduler and WebSocketManager');
    }
  } catch (error: any) {
    logger.warn({ err: error.message }, '⚠️ Workflow Engine not initialized');
  }

  logger.info('Service initialization complete');
}

/**
 * Get status of all services
 */
export function getServiceStatus() {
  return {
    autoHealer: autoHealer !== null,
    healthMonitor: healthMonitor !== null,
    slaMonitor: slaMonitor !== null,
    costOptimizer: costOptimizer !== null,
    sagaOrchestrator: sagaOrchestrator !== null,
    kubernetesOperator: k8sOperator !== null,
    modelStorage: modelStorage !== null,
  };
}

/**
 * Graceful shutdown of services
 */
export async function shutdownServices(logger: Logger) {
  logger.info('Shutting down services...');

  if (autoHealer) {
    try {
      await autoHealer.stop();
    } catch (e) {}
  }
  if (healthMonitor) {
    try {
      healthMonitor.stop();
    } catch (e) {}
  }
  if (sagaOrchestrator) {
    try {
      sagaOrchestrator.stopRecovery();
    } catch (e) {}
  }

  logger.info('Services shutdown complete');
}

import { pino } from 'pino';
import { afterEach,beforeEach, describe, expect, it, vi } from 'vitest';

import * as metrics from '../../services/metrics-service';
import { ConsistencyCheckerJob } from '../consistency-checker';

// Mock metrics
vi.mock('../../services/metrics-service', () => ({
  consistencyViolationsTotal: { labels: vi.fn(() => ({ inc: vi.fn() })) },
  consistencyAutoFixesTotal: { labels: vi.fn(() => ({ inc: vi.fn() })) }
}));

// Mock AWS S3
vi.mock('@aws-sdk/client-s3', () => ({
  S3Client: vi.fn(() => ({ send: vi.fn() })),
  PutObjectCommand: vi.fn()
}));

describe('ConsistencyCheckerJob', () => {
  let prisma: any;
  let logger: any;
  let job: ConsistencyCheckerJob;

  beforeEach(() => {
    prisma = {
      $queryRawUnsafe: vi.fn(),
      auditLog: { create: vi.fn() },
      task: { updateMany: vi.fn() },
      edgeNode: { updateMany: vi.fn() },
      $transaction: vi.fn((cb) => (typeof cb === 'function' ? cb(prisma) : cb)),
    };
    logger = pino({ level: 'silent' });
    job = new ConsistencyCheckerJob(prisma, logger, 3);

    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.clearAllMocks();
    vi.useRealTimers();
  });

  it('should detect invariant violations and report them', async () => {
    // Mock violations for Invariant 1 (TASK_EXECUTION_SYNC)
    prisma.$queryRawUnsafe.mockImplementation((query: string) => {
      if (query.includes('tasks t') && query.includes('HAVING COUNT(te.id) != 1')) {
        return Promise.resolve([{ id: 'task-1', name: 'Broken Task', running_executions: 0 }]);
      }
      return Promise.resolve([]);
    });

    await job.run();

    // Verify detection
    expect(prisma.$queryRawUnsafe).toHaveBeenCalled();
    expect(metrics.consistencyViolationsTotal.labels).toHaveBeenCalledWith('TASK_EXECUTION_SYNC');

    // Verify audit log creation
    expect(prisma.auditLog.create).toHaveBeenCalledWith(expect.objectContaining({
      data: expect.objectContaining({
        action: 'CONSISTENCY_VIOLATION',
        tenantId: 'SYSTEM'
      })
    }));
  });

  it('should apply safe fixes for stuck tasks', async () => {
    // Mock stuck tasks for STUCK_SCHEDULING fix
    prisma.$queryRawUnsafe.mockImplementation((query: string) => {
      if (query.includes("status = 'SCHEDULED'") && query.includes("INTERVAL '10 minutes'")) {
        return Promise.resolve([{ id: 'task-stuck' }]);
      }
      return Promise.resolve([]);
    });

    prisma.task.updateMany.mockResolvedValue({ count: 1 });

    await job.run();

    // Verify fix was applied
    expect(prisma.task.updateMany).toHaveBeenCalledWith(expect.objectContaining({
      where: { id: { in: ['task-stuck'] } },
      data: expect.objectContaining({ status: 'PENDING' })
    }));

    // Verify metric emission
    expect(metrics.consistencyAutoFixesTotal.labels).toHaveBeenCalledWith('STUCK_SCHEDULING', 'success');
  });

  it('should handle offline nodes and reassign tasks', async () => {
    // Mock ghost node
    prisma.$queryRawUnsafe.mockImplementation((query: string) => {
      if (query.includes("status = 'ONLINE'") && query.includes("INTERVAL '5 minutes'")) {
        return Promise.resolve([{ id: 'node-dead' }]);
      }
      return Promise.resolve([]);
    });

    await job.run();

    // Verify node marked as OFFLINE
    expect(prisma.edgeNode.updateMany).toHaveBeenCalledWith(expect.objectContaining({
      where: { id: { in: ['node-dead'] } },
      data: { status: 'OFFLINE' }
    }));

    // Verify tasks reassigned
    expect(prisma.task.updateMany).toHaveBeenCalledWith(expect.objectContaining({
      where: { 
        nodeId: { in: ['node-dead'] },
        status: 'RUNNING'
      },
      data: expect.objectContaining({ status: 'PENDING' })
    }));
  });

  it('should schedule the job to run at the correct hour', async () => {
    const runSpy = vi.spyOn(job, 'run').mockResolvedValue();

    // Set time to 3:00 AM
    vi.setSystemTime(new Date('2024-01-01T03:00:00Z'));

    job.start();

    // Advance timers by more than 1 minute to ensure it ticks
    await vi.advanceTimersByTimeAsync(120000); 

    expect(runSpy).toHaveBeenCalled();
  });
});

import nock from 'nock';
import { pino } from 'pino';

import { WebhookRetryJob } from '../webhook-retry';


describe('WebhookRetryJob', () => {
  let prisma: any;
  let logger: any;
  let job: WebhookRetryJob;

  beforeEach(() => {
    prisma = {
      webhookDelivery: {
        findMany: vi.fn(),
        update: vi.fn(),
      },
      auditLog: {
        create: vi.fn(),
      },
      $transaction: vi.fn((cb) => (typeof cb === 'function' ? cb(prisma) : cb)),
    };
    logger = pino({ level: 'silent' });
    job = new WebhookRetryJob(prisma, logger, 60000, 5);

    // Enable system time mocking
    vi.useFakeTimers();
  });

  afterEach(() => {
    nock.cleanAll();
    vi.clearAllMocks();
    vi.useRealTimers();
  });

  it('should successfully retry a failed delivery', async () => {
    const delivery = {
      id: 'del-1',
      webhookId: 'web-1',
      tenantId: 'tenant-1',
      event: 'task.completed',
      payload: { foo: 'bar' },
      retryCount: 1,
      webhook: {
        url: 'https://example.com/webhook',
        secret: 'secret-key',
        enabled: true,
      },
    };

    prisma.webhookDelivery.findMany.mockResolvedValue([delivery]);

    const scope = nock('https://example.com')
      .post('/webhook', (body) => body.foo === 'bar')
      .reply(200, { success: true });

    await job.process();

    expect(scope.isDone()).toBe(true);
    expect(prisma.webhookDelivery.update).toHaveBeenCalledWith(expect.objectContaining({
      where: { id: 'del-1' },
      data: expect.objectContaining({
        status: 'DELIVERED',
        statusCode: 200,
      }),
    }));
  });

  it('should increment retry count and calculate exponential backoff on failure', async () => {
    const delivery = {
      id: 'del-2',
      webhookId: 'web-1',
      tenantId: 'tenant-1',
      event: 'task.completed',
      payload: { foo: 'bar' },
      retryCount: 1,
      webhook: {
        url: 'https://example.com/webhook',
        secret: 'secret-key',
        enabled: true,
      },
    };

    prisma.webhookDelivery.findMany.mockResolvedValue([delivery]);

    nock('https://example.com')
      .post('/webhook')
      .reply(500, 'Internal Server Error');

    const now = new Date('2024-01-01T12:00:00Z');
    vi.setSystemTime(now);

    await job.process();

    // nextRetryCount = 2
    // backoffMinutes = 2^2 = 4
    // backoffMs = 4 * 60000 = 240,000ms
    const expectedNextRetryAt = new Date(now.getTime() + 240000);

    expect(prisma.webhookDelivery.update).toHaveBeenCalledWith(expect.objectContaining({
      where: { id: 'del-2' },
      data: expect.objectContaining({
        retryCount: 2,
        nextRetryAt: expectedNextRetryAt,
      }),
    }));
  });

  it('should mark as DEAD_LETTERED and create audit log after max retries', async () => {
    const delivery = {
      id: 'del-3',
      webhookId: 'web-1',
      tenantId: 'tenant-1',
      event: 'task.completed',
      payload: { foo: 'bar' },
      retryCount: 4, // Next attempt will be the 5th (maxRetries)
      webhook: {
        url: 'https://example.com/webhook',
        secret: 'secret-key',
        enabled: true,
      },
    };

    prisma.webhookDelivery.findMany.mockResolvedValue([delivery]);

    nock('https://example.com')
      .post('/webhook')
      .reply(404, 'Not Found');

    await job.process();

    expect(prisma.webhookDelivery.update).toHaveBeenCalledWith(expect.objectContaining({
      where: { id: 'del-3' },
      data: expect.objectContaining({
        status: 'DEAD_LETTERED',
        retryCount: 5,
      }),
    }));

    expect(prisma.auditLog.create).toHaveBeenCalledWith(expect.objectContaining({
      data: expect.objectContaining({
        action: 'WEBHOOK_EXHAUSTED',
        entityId: 'del-3',
        tenantId: 'tenant-1'
      }),
    }));
  });

  it('should respect the batch size (take)', async () => {
    prisma.webhookDelivery.findMany.mockResolvedValue([]);

    await job.process();

    expect(prisma.webhookDelivery.findMany).toHaveBeenCalledWith(expect.objectContaining({
      take: 50
    }));
  });

  it('should skip retries for disabled webhooks', async () => {
    const delivery = {
      id: 'del-4',
      webhookId: 'web-1',
      webhook: {
        enabled: false,
        url: 'https://example.com/webhook'
      }
    };

    prisma.webhookDelivery.findMany.mockResolvedValue([delivery]);

    const scope = nock('https://example.com')
      .post('/webhook')
      .reply(200);

    await job.process();

    expect(scope.isDone()).toBe(false);
    expect(prisma.webhookDelivery.update).not.toHaveBeenCalled();
  });
});

import { PutObjectCommand,S3Client } from '@aws-sdk/client-s3';
import { 
  SAFE_FIXES, 
  SYSTEM_INVARIANTS} from '@edgecloud/shared-kernel';
import { PrismaClient } from '@prisma/client';
import { Logger } from 'pino';

import { 
  consistencyAutoFixesTotal, 
  consistencyViolationsTotal} from '../services/metrics-service';

export class ConsistencyCheckerJob {
  private interval: NodeJS.Timeout | null = null;
  private isProcessing = false;
  private s3Client: S3Client;
  private reportBucket: string;
  private lastRunDay: string | undefined = undefined;

  constructor(
    private prisma: PrismaClient,
    private logger: Logger,
    private readonly scheduleHour: number = 3, // Default 3 AM
  ) {
    this.reportBucket = process.env.REPORTS_BUCKET || 'edgecloud-reports';
    this.s3Client = new S3Client({
      region: process.env.AWS_REGION || 'us-east-1',
      credentials: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID || 'minioadmin',
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || 'minioadmin',
      },
      ...(process.env.S3_ENDPOINT ? { endpoint: process.env.S3_ENDPOINT } : {}),
      forcePathStyle: !!process.env.S3_ENDPOINT,
    });
  }

  /**
   * Start the background job with a 1-minute check interval
   */
  start(): void {
    if (this.interval) {return;}

    this.logger.info({ scheduleHour: this.scheduleHour }, 'Consistency checker job scheduled');

    this.interval = setInterval(() => {
      const now = new Date();
      const currentDay = now.toISOString().split('T')[0];
      const currentHour = now.getUTCHours();

      if (currentHour === this.scheduleHour && this.lastRunDay !== currentDay) {
        this.lastRunDay = currentDay;
        this.logger.info({ hour: currentHour, day: currentDay }, 'Triggering scheduled consistency check');
        this.run().catch((err) => {
          this.logger.error({ err }, 'Error in ConsistencyCheckerJob run');
        });
      }
    }, 60000); // Check every minute
  }

  stop(): void {
    if (this.interval) {
      clearInterval(this.interval);
      this.interval = null;
      this.logger.info('Consistency checker job stopped');
    }
  }

  /**
   * Run the consistency check suite
   */
  async run(): Promise<void> {
    if (this.isProcessing) {return;}
    this.isProcessing = true;

    const startTime = Date.now();
    const results: any = {
      timestamp: new Date().toISOString(),
      invariants: [],
      autoFixes: [],
      summary: {
        totalViolations: 0,
        fixedCount: 0,
        durationMs: 0
      }
    };

    this.logger.info('Starting system consistency check...');

    try {
      // 1. Run Invariant Checks
      for (const [_key, invariant] of Object.entries(SYSTEM_INVARIANTS)) {
        try {
          const violations = await this.prisma.$queryRawUnsafe(invariant.query);
          const violationCount = Array.isArray(violations) ? violations.length : 0;

          results.invariants.push({
            name: invariant.name,
            violated: violationCount > 0,
            violationCount,
            details: violations
          });

          if (violationCount > 0) {
            this.logger.warn({ invariant: invariant.name, count: violationCount }, 'Consistency violation detected');
            consistencyViolationsTotal.labels(invariant.name).inc(violationCount);

            // Log to audit log
            await this.prisma.auditLog.create({
              data: {
                action: 'CONSISTENCY_VIOLATION',
                entityType: 'System',
                details: { 
                  invariant: invariant.name, 
                  count: violationCount,
                  description: invariant.description
                } as any,
                tenantId: 'SYSTEM' // Global system tenant
              }
            });
          }
          results.summary.totalViolations += violationCount;
        } catch (err) {
          this.logger.error({ err, invariant: invariant.name }, 'Failed to run invariant check');
        }
      }

      // 2. Run Safe Fixes
      for (const [_key, fix] of Object.entries(SAFE_FIXES)) {
        try {
          const toFix: any[] = await this.prisma.$queryRawUnsafe(fix.query);
          if (toFix.length > 0) {
            const ids = toFix.map((item) => item.id);
            this.logger.info({ fix: fix.name, count: ids.length }, 'Applying auto-fix');

            try {
              await fix.fix(this.prisma, ids);
              results.autoFixes.push({
                name: fix.name,
                fixedCount: ids.length,
                status: 'SUCCESS'
              });
              consistencyAutoFixesTotal.labels(fix.name, 'success').inc(ids.length);
              results.summary.fixedCount += ids.length;
            } catch (fixErr) {
              this.logger.error({ err: fixErr, fix: fix.name }, 'Failed to apply auto-fix');
              results.autoFixes.push({
                name: fix.name,
                status: 'FAILED',
                error: fixErr instanceof Error ? fixErr.message : String(fixErr)
              });
              consistencyAutoFixesTotal.labels(fix.name, 'failure').inc(1);
            }
          }
        } catch (err) {
          this.logger.error({ err, fix: fix.name }, 'Failed to run auto-fix check');
        }
      }

      results.summary.durationMs = Date.now() - startTime;

      // 3. Upload Report to S3
      await this.uploadReport(results);

      this.logger.info(results.summary, 'Consistency check completed');

    } catch (error) {
      this.logger.error({ error }, 'Fatal error during consistency check');
    } finally {
      this.isProcessing = false;
    }
  }

  private async uploadReport(results: any): Promise<void> {
    const dateStr = new Date().toISOString().split('T')[0];
    const key = `consistency-reports/report-${dateStr}.json`;

    try {
      const command = new PutObjectCommand({
        Bucket: this.reportBucket,
        Key: key,
        Body: JSON.stringify(results, null, 2),
        ContentType: 'application/json'
      });

      await this.s3Client.send(command);
      this.logger.info({ key }, 'Consistency report uploaded to S3');
    } catch (err) {
      this.logger.error({ err }, 'Failed to upload consistency report to S3');
    }
  }
}

