import { validateWebhookUrl } from '@edgecloud/shared-kernel';
import { PrismaClient } from '@prisma/client';
import axios from 'axios';
import crypto from 'crypto';
import { Logger } from 'pino';

export class WebhookRetryJob {
  private interval: NodeJS.Timeout | null = null;
  private isProcessing = false;

  constructor(
    private prisma: PrismaClient,
    private logger: Logger,
    private readonly intervalMs: number = 60000,
    private readonly maxRetries: number = 5
  ) {}

  /**
   * Start the background job
   */
  start(): void {
    if (this.interval) {
      return;
    }

    this.interval = setInterval(() => {
      this.process().catch((err) => {
        this.logger.error({ err }, 'Unhandled error in WebhookRetryJob');
      });
    }, this.intervalMs);

    this.logger.info({ intervalMs: this.intervalMs }, 'Webhook retry job started');
  }

  /**
   * Stop the background job
   */
  stop(): void {
    if (this.interval) {
      clearInterval(this.interval);
      this.interval = null;
      this.logger.info('Webhook retry job stopped');
    }
  }

  /**
   * Process pending retries
   */
  async process(): Promise<void> {
    if (this.isProcessing) {
      return;
    }

    this.isProcessing = true;
    const now = new Date();

    try {
      const failedDeliveries = await this.prisma.webhookDelivery.findMany({
        where: {
          status: 'FAILED',
          retryCount: { lt: this.maxRetries },
          OR: [
            { nextRetryAt: { lte: now } },
            { nextRetryAt: null }
          ]
        },
        include: {
          webhook: true
        },
        take: 50 // Process in batches
      });

      if (failedDeliveries.length > 0) {
        this.logger.info({ count: failedDeliveries.length }, 'Processing failed webhook deliveries');
      }

      for (const delivery of failedDeliveries) {
        await this.attemptDelivery(delivery);
      }
    } catch (error) {
      this.logger.error({ error }, 'Error querying failed webhook deliveries');
    } finally {
      this.isProcessing = false;
    }
  }

  /**
   * Attempt a single delivery
   */
  private async attemptDelivery(delivery: any): Promise<void> {
    const { webhook, payload, event } = delivery;

    if (!webhook || !webhook.enabled) {
      this.logger.warn({ deliveryId: delivery.id, webhookId: delivery.webhookId }, 'Webhook disabled or missing, skipping retry');
      return;
    }

    const payloadString = JSON.stringify(payload);
    const signature = crypto
      .createHmac('sha256', webhook.secret || '')
      .update(payloadString)
      .digest('hex');

    // SSRF Protection
    const { safe, reason } = await validateWebhookUrl(webhook.url);
    if (!safe) {
      this.logger.error({ deliveryId: delivery.id, reason }, 'Webhook URL failed SSRF check at delivery time');
      await (this.prisma as any).webhookDelivery.update({
        where: { id: delivery.id },
        data: { 
          status: 'DEAD_LETTERED', 
          response: `SSRF_BLOCKED: ${reason}`
        }
      });
      return;
    }

    try {
      const response = await axios.post(webhook.url, payload, {
        headers: {
          'Content-Type': 'application/json',
          'X-Webhook-Signature': signature,
          'X-Webhook-Event': event,
          'X-Webhook-Delivery-Id': delivery.id,
          'User-Agent': 'EdgeCloud-Webhook/1.0'
        },
        timeout: 5000,           // 5 second timeout
        maxContentLength: 10240, // 10KB max response
        maxRedirects: 0          // No redirects
      });

      await this.prisma.webhookDelivery.update({
        where: { id: delivery.id },
        data: {
          status: 'DELIVERED',
          statusCode: response.status,
          response: typeof response.data === 'string' ? response.data : JSON.stringify(response.data),
          deliveredAt: new Date()
        }
      });

      this.logger.info({ deliveryId: delivery.id, webhookId: webhook.id }, 'Webhook delivery successful on retry');
    } catch (error: any) {
      const nextRetryCount = delivery.retryCount + 1;
      const statusCode = error.response?.status;
      const responseData = error.response?.data;
      const errorMessage = typeof responseData === 'string' ? responseData : JSON.stringify(responseData) || error.message;

      if (nextRetryCount >= this.maxRetries) {
        // Max retries exhausted
        await this.prisma.$transaction([
          this.prisma.webhookDelivery.update({
            where: { id: delivery.id },
            data: {
              status: 'DEAD_LETTERED',
              retryCount: nextRetryCount,
              statusCode,
              response: errorMessage
            }
          }),
          this.prisma.auditLog.create({
            data: {
              action: 'WEBHOOK_EXHAUSTED',
              entityType: 'WebhookDelivery',
              entityId: delivery.id,
              tenantId: delivery.tenantId,
              details: {
                webhookId: delivery.webhookId,
                event: delivery.event,
                finalError: errorMessage,
                finalStatus: statusCode,
                attempts: nextRetryCount
              }
            }
          })
        ]);

        this.logger.error({ deliveryId: delivery.id, webhookId: webhook.id }, 'Webhook delivery exhausted all retries');
      } else {
        // Calculate exponential backoff: 2^retryCount * 60s, capped at 1 hour
        const backoffMinutes = Math.pow(2, nextRetryCount);
        const backoffMs = Math.min(backoffMinutes * 60000, 3600000);
        const nextRetryAt = new Date(Date.now() + backoffMs);

        await this.prisma.webhookDelivery.update({
          where: { id: delivery.id },
          data: {
            retryCount: nextRetryCount,
            nextRetryAt,
            statusCode,
            response: errorMessage
          }
        });

        this.logger.warn(
          { deliveryId: delivery.id, nextRetryAt, retryCount: nextRetryCount },
          'Webhook delivery failed, scheduled next retry'
        );
      }
    }
  }
}

/**
 * Structured Logging with Pino
 *
 * This module configures structured logging for the application,
 * compatible with log aggregation systems like ELK/Loki.
 */

import { trace } from '@opentelemetry/api';
import pino from 'pino';

import { env } from '../config/env';

// Configure log level based on environment
const logLevel = env.LOG_LEVEL;
const logFormat = env.LOG_FORMAT;

// Create logger instance
export const logger = pino({
  level: logLevel,
  // Inject OpenTelemetry context automatically
  mixin() {
    const span = trace.getActiveSpan();
    if (!span) {return {};}

    const { traceId, spanId } = span.spanContext();
    return { traceId, spanId };
  },
  // Pretty print in development, JSON in production
  ...(logFormat === 'pretty' && env.NODE_ENV !== 'production'
    ? {
        transport: {
          target: 'pino-pretty',
          options: {
            colorize: true,
            translateTime: 'HH:MM:ss Z',
            ignore: 'pid,hostname',
          },
        },
      }
    : {}),
  // Add standard fields for log aggregation
  base: {
    service: 'edge-cloud-orchestrator',
    version: '1.0.0',
    environment: env.NODE_ENV,
  },
  // Redact sensitive fields
  redact: {
    paths: [
      'password',
      'passwordHash',
      'token',
      'refreshToken',
      'apiKey',
      'secret',
      'headers.authorization',
      'headers.cookie',
    ],
    remove: true,
  },
});

// Child loggers for specific components
export function createLogger(component: string) {
  return logger.child({ component });
}

// Request logging helper
export function logRequest(
  requestId: string,
  method: string,
  url: string,
  statusCode: number,
  duration: number,
  userId?: string,
) {
  const logData = {
    requestId,
    method,
    url,
    statusCode,
    duration,
    ...(userId && { userId }),
  };

  if (statusCode >= 500) {
    logger.error(logData, 'Request failed');
  } else if (statusCode >= 400) {
    logger.warn(logData, 'Request error');
  } else {
    logger.info(logData, 'Request completed');
  }
}

// Error logging helper
export function logError(
  error: Error,
  context: Record<string, unknown> = {},
  requestId?: string,
) {
  logger.error(
    {
      error: {
        name: error.name,
        message: error.message,
        stack: error.stack,
      },
      ...context,
      ...(requestId && { requestId }),
    },
    error.message,
  );
}

// Audit logging helper
export function logAudit(
  userId: string,
  action: string,
  resource: string,
  resourceId?: string,
  details?: Record<string, unknown>,
) {
  logger.info(
    {
      audit: true,
      userId,
      action,
      resource,
      resourceId,
      details,
      timestamp: new Date().toISOString(),
    },
    `Audit: ${action} on ${resource}`,
  );
}

// Performance logging helper
export function logPerformance(
  operation: string,
  duration: number,
  metadata?: Record<string, unknown>,
) {
  logger.info(
    {
      performance: true,
      operation,
      duration,
      ...metadata,
    },
    `Performance: ${operation} took ${duration}ms`,
  );
}

// Seed script logger (runs outside main app context)
export const seedLogger = pino({
  level: 'info',
  transport: {
    target: 'pino-pretty',
    options: {
      colorize: true,
      translateTime: 'HH:MM:ss Z',
      ignore: 'pid,hostname,service,version,environment',
    },
  },
});

import {
  Attributes,
  Context,
  Link,
  SpanKind,
} from '@opentelemetry/api';
import {
  Sampler,
  SamplingDecision,
  SamplingResult,
  TraceIdRatioBasedSampler,
} from '@opentelemetry/sdk-trace-base';

/**
 * CompositeSampler implements the advanced sampling strategy:
 * - Always sample: requests with X-Force-Trace: true header
 * - Sample 1% of: health check endpoints
 * - Sample 10% of: normal successful requests
 * 
 * NOTE: Sampling based on 5xx errors or latency > 500ms is typically handled
 * by a Tail Sampling Processor in the OTel Collector, as the outcome 
 * is unknown at the start of the span (Head Sampling).
 */
export class CompositeSampler implements Sampler {
  private ratioSampler: TraceIdRatioBasedSampler;
  private healthCheckSampler: TraceIdRatioBasedSampler;

  constructor(ratio = 0.1, healthRatio = 0.01) {
    this.ratioSampler = new TraceIdRatioBasedSampler(ratio);
    this.healthCheckSampler = new TraceIdRatioBasedSampler(healthRatio);
  }

  shouldSample(
    context: Context,
    traceId: string,
    spanName: string,
    spanKind: SpanKind,
    attributes: Attributes,
    links: Link[]
  ): SamplingResult {
    // 1. Check for X-Force-Trace header in attributes
    // Instrumentations often add headers to attributes
    const forceTrace = attributes['http.request.header.x_force_trace'] || 
                       attributes['x-force-trace'] ||
                       attributes['http.header.x-force-trace'];

    if (forceTrace === 'true') {
      return { decision: SamplingDecision.RECORD_AND_SAMPLED };
    }

    // 2. Health check endpoints (sample at 1%)
    const isHealthCheck = spanName.toLowerCase().includes('health') || 
                          (attributes['http.target'] as string)?.toLowerCase().includes('health') ||
                          (attributes['http.route'] as string)?.toLowerCase().includes('health');

    if (isHealthCheck) {
      return (this.healthCheckSampler as any).shouldSample(context, traceId, spanName, spanKind, attributes, links);
    }

    // 3. Default probabilistic sampling (10%)
    return (this.ratioSampler as any).shouldSample(context, traceId, spanName, spanKind, attributes, links);
  }

  toString(): string {
    return 'CompositeSampler';
  }
}

