/**
 * OpenTelemetry Distributed Tracing Setup
 *
 * This module configures distributed tracing for the application,
 * allowing request flows to be tracked across services.
 */

import { 
  getNodeAutoInstrumentations 
} from '@opentelemetry/auto-instrumentations-node';
import { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-grpc';
import { FastifyInstrumentation } from '@opentelemetry/instrumentation-fastify';
import { HttpInstrumentation } from '@opentelemetry/instrumentation-http';
import { PgInstrumentation } from '@opentelemetry/instrumentation-pg';
import { RedisInstrumentation } from '@opentelemetry/instrumentation-redis';
import { NodeSDK } from '@opentelemetry/sdk-node';
import { 
  BatchSpanProcessor,
  ParentBasedSampler, 
  ReadableSpan,
  SpanProcessor} from '@opentelemetry/sdk-trace-base';


import { env } from '../config/env';
import { createLogger } from './logger';
import { CompositeSampler } from './otel-sampler';
import type { FastifyInstance } from 'fastify';

const logger = createLogger('tracing');

/**
 * TailSamplingSpanProcessor for ML Scheduler
 * Discards spans for ML decisions that are fast (< 20ms) and didn't fallback.
 */
class TailSamplingSpanProcessor implements SpanProcessor {
  constructor(private delegate: SpanProcessor) {}

  onStart(span: any, parentContext: any): void {
    this.delegate.onStart(span, parentContext);
  }

  onEnd(span: ReadableSpan): void {
    if (span.name === 'scheduler:ml_decision') {
      const durationMs = (span.duration[0] * 1e9 + span.duration[1]) / 1e6;
      const isFallback = span.attributes['ml.fallback'] === true;

      if (durationMs < 20 && !isFallback) {
        return; // Discard
      }
    }
    this.delegate.onEnd(span);
  }

  forceFlush(): Promise<void> { return this.delegate.forceFlush(); }
  shutdown(): Promise<void> { return this.delegate.shutdown(); }
}

let sdk: NodeSDK | null = null;

export function initTracing(): void {
  const enabled = env.OTEL_ENABLED;

  if (!enabled) {
    logger.info('OpenTelemetry tracing disabled');
    return;
  }

  const serviceName = env.OTEL_SERVICE_NAME;
  const endpoint = env.OTEL_EXPORTER_OTLP_ENDPOINT;

  const traceExporter = new OTLPTraceExporter({
    url: endpoint,
  });

  const sampler = new ParentBasedSampler({
    root: new CompositeSampler(0.1, 0.01),
  });

  // Wrap batch processor with our tail sampling logic
  const batchProcessor = new BatchSpanProcessor(traceExporter);
  const tailProcessor = new TailSamplingSpanProcessor(batchProcessor);

  sdk = new NodeSDK({
    sampler,
    spanProcessor: tailProcessor,
    instrumentations: [
      getNodeAutoInstrumentations(),
      new FastifyInstrumentation(),
      new HttpInstrumentation(),
      new PgInstrumentation(),
      new RedisInstrumentation(),
    ],
    resource: {
      'service.name': serviceName,
      'service.version': '1.0.0',
      'deployment.environment': env.NODE_ENV,
    } as any,
  });

  sdk.start();
  logger.info({ serviceName, endpoint }, 'OpenTelemetry tracing enabled with advanced sampling');
}

export function shutdownTracing(): Promise<void> {
  if (sdk) {
    return sdk.shutdown();
  }
  return Promise.resolve();
}

// Middleware to add trace context to requests
export function tracingMiddleware(fastify: FastifyInstance): void {
  fastify.addHook('onRequest', async (request, reply) => {
    // Add trace ID to response headers for debugging
    const { span } = request as any;
    if (span) {
      void reply.header('X-Trace-Id', span.spanContext().traceId);      void reply.header('X-Span-Id', span.spanContext().spanId);    }
  });
}

// Helper to create custom spans
export async function withSpan<T>(
  name: string,
  operation: (span: any) => Promise<T>,
  attributes?: Record<string, string | number | boolean>,
): Promise<T> {
  const { trace } = await import('@opentelemetry/api');
  const tracer = trace.getTracer('edge-cloud-orchestrator');

  return tracer.startActiveSpan(name, async (span) => {
    try {
      if (attributes) {
        Object.entries(attributes).forEach(([key, value]) => {
          span.setAttribute(key, value);
        });
      }

      const result = await operation(span);
      span.setStatus({ code: 1 }); // OK
      return result;
    } catch (error) {
      span.setStatus({
        code: 2, // ERROR
        message: error instanceof Error ? error.message : 'Unknown error',
      });
      span.recordException(error as Error);
      throw error;
    } finally {
      span.end();
    }
  });
}

import { 
  createLogger, 
  enterWithTenantContext, 
  Permission, 
  RolePermissions} from '@edgecloud/shared-kernel';
import { FastifyReply, FastifyRequest } from 'fastify';
import jwt from 'jsonwebtoken';

import { env } from '../config/env';
import { UserPayload, UserRole } from '../types/fastify';

const logger = createLogger('api-auth');

export async function authenticate(
  request: FastifyRequest,
  reply: FastifyReply,
): Promise<void> {


  try {
    const authHeader = request.headers.authorization;

    if (!authHeader?.startsWith('Bearer ')) {
      // Check for API Key
      const apiKey = request.headers['x-api-key'] as string;
      if (apiKey) {
        const {apiKeyService} = (request as any).server;
        if (!apiKeyService) {
          throw new Error('apiKeyService not decorated on fastify instance');
        }
        const result = await apiKeyService.validateApiKey(apiKey);
        
        if (result) {
          request.user = {
            id: result.user.id,
            email: result.user.email,
            role: result.user.role,
            tenantId: result.user.tenantId,
            permissions: result.permissions || [],
          };

          if (result.user.tenantId) {
            enterWithTenantContext(result.user.tenantId);
          }
          return;
        }
      }

      return reply.status(401).send({ error: 'Authentication required' });
    }

    const token = authHeader.replace('Bearer ', '');
    const jwtSecret = env.JWT_SECRET;
    if (process.env.NODE_ENV === 'test') {
      logger.debug({ 
        jwtSecretPrefix: jwtSecret.substring(0, 5), 
        jwtSecretLength: jwtSecret.length,
        issuer: env.JWT_ISSUER,
        audience: env.JWT_AUDIENCE
      }, 'JWT middleware debug info');
    }
    const decoded = jwt.verify(token, jwtSecret, {
      issuer: env.JWT_ISSUER,
      audience: env.JWT_AUDIENCE,
      clockTolerance: 30,
    }) as UserPayload;

    // 1. Future iat check (30s tolerance)
    if (decoded.iat && decoded.iat > (Math.floor(Date.now() / 1000) + 30)) {
      return reply.status(401).send({ error: 'Token issued in the future' });
    }

    // 2. JTI Revocation Check (Redis)
    if (decoded.jti) {
      const {redis} = (request.server as any);
      if (redis) {
        if (process.env.NODE_ENV === 'test') {
          logger.debug({ 
            redisType: typeof redis, 
            isMock: redis.isMock, 
            hasGet: typeof redis.get === 'function' 
          }, 'Redis middleware debug info');
          if (typeof redis.get !== 'function') {
             logger.debug({ 
               redisKeys: Object.keys(redis),
               protoKeys: Object.keys(Object.getPrototypeOf(redis))
             }, 'Redis interface mismatch details');
          }
        }
        const isRevoked = await redis.get(`revoked_token:${decoded.jti}`);
        if (isRevoked) {
          return reply.status(401).send({ error: 'Access token has been revoked' });
        }
      }
    }


    request.user = {
      id: decoded.id,
      email: decoded.email,
      role: decoded.role as any,
      tenantId: decoded.tenantId,
      permissions: decoded.permissions || [],
    };

    if (decoded.tenantId) {
      enterWithTenantContext(decoded.tenantId);
    }
  } catch (error: any) {
    request.log.error({ error: error.message, stack: error.stack }, 'Authentication error');
    return reply.status(401).send({ 
      error: 'Authentication failed', 
      message: error.message,
      // In tests, include more info
      ...(process.env.NODE_ENV === 'test' ? { details: error.message } : {})
    });
  }
}

export function requireRole(...roles: UserRole[]) {
  return async (request: FastifyRequest, reply: FastifyReply) => {
    if (!request.user) {
      return reply.status(401).send({ error: 'Authentication required' });
    }

    // SUPER_ADMIN and ADMIN bypass all checks
    if ((request.user.role as any) === 'SUPER_ADMIN' || (request.user.role as any) === 'ADMIN') {
      return;
    }

    if (!roles.includes(request.user.role)) {
      logger.warn({
        userId: request.user.id,
        role: request.user.role,
        requiredRoles: roles,
        route: request.url,
      }, 'Authorization denied (role-based)');
      
      return reply.status(403).send({ error: 'Insufficient permissions' });
    }
  };
}

export function requirePermission(permission: Permission) {
  return async (request: FastifyRequest, reply: FastifyReply) => {
    if (!request.user) {
      return reply.status(401).send({ error: 'Authentication required' });
    }

    const {user} = request;
    const userPermissions = RolePermissions[user.role] ?? [];

    // Check for specific permission or global wildcard (from service tokens)
    const hasPermission = userPermissions.includes(permission) || 
                          user.permissions?.includes('*') ||
                          user.permissions?.includes(permission);

    if (!hasPermission) {
      logger.warn({
        userId: user.id,
        role: user.role,
        requiredPermission: permission,
        route: request.url,
      }, 'Authorization denied (permission-based)');

      return reply.status(403).send({ 
        error: 'Insufficient permissions',
        code: 'FORBIDDEN',
        required: permission
      });
    }
  };
}

// ============================================================================
// Authorization Middleware - RBAC Enforcement
// ============================================================================
//
// Provides role-based access control that MUST be applied to all protected routes.
// This middleware enforces authorization at the route level.
// ============================================================================

import { 
  createLogger, 
  Permission, 
  RolePermissions} from '@edgecloud/shared-kernel';
import { FastifyReply,FastifyRequest } from 'fastify';

import type { UserRole } from '../types/fastify';

const logger = createLogger('api-auth');

export class AuthorizationError extends Error {
  constructor(
    message: string,
    public requiredRoles: string[],
    public userRole?: string,
  ) {
    super(message);
    this.name = 'AuthorizationError';
  }
}

/**
 * Require specific roles for route access (Legacy support)
 */
export function authorize(...roles: UserRole[]) {
  return async function (request: FastifyRequest, reply: FastifyReply) {
    if (!request.user) {
      return reply.status(401).send({
        error: 'Authentication required',
        code: 'AUTH_REQUIRED',
      });
    }

    // SUPER_ADMIN or ADMIN can access everything
    if ((request.user.role as any) === 'SUPER_ADMIN' || (request.user.role as any) === 'ADMIN') {
      return;
    }

    if (!roles.includes(request.user.role)) {
      logger.warn({
        userId: request.user.id,
        role: request.user.role,
        requiredRoles: roles,
        route: request.url,
      }, 'Authorization denied (role-based)');

      throw new AuthorizationError(
        `Access denied. Required roles: ${roles.join(', ')}. Your role: ${request.user.role}`,
        roles,
        request.user.role,
      );
    }
  };
}

/**
 * Require specific permission for route access
 */
export function requirePermission(permission: Permission) {
  return async function (request: FastifyRequest, reply: FastifyReply) {
    if (!request.user) {
      return reply.status(401).send({
        error: 'Authentication required',
        code: 'AUTH_REQUIRED',
      });
    }

    const {user} = request;
    const userPermissions = RolePermissions[user.role] ?? [];

    // Check for specific permission or global wildcard (from service tokens)
    const hasPermission = userPermissions.includes(permission) || 
                          (user as any).permissions?.includes('*') ||
                          (user as any).permissions?.includes(permission);

    if (!hasPermission) {
      logger.warn({
        userId: user.id,
        role: user.role,
        requiredPermission: permission,
        route: request.url,
      }, 'Authorization denied (permission-based)');

      return reply.status(403).send({
        error: 'Insufficient permissions',
        code: 'FORBIDDEN',
        required: permission,
      });
    }
  };
}

/**
 * Require multiple permissions (Optional helper)
 */
export function requirePermissions(...permissions: Permission[]) {
  return async function (request: FastifyRequest, reply: FastifyReply) {
    for (const permission of permissions) {
      const handler = requirePermission(permission);
      await handler(request, reply);
    }
  };
}

/**
 * Resource ownership check
 * Ensures user can only access their own resources
 *
 * @param resourceIdParam - Name of URL parameter containing resource ID
 * @param getUserFromResource - Function to get owner ID from resource
 * @returns Fastify preHandler function
 */
export function requireOwnership(
  resourceIdParam: string,
  getUserFromResource: (resourceId: string) => Promise<string | null>,
) {
  return async function (request: FastifyRequest, reply: FastifyReply) {
    if (!request.user) {
      return reply.status(401).send({
        error: 'Authentication required',
        code: 'AUTH_REQUIRED',
      });
    }

    const resourceId = (request.params as Record<string, string>)[
      resourceIdParam
    ];

    if (!resourceId) {
      return reply.status(400).send({
        error: 'Resource ID required',
        code: 'INVALID_PARAM',
      });
    }

    const ownerId = await getUserFromResource(resourceId);

    if (!ownerId) {
      return reply.status(404).send({
        error: 'Resource not found',
        code: 'NOT_FOUND',
      });
    }

    // Admin can access any resource
    if ((request.user.role as any) === 'ADMIN') {
      return;
    }

    // Check if user owns the resource
    if (request.user.id !== ownerId) {
      throw new AuthorizationError(
        'You can only access your own resources',
        ['owner'],
        request.user.role,
      );
    }
  };
}

