import { ApiError } from '@edgecloud/shared-kernel';
import {
  FastifyError,
  FastifyInstance,
  FastifyReply,
  FastifyRequest,
} from 'fastify';
import fp from 'fastify-plugin';
import { ZodError } from 'zod';

import { env } from '../config/env';
import { apiErrorsTotal } from '../services/metrics-service';

/**
 * Global Error Handler Plugin
 * Standardizes all API errors into the ApiError schema and records metrics.
 */
export const errorHandler = fp(async (fastify: FastifyInstance) => {
  fastify.setErrorHandler(
    (
      error: FastifyError | Error & { statusCode?: number; code?: string },
      request: FastifyRequest,
      reply: FastifyReply,
    ) => {
      let statusCode = error.statusCode || 500;
      let code = 'INTERNAL_ERROR';
      let message = error.message || 'An unexpected error occurred';
      let details: unknown = undefined;

      // --- Mapping Logic ---

      // 1. Zod Validation Errors
      if (error instanceof ZodError || error.name === 'ZodError') {
        statusCode = 400;
        code = 'VALIDATION_ERROR';
        message = 'Validation failed';
        details = (error as any).errors.map((e: any) => ({
          path: e.path.join('.'),
          message: e.message,
          code: e.code,
        }));
      }

      // 2. Prisma Database Errors
      else if (error.name === 'PrismaClientKnownRequestError') {
        const prismaError = error as any;
        switch (prismaError.code) {
          case 'P2025': // Not found
            statusCode = 404;
            code = 'RESOURCE_NOT_FOUND';
            message = 'The requested resource was not found';
            break;
          case 'P2002': // Unique constraint violation
            statusCode = 409;
            code = 'RESOURCE_CONFLICT';
            message = 'A resource with this identifier already exists';
            details = { target: (error as any).meta?.target };
            break;
          default:
            statusCode = 500;
            code = 'DATABASE_ERROR';
            message = 'A database error occurred';
        }
      }

      // 3. Authentication & Authorization Errors
      else if (error.message?.includes('jwt') || error.message?.includes('token')) {
        statusCode = 401;
        if (error.message.includes('expired')) {
          code = 'TOKEN_EXPIRED';
          message = 'Your session has expired. Please log in again.';
        } else {
          code = 'TOKEN_INVALID';
          message = 'Invalid authentication token provided.';
        }
      } 
      else if (statusCode === 403 || error.message?.includes('permission')) {
        statusCode = 403;
        code = 'FORBIDDEN';
        message = 'You do not have permission to perform this action.';
      }

      // 4. Rate Limiting
      else if (statusCode === 429) {
        code = 'RATE_LIMIT_EXCEEDED';
        message = 'Too many requests. Please try again later.';
      }

      // 5. Explicit Fastify/Custom Errors
      else if (error.code === 'FST_ERR_VALIDATION') {
        statusCode = 400;
        code = 'VALIDATION_ERROR';
      }

      // Final sanitization for production
      if (statusCode === 500 && env.NODE_ENV === 'production') {
        message = 'An internal server error occurred';
      }

      const errorResponse: ApiError = {
        code,
        message,
        requestId: (request.headers['x-request-id'] as string) || (request.id) || 'unknown',
        timestamp: new Date().toISOString(),
        details,
        ...(env.NODE_ENV !== 'production' && { stack: error.stack }),
      };

      // Record Metrics
      const route = request.routeOptions?.url || request.url;
      apiErrorsTotal.labels(code, route, request.method).inc();

      // Log Error
      request.log.error({
        msg: 'API Error',
        requestId: request.id,
        code,
        statusCode,
        error: {
          message: error.message,
          stack: error.stack,
        },
      });

      return reply.status(statusCode).send(errorResponse);
    },
  );
});

export default errorHandler;

import { CircuitBreaker } from '@edgecloud/circuit-breaker';
import { prismaForTenant } from '@edgecloud/shared-kernel';
import { PrismaClient } from '@prisma/client';
import fp from 'fastify-plugin';
import { Histogram, register as globalRegister } from 'prom-client';

declare module 'fastify' {
  interface FastifyInstance {
    prisma: PrismaClient;
    dbCircuitBreaker: CircuitBreaker;
  }
}

// Helper to get or create metric
function getDbQueryDuration() {
  const name = 'db_query_duration_seconds';
  const existing = globalRegister.getSingleMetric(name);
  if (existing) {return existing as Histogram<string>;}
  
  return new Histogram({
    name,
    help: 'Duration of Database queries in seconds',
    labelNames: ['model', 'operation'],
    buckets: [0.001, 0.005, 0.01, 0.05, 0.1, 0.5, 1, 2, 5, 10],
  });
}

export const prismaPlugin = fp(
  async (fastify, options: { prisma: PrismaClient }) => {
    fastify.log.info('Initializing Prisma with resilience middleware...');
    
    const {isMock} = (options.prisma as any);
    const dbQueryDuration = getDbQueryDuration();

    // Create Circuit Breaker for DB - scoped to this plugin instance
    const dbCircuitBreaker = new CircuitBreaker({
      name: 'database',
      failureThreshold: 5,
      resetTimeout: 30000, // 30s
    });

    
    // 1. Add Scoped Tenant Extension
    let extendedPrisma = isMock ? options.prisma : prismaForTenant(options.prisma);

    // Common handler for all database operations
    const handleOperation = async ({ model, operation, args, query }: {
      model?: string;
      operation: string;
      args: unknown;
      query: (args: unknown) => Promise<unknown>;
    }) => {
      const start = Date.now();
      const modelName = model || 'none';
      
      try {
        // Execute within Circuit Breaker
        const result = await dbCircuitBreaker.execute(async () => {
          return query(args);
        });

        const duration = (Date.now() - start) / 1000;
        dbQueryDuration.observe({ model: modelName, operation }, duration);

        // Log slow queries
        if (duration > 0.1) { // 100ms
          fastify.log.warn({
            msg: 'Slow database query detected',
            model: modelName,
            operation,
            duration: `${duration}s`
          });
        }

        return result;
      } catch (error: any) {
        const duration = (Date.now() - start) / 1000;
        dbQueryDuration.observe({ model: modelName, operation }, duration);

        // If it's a circuit breaker open error, log it specifically
        if (error.name === 'CircuitBreakerOpenError') {
          fastify.log.error({
            msg: 'Database circuit breaker is OPEN. Rejecting query.',
            model: modelName,
            operation
          });
        }
        throw error;
      }
    };

    // 2. Add Observability and Resilience Extension
    extendedPrisma = extendedPrisma.$extends({
      query: {
        $allModels: {
          $allOperations: handleOperation
        },
        $queryRaw: handleOperation,
        $executeRaw: handleOperation,
        $queryRawUnsafe: handleOperation,
        $executeRawUnsafe: handleOperation
      },
    });
    
    if (!fastify.prisma) {
      fastify.decorate('prisma', extendedPrisma);
      fastify.decorate('dbCircuitBreaker', dbCircuitBreaker);
      fastify.log.info('Prisma and DB Circuit Breaker decorated successfully');
    }

    fastify.addHook('onClose', async () => {
      await options.prisma.$disconnect();
    });
  },
);

import fp from 'fastify-plugin';
