/**
 * Validate Redis connection is healthy
 */
export async function validateRedisConnection(redis: Redis): Promise<boolean> {
  try {
    await redis.ping();
    return true;
  } catch {
    return false;
  }
}

export const redisPlugin = fp(async (fastify, options: { redis: Redis }) => {
  // Validate connection before decorating
  const isHealthy = await validateRedisConnection(options.redis);

  if (!isHealthy) {
    if (env.NODE_ENV === 'production') {
      throw new Error('Redis connection validation failed');
    }
    fastify.log.warn(
      'Redis connection failed, continuing without Redis (development mode)',
    );
  }

  fastify.decorate('redis', options.redis);

  // Add health check endpoint
  fastify.get('/health/redis', async () => {
    const healthy = await validateRedisConnection(options.redis);
    return {
      status: healthy ? 'healthy' : 'unhealthy',
      service: 'redis',
    };
  });

  fastify.addHook('onClose', async () => {
    options.redis.disconnect();
  });
});

import { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';
import fp from 'fastify-plugin';

import { env } from '../config/env';

export const requestLogger = fp(async (fastify: FastifyInstance) => {
  fastify.addHook('onRequest', async (request: FastifyRequest) => {
    request.log.info({
      msg: 'Incoming request',
      method: request.method,
      url: request.url,
      ip: request.ip,
      userAgent: request.headers['user-agent'] ?? null,
    });
  });

  fastify.addHook(
    'onResponse',
    async (request: FastifyRequest, reply: FastifyReply) => {
      const responseTime = reply.elapsedTime;

      request.log.info({
        msg: 'Request completed',
        method: request.method,
        url: request.url,
        statusCode: reply.statusCode,
        responseTime: `${responseTime.toFixed(2)}ms`,
      });

      // Store request metrics in Redis for monitoring
      if (env.METRICS_ENABLED) {
        const date = new Date().toISOString().split('T')[0];
        const key = `metrics:requests:${date}`;

        await fastify.redis
          .multi()
          .hincrby(key, 'total', 1)
          .hincrby(key, `status:${Math.floor(reply.statusCode / 100)}xx`, 1)
          .hincrbyfloat(key, 'responseTime', responseTime)
          .expire(key, 86400 * 7) // Keep for 7 days
          .exec()
          .catch(() => {}); // Ignore errors
      }
    },
  );
});

