import { FastifyPluginAsync, FastifyReply,FastifyRequest } from 'fastify';
import fp from 'fastify-plugin';

/**
 * API Version Negotiation Plugin
 * Handles X-API-Version header and URL-based version validation.
 */

interface VersionNegotiationOptions {
  supportedVersions: string[];
  defaultVersion: string;
}

const versionNegotiationPluginInternal: FastifyPluginAsync<VersionNegotiationOptions> = async (
  fastify,
  options
) => {

  fastify.log.info('versionNegotiationPlugin executing...');
  const { supportedVersions, defaultVersion } = options;


  fastify.addHook('onRequest', async (request: FastifyRequest, reply: FastifyReply) => {
    const headerVersion = request.headers['x-api-version'];
    
    // Determine requested version from URL prefix if not in header
    // e.g., /v1/tasks -> v1
    const urlParts = request.url.split('/');
    const urlVersion = urlParts.find((p) => /^v\d+$/.test(p));

    const requestedVersion = (headerVersion as string) || urlVersion || defaultVersion;
    request.log.debug({ url: request.url, header: headerVersion, urlVersion, default: defaultVersion, requested: requestedVersion }, 'Version negotiation details');

    // Validate if the requested version is supported
    if (!supportedVersions.includes(requestedVersion)) {
      request.log.warn({ requestedVersion, supportedVersions }, 'Unsupported API version requested');
      
      return reply.code(400).send({
        error: 'unsupported_version',
        message: `API version ${requestedVersion} is not supported.`,
        supported: supportedVersions,
      });
    }

    // Ensure header matches URL version if both provided
    if (headerVersion && urlVersion && headerVersion !== urlVersion) {
      request.log.warn({ headerVersion, urlVersion }, 'API version mismatch between header and URL');
      
      return reply.code(400).send({
        error: 'version_mismatch',
        message: `API version in X-API-Version header (${headerVersion}) does not match URL version (${urlVersion}).`,
      });
    }

    // Decorate request with identified version
    request.apiVersion = requestedVersion;
    request.log.debug({ apiVersion: request.apiVersion }, 'Set request.apiVersion');
  });


  // Add deprecation headers for v1
  fastify.addHook('onSend', async (request, reply, payload) => {
    if (request.apiVersion === 'v1') {
      request.log.info({ url: request.url }, 'Adding deprecation headers to v1 request');
      void reply.header('Deprecation', 'true');      
      // Set sunset date to 6 months from now
      const sunsetDate = new Date();
      sunsetDate.setMonth(sunsetDate.getMonth() + 6);
      void reply.header('Sunset', sunsetDate.toUTCString());    }
    return payload;
  });


  // Decorate Fastify instance with versioning utils
  fastify.decorateRequest('apiVersion', '');
};

declare module 'fastify' {
  interface FastifyRequest {
    apiVersion: string;
  }
}

export const versionNegotiationPlugin = fp(versionNegotiationPluginInternal, {
  name: 'version-negotiation',
});

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

// ============================================================================
// TaskExecution Entity - Example Queries and Usage
// ============================================================================

/**
 * TASKEXECUTION ENTITY DESIGN
 *
 * Purpose: Separates "what to run" (Task) from "how it ran" (TaskExecution)
 *
 * Key Design Decisions:
 * 1. One Task can have multiple TaskExecutions (retries)
 * 2. Each execution captures actual metrics, not estimates
 * 3. Full lifecycle tracking: scheduled → started → completed
 * 4. Links to container runtime information
 * 5. Enables cost tracking and performance analytics
 */

// ============================================================================
// 1. BASIC CRUD OPERATIONS
// ============================================================================

/**
 * Create a new execution when task is scheduled
 */
async function createExecution(taskId: string, nodeId: string): Promise<void> {
  await prisma.taskExecution.create({
    data: {
      taskId,
      nodeId,
      status: 'SCHEDULED',
      scheduledAt: new Date(),
      attemptNumber: await getAttemptNumber(taskId),
      tenantId: 'system', // Default for background queries
    },
  });
}

/**
 * Update execution when container starts
 */
async function markExecutionStarted(
  executionId: string,
  containerId: string,
  image: string,
): Promise<void> {
  const now = new Date();

  await prisma.taskExecution.update({
    where: { id: executionId },
    data: {
      status: 'RUNNING',
      startedAt: now,
      containerId,
      image,
    },
  });
}

/**
 * Update execution when container completes
 */
async function markExecutionCompleted(
  executionId: string,
  result: {
    exitCode: number;
    output?: unknown;
    error?: string;
    durationMs: number;
    resourceUsage: {
      cpuAvg: number;
      cpuPeak: number;
      memoryMax: number;
      networkIn: number;
      networkOut: number;
    };
    cost: number;
  },
): Promise<void> {
  const status = result.exitCode === 0 ? 'COMPLETED' : 'FAILED';

  await prisma.taskExecution.update({
    where: { id: executionId },
    data: {
      status,
      completedAt: new Date(),
      durationMs: result.durationMs,
      exitCode: result.exitCode,
      output: result.output as any,
      error: result.error ?? null,
      cpuUsageAvg: result.resourceUsage.cpuAvg,
      cpuUsagePeak: result.resourceUsage.cpuPeak,
      memoryUsageMax: result.resourceUsage.memoryMax,
      networkIngressBytes: result.resourceUsage.networkIn,
      networkEgressBytes: result.resourceUsage.networkOut,
      costUSD: result.cost,
    },
  });
}

// ============================================================================
// 2. MONITORING QUERIES
// ============================================================================

/**
 * Get currently running executions
 */
async function getRunningExecutions(): Promise<any[]> {
  return prisma.taskExecution.findMany({
    where: { status: 'RUNNING' },
    include: {
      task: { select: { id: true, name: true, type: true, priority: true } },
      node: { select: { id: true, name: true, region: true } },
    },
    orderBy: { startedAt: 'desc' },
  });
}

/**
 * Get execution statistics for a time period
 */
async function getExecutionStats(
  startDate: Date,
  endDate: Date,
): Promise<{
  total: number;
  byStatus: Record<string, number>;
  avgDuration: number;
  avgCost: number;
  successRate: number;
}> {
  const executions = await prisma.taskExecution.findMany({
    where: {
      completedAt: { gte: startDate, lte: endDate },
    },
    select: {
      status: true,
      durationMs: true,
      costUSD: true,
    },
  });

  const total = executions.length;
  const completed = executions.filter((e) => e.status === 'COMPLETED').length;

  const byStatus = executions.reduce(
    (acc, e) => {
      acc[e.status] = (acc[e.status] || 0) + 1;
      return acc;
    },
    {} as Record<string, number>,
  );

  const durations = executions
    .filter((e) => e.durationMs)
    .map((e) => e.durationMs!);
  const avgDuration =
    durations.length > 0
      ? durations.reduce((a, b) => a + b, 0) / durations.length
      : 0;

  const costs = executions.filter((e) => e.costUSD).map((e) => e.costUSD!);
  const avgCost =
    costs.length > 0 ? costs.reduce((a, b) => a + b, 0) / costs.length : 0;

  return {
    total,
    byStatus,
    avgDuration,
    avgCost,
    successRate: total > 0 ? completed / total : 0,
  };
}

/**
 * Get executions that have been running too long (potential hangs)
 */
async function getStuckExecutions(
  maxDurationMinutes: number = 30,
): Promise<any[]> {
  const cutoff = new Date(Date.now() - maxDurationMinutes * 60 * 1000);

  return prisma.taskExecution.findMany({
    where: {
      status: 'RUNNING',
      startedAt: { lt: cutoff },
    },
    include: {
      task: { select: { id: true, name: true } },
      node: { select: { id: true, name: true } },
    },
  });
}

