import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';

type UserRoleStr = 'SUPER_ADMIN' | 'ADMIN' | 'OPERATOR' | 'VIEWER';

export default async function adminRoutes(fastify: FastifyInstance) {
  // Get audit logs
  fastify.get<{
    Querystring: { userId?: string; action?: string; limit?: number };
  }>(
    '/audit-logs',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.AUDIT_READ)],
      schema: {
        querystring: {
          type: 'object',
          properties: {
            userId: { type: 'string' },
            action: { type: 'string' },
            limit: { type: 'number', default: 100 },
          },
        },
        tags: ['admin'],
        summary: 'Get audit logs',
      },
    },
    async (request, _reply) => {
      const { userId, action, limit = 100 } = request.query;

      const logs = await (fastify.prisma as any).auditLog.findMany({
        where: {
          tenantId: request.user!.tenantId!,
          ...(userId && { userId }),
          ...(action && { action }),
        },
        orderBy: { createdAt: 'desc' },
        take: limit,
        include: {
          user: {
            select: { id: true, email: true, name: true },
          },
        },
      });

      return logs;
    },
  );

  // List users
  fastify.get(
    '/users',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.TENANT_MANAGE)],
      schema: {
        tags: ['admin'],
        summary: 'List all users',
      },
    },
    async (request, _reply) => {
      const users = await (fastify.prisma as any).user.findMany({
        where: {
          tenantUsers: {
            some: {
              tenantId: request.user!.tenantId!,
            },
          },
        },
        select: {
          id: true,
          email: true,
          name: true,
          role: true,
          isActive: true,
          emailVerified: true,
          createdAt: true,
          lastLoginAt: true,
          _count: { select: { sessions: true, apiKeys: true } },
        },
        orderBy: { createdAt: 'desc' },
      });

      return users;
    },
  );

  // Update user role
  fastify.patch<{ Params: { id: string }; Body: { role: UserRoleStr } }>(
    '/users/:id/role',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.TENANT_MANAGE)],
      schema: {
        params: {
          type: 'object',
          properties: {
            id: { type: 'string' },
          },
          required: ['id'],
        },
        body: {
          type: 'object',
          properties: {
            role: { type: 'string', enum: ['ADMIN', 'OPERATOR', 'VIEWER'] },
          },
          required: ['role'],
        },
        tags: ['admin'],
        summary: 'Update user role',
      },
    },
    async (request, reply) => {
      const { id } = request.params;
      const { role } = request.body;

      const currentUser = request.user as { id: string; tenantId: string };
      if (id === currentUser.id) {
        return reply.status(400).send({ 
          code: 'FORBIDDEN', 
          message: 'Cannot change your own role' 
        });
      }

      // Verify target user belongs to the same tenant
      const tenantUser = await (fastify.prisma as any).tenantUser.findFirst({
        where: {
          userId: id,
          tenantId: currentUser.tenantId,
        },
      });

      if (!tenantUser) {
        return reply.status(404).send({
          code: 'NOT_FOUND',
          message: 'User not found in your tenant',
        });
      }

      const user = await (fastify.prisma as any).user.update({
        where: { id },
        data: { role },
      });

      // Audit log
      await (fastify.prisma as any).auditLog.create({
        data: {
          userId: currentUser.id,
          tenantId: request.user!.tenantId!,
          action: 'user.role_changed',
          entityType: 'user',
          entityId: id,
          details: { newRole: role } as any,
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return user;
    },
  );

  // Deactivate user
  fastify.post<{ Params: { id: string } }>(
    '/users/:id/deactivate',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.TENANT_MANAGE)],
      schema: {
        params: {
          type: 'object',
          properties: {
            id: { type: 'string' },
          },
          required: ['id'],
        },
        tags: ['admin'],
        summary: 'Deactivate user',
      },
    },
    async (request, reply) => {
      const { id } = request.params;

      const currentUser = request.user as { id: string; tenantId: string };
      if (id === currentUser.id) {
        return reply.status(400).send({ 
          code: 'FORBIDDEN', 
          message: 'Cannot deactivate yourself' 
        });
      }

      // Verify target user belongs to the same tenant
      const tenantUser = await (fastify.prisma as any).tenantUser.findFirst({
        where: {
          userId: id,
          tenantId: currentUser.tenantId,
        },
      });

      if (!tenantUser) {
        return reply.status(404).send({
          code: 'NOT_FOUND',
          message: 'User not found in your tenant',
        });
      }

      const user = await (fastify.prisma as any).user.update({
        where: { id },
        data: { isActive: false },
      });

      // Invalidate all sessions
      await (fastify.prisma as any).session.deleteMany({ where: { userId: id } });

      return user;
    },
  );

  // Get system health
  fastify.get(
    '/health',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SYSTEM_READ)],
      schema: {
        tags: ['admin'],
        summary: 'Get system health',
      },
    },
    async (_request, _reply) => {
      const [dbHealth, redisHealth] = await Promise.all([
        fastify.prisma.$queryRaw`SELECT 1`
          .then(() => 'healthy')
          .catch(() => 'unhealthy'),
        fastify.redis
          .ping()
          .then(() => 'healthy')
          .catch(() => 'unhealthy'),
      ]);

      return {
        database: dbHealth,
        redis: redisHealth,
        timestamp: new Date().toISOString(),
      };
    },
  );

  // Clear old data
  fastify.post<{ Body: { olderThanDays: number; types: string[] } }>(
    '/cleanup',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.TENANT_MANAGE)],
      schema: {
        body: {
          type: 'object',
          properties: {
            olderThanDays: { type: 'number' },
            types: { type: 'array', items: { type: 'string' } },
          },
          required: ['olderThanDays', 'types'],
        },
        tags: ['admin'],
        summary: 'Clean up old data',
      },
    },
    async (request, _reply) => {
      const { olderThanDays, types } = request.body;
      const cutoff = new Date(Date.now() - olderThanDays * 24 * 60 * 60 * 1000);

      const results: Record<string, number> = {};

      if (types.includes('metrics')) {
        results.nodeMetrics = await fastify.prisma.nodeMetric
          .deleteMany({
            where: { 
              timestamp: { lt: cutoff },
              node: { tenantId: request.user!.tenantId! }
            },
          })
          .then((r: { count: number }) => r.count);
      }

      if (types.includes('logs')) {
        results.taskLogs = await fastify.prisma.taskLog
          .deleteMany({
            where: { 
              timestamp: { lt: cutoff },
              task: { tenantId: request.user!.tenantId! }
            },
          })
          .then((r: { count: number }) => r.count);
      }

      if (types.includes('webhookDeliveries')) {
        results.webhookDeliveries = await (fastify.prisma as any).webhookDelivery
          .deleteMany({
            where: { 
              createdAt: { lt: cutoff },
              tenantId: request.user!.tenantId!
            },
          })
          .then((r: { count: number }) => r.count);
      }

      if (types.includes('auditLogs')) {
        results.auditLogs = await (fastify.prisma as any).auditLog
          .deleteMany({
            where: { 
              createdAt: { lt: cutoff },
              tenantId: request.user!.tenantId!
            },
          })
          .then((r: { count: number }) => r.count);
      }

      return { deleted: results, cutoff: cutoff.toISOString() };
    },
  );

  // ML retrain endpoint
  fastify.post(
    '/ml/retrain',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_RETRAIN)],
      schema: {
        tags: ['admin'],
        summary: 'Trigger ML model retraining',
      },
    },
    async (_request, reply) => {
      const scheduler = (fastify as any).taskScheduler;
      if (!scheduler) {
        return reply.status(500).send({ 
          code: 'INTERNAL_ERROR', 
          message: 'TaskScheduler not initialized' 
        });
      }

      const { spawn } = await import('child_process');
      const path = await import('path');
      const fs = await import('fs');

      // 1. Extract data
      const trainingData = await scheduler.featureExtractor.extractTrainingData();
      if (trainingData.length < 50) {
        return reply.status(400).send({ 
          code: 'INSUFFICIENT_DATA', 
          message: 'Insufficient training data (need at least 50 samples)' 
        });
      }

      // 2. Write to temp file
      const tempPath = path.join(process.cwd(), 'temp_training_data.json');
      fs.writeFileSync(tempPath, JSON.stringify(trainingData));

      // 3. Spawn Python process
      const pythonScript = path.join(process.cwd(), '../../packages/ml-scheduler/src/training/train_model.py');
      const modelDir = path.join(process.cwd(), 'models');

      return new Promise((resolve, _reject) => {
        const pyProcess = spawn('python', [pythonScript, tempPath, modelDir]);
        
        let output = '';
        pyProcess.stdout.on('data', (data) => output += data.toString());
        pyProcess.stderr.on('data', (data) => output += data.toString());

        pyProcess.on('close', async (code) => {
          // Cleanup temp file
          if (fs.existsSync(tempPath)) {fs.unlinkSync(tempPath);}

          if (code !== 0) {
            fastify.log.error({ output }, 'ML retraining failed');
            return resolve(reply.status(500).send({ error: 'Training process failed', details: output }));
          }

          // Parse version from output or latest.json
          try {
            const latestPath = path.join(modelDir, 'latest.json');
            const latest = JSON.parse(fs.readFileSync(latestPath, 'utf-8'));
            
            // 4. Promote new model
            await scheduler.modelRegistry.promoteModel(latest.version);
            
            resolve({ 
              status: 'success', 
              version: latest.version, 
              mae: latest.mae 
            });
          } catch (e) {
            resolve(reply.status(500).send({ error: 'Failed to promote model', details: (e as Error).message }));
          }
        });
      });
    },
  );

  // ============================================
  // Event Republishing
  // ============================================

  // Single event republish
  fastify.post<{
    Body: {
      eventType: string;
      entityId: string;
      targetTopic?: string;
    };
  }>(
    '/events/republish',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.EVENT_REPUBLISH)],
      config: {
        rateLimit: { max: 10, timeWindow: 60000 },
      },
      schema: {
        body: {
          type: 'object',
          properties: {
            eventType: { type: 'string' },
            entityId: { type: 'string' },
            targetTopic: { type: 'string' },
          },
          required: ['eventType', 'entityId'],
        },
        tags: ['admin'],
        summary: 'Republish an event to Kafka',
      },
    },
    async (request, reply) => {
      const currentUser = request.user as { id: string; tenantId?: string; role: string };
      if (currentUser.tenantId && currentUser.tenantId !== 'SYSTEM') {
        return reply.status(403).send({ code: 'FORBIDDEN', message: 'Tenant-scoped tokens cannot republish events' });
      }

      const { eventType, entityId, targetTopic } = request.body;

      let payload: any = null;
      let defaultTopic = '';

      if (eventType === 'task.created') {
        const task = await (fastify.prisma as any).task.findUnique({ where: { id: entityId } });
        if (!task) {return reply.status(404).send({ error: 'Task not found' });}
        payload = {
          eventType: 'TaskCreated',
          taskId: task.id,
          name: task.name,
          type: task.type,
          priority: task.priority,
          target: task.targetNodeId || '',
          region: task.region || '',
          aggregateId: task.id,
          version: 1,
        };
        defaultTopic = 'tasks.events';
      } else if (eventType === 'node.registered') {
        const node = await (fastify.prisma as any).node.findUnique({ where: { id: entityId } });
        if (!node) {return reply.status(404).send({ error: 'Node not found' });}
        payload = {
          eventType: 'NodeRegistered',
          nodeId: node.id,
          name: node.name,
          region: node.region || '',
          capabilities: node.capabilities || [],
          aggregateId: node.id,
          version: 1,
        };
        defaultTopic = 'nodes.events';
      } else {
        return reply.status(400).send({ error: `Unsupported event type: ${eventType}` });
      }

      const topic = targetTopic || defaultTopic;

      // @ts-ignore
      const { EventBus } = await import('@edgecloud/event-bus');
      const { env } = await import('../config/env.js');
      const eventBus = new EventBus({
        clientId: 'admin-republisher',
        brokers: env.KAFKA_BROKERS.split(','),
      });
      await eventBus.connect();
      await eventBus.publish(topic, payload);
      await eventBus.disconnect();

      await (fastify.prisma as any).auditLog.create({
        data: {
          userId: currentUser.id,
          tenantId: 'SYSTEM',
          action: 'event.republished',
          entityType: 'event',
          entityId: entityId,
          details: { eventType, topic } as any,
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return { success: true, topic };
    }
  );

  // Bulk event republish
  fastify.post<{
    Body: {
      eventType: string;
      fromTimestamp: string;
      toTimestamp: string;
      dryRun?: boolean;
    };
  }>(
    '/events/republish-range',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.EVENT_REPUBLISH)],
      config: {
        rateLimit: { max: 10, timeWindow: 60000 },
      },
      schema: {
        body: {
          type: 'object',
          properties: {
            eventType: { type: 'string' },
            fromTimestamp: { type: 'string', format: 'date-time' },
            toTimestamp: { type: 'string', format: 'date-time' },
            dryRun: { type: 'boolean' },
          },
          required: ['eventType', 'fromTimestamp', 'toTimestamp'],
        },
        tags: ['admin'],
        summary: 'Bulk republish events to Kafka',
      },
    },
    async (request, reply) => {
      const currentUser = request.user as { id: string; tenantId?: string; role: string };
      if (currentUser.tenantId && currentUser.tenantId !== 'SYSTEM') {
        return reply.status(403).send({ code: 'FORBIDDEN', message: 'Tenant-scoped tokens cannot republish events' });
      }

      const { eventType, fromTimestamp, toTimestamp, dryRun } = request.body;
      const fromDate = new Date(fromTimestamp);
      const toDate = new Date(toTimestamp);

      if (isNaN(fromDate.getTime()) || isNaN(toDate.getTime())) {
        return reply.status(400).send({ error: 'Invalid timestamps' });
      }

      let entities: any[] = [];
      let defaultTopic = '';

      if (eventType === 'task.created') {
        entities = await (fastify.prisma as any).task.findMany({
          where: {
            createdAt: { gte: fromDate, lte: toDate },
          },
          take: 1000,
        });
        defaultTopic = 'tasks.events';
      } else if (eventType === 'node.registered') {
        entities = await (fastify.prisma as any).node.findMany({
          where: {
            createdAt: { gte: fromDate, lte: toDate },
          },
          take: 1000,
        });
        defaultTopic = 'nodes.events';
      } else {
        return reply.status(400).send({ error: `Unsupported event type: ${eventType}` });
      }

      if (dryRun) {
        return {
          count: entities.length,
          events: entities.slice(0, 10),
        };
      }

      // @ts-ignore
      const { EventBus } = await import('@edgecloud/event-bus');
      const { env } = await import('../config/env.js');
      const eventBus = new EventBus({
        clientId: 'admin-republisher-bulk',
        brokers: env.KAFKA_BROKERS.split(','),
      });
      await eventBus.connect();

      let published = 0;
      let failed = 0;
      const errors: string[] = [];

      for (const entity of entities) {
        try {
          let payload: any = null;
          if (eventType === 'task.created') {
            payload = {
              eventType: 'TaskCreated',
              taskId: entity.id,
              name: entity.name,
              type: entity.type,
              priority: entity.priority,
              target: entity.targetNodeId || '',
              region: entity.region || '',
              aggregateId: entity.id,
              version: 1,
            };
          } else if (eventType === 'node.registered') {
            payload = {
              eventType: 'NodeRegistered',
              nodeId: entity.id,
              name: entity.name,
              region: entity.region || '',
              capabilities: entity.capabilities || [],
              aggregateId: entity.id,
              version: 1,
            };
          }
          await eventBus.publish(defaultTopic, payload);
          published++;
        } catch (err) {
          failed++;
          errors.push(`Entity ${entity.id}: ${(err as any).message}`);
        }
      }

      await eventBus.disconnect();

      await (fastify.prisma as any).auditLog.create({
        data: {
          userId: currentUser.id,
          tenantId: 'SYSTEM',
          action: 'event.republished_bulk',
          entityType: 'event',
          entityId: 'range',
          details: { eventType, fromTimestamp, toTimestamp, published } as any,
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return { published, failed, errors };
    }
  );

  // ============================================

  // DLQ Monitoring Endpoints
  // ============================================

  // Get DLQ statistics
  fastify.get(
    '/dlq/stats',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.AUDIT_READ)],
      schema: {
        tags: ['admin'],
        summary: 'Get DLQ statistics across all streams',
      },
    },
    async (_request, _reply) => {
      const dbStats = await fastify.prisma.deadLetterEvent.groupBy({
        by: ['status'],
        _count: { id: true },
      });

      const byTopic = await fastify.prisma.deadLetterEvent.groupBy({
        by: ['originalTopic'],
        _count: { id: true },
        where: { status: 'PENDING' },
      });

      const stats: any = {
        totalEvents: 0,
        pendingRetry: 0,
        permanentlyFailed: 0,
        reprocessed: 0,
        byTopic: {} as Record<string, number>,
      };

      dbStats.forEach((s: { status: string; _count: { id: number } }) => {
        stats.totalEvents += s._count.id;
        if (s.status === 'PENDING') {stats.pendingRetry = s._count.id;}
        if (s.status === 'PERMANENTLY_FAILED') {stats.permanentlyFailed = s._count.id;}
        if (s.status === 'REPROCESSED') {stats.reprocessed = s._count.id;}
      });

      byTopic.forEach((t: { originalTopic: string; _count: { id: number } }) => {
        stats.byTopic[t.originalTopic] = t._count.id;
      });

      return stats;
    },
  );

  // List DLQ events
  fastify.get<{
    Querystring: {
      topic?: string;
      status?: 'PENDING' | 'RETRYING' | 'REPROCESSED' | 'PERMANENTLY_FAILED';
      limit?: number;
      offset?: number;
    };
  }>(
    '/dlq/events',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.AUDIT_READ)],
      schema: {
        querystring: {
          type: 'object',
          properties: {
            topic: { type: 'string' },
            status: { type: 'string', enum: ['PENDING', 'RETRYING', 'REPROCESSED', 'PERMANENTLY_FAILED'] },
            limit: { type: 'number', default: 50 },
            offset: { type: 'number', default: 0 },
          },
        },
        tags: ['admin'],
        summary: 'List DLQ events with filtering',
      },
    },
    async (request, _reply) => {
      const { topic, status, limit = 50, offset = 0 } = request.query;

      const where: any = {};
      if (topic) {where.originalTopic = topic;}
      if (status) {where.status = status;}

      const events = await (fastify.prisma as any).deadLetterEvent.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        take: limit,
        skip: offset,
      });

      const total = await (fastify.prisma as any).deadLetterEvent.count({ where });

      return {
        events,
        pagination: {
          total,
          limit,
          offset,
          hasMore: offset + limit < total,
        },
      };
    },
  );

  // Retry DLQ event
  fastify.post<{ Params: { id: string } }>(
    '/dlq/events/:id/retry',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.EVENT_REPUBLISH)],
      schema: {
        params: {
          type: 'object',
          properties: { id: { type: 'string' } },
          required: ['id'],
        },
        tags: ['admin'],
        summary: 'Retry a specific DLQ event',
      },
    },
    async (request, reply) => {
      const { id } = request.params;

      try {
        const event = await (fastify.prisma as any).deadLetterEvent.findUnique({
          where: { id },
        });

        if (!event) {
          return reply.status(404).send({ error: 'Event not found' });
        }

        if (event.status === 'REPROCESSED') {
          return reply.status(400).send({ error: 'Event already reprocessed' });
        }

        // Update status to RETRYING
        await (fastify.prisma as any).deadLetterEvent.update({
          where: { id },
          data: {
            status: 'RETRYING',
            attempts: { increment: 1 },
            lastAttemptAt: new Date(),
          },
        });

        try {
          // @ts-ignore
          const { EventBus } = await import('@edgecloud/event-bus');
          const { env } = await import('../config/env.js');
          const eventBus = new EventBus({
            clientId: 'admin-dlq-retry',
            brokers: env.KAFKA_BROKERS.split(','),
          });
          await eventBus.connect();
          await eventBus.publish(event.originalTopic, event.payload);
          await eventBus.disconnect();

          await (fastify.prisma as any).deadLetterEvent.update({
            where: { id },
            data: { status: 'REPROCESSED' }
          });
          return { success: true, eventId: id, message: 'Event successfully retried and published' };
        } catch (publishErr) {
          return reply.status(500).send({ error: 'Failed to republish event to Kafka', details: (publishErr as any).message });
        }
      } catch (err) {
        return reply.status(400).send({ error: (err as any).message });
      }
    },
  );

  // Purge old DLQ events
  fastify.post<{
    Body: { olderThanDays?: number };
  }>(
    '/dlq/purge',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.TENANT_MANAGE)],
      schema: {
        body: {
          type: 'object',
          properties: {
            olderThanDays: { type: 'number', default: 7 },
          },
        },
        tags: ['admin'],
        summary: 'Purge old DLQ events',
      },
    },
    async (request, _reply) => {
      const { olderThanDays = 7 } = request.body;

      const cutoff = new Date(Date.now() - olderThanDays * 24 * 60 * 60 * 1000);

      const result = await (fastify.prisma as any).deadLetterEvent.deleteMany({
        where: {
          status: { in: ['REPROCESSED', 'PERMANENTLY_FAILED'] },
          createdAt: { lt: cutoff },
        },
      });

      return { purged: result.count, olderThanDays };
    },
  );
}

import { trace } from '@opentelemetry/api';
import { FastifyInstance, FastifyPluginAsync } from 'fastify';

const agentRoutes: FastifyPluginAsync = async (fastify: FastifyInstance) => {
  const { AgentRegistrationService, CertificateAuthorityManager } = await import('../services/mtls-authentication.js');

  if (!(fastify as any).prisma) {
    fastify.log.error('Prisma client not found on fastify instance in agentRoutes');
  }
  const caManager = new CertificateAuthorityManager(fastify.prisma, fastify.log as any);
  const registrationService = new AgentRegistrationService(caManager, fastify.prisma, fastify.log as any);

  // Initialize CA on startup
  await caManager.initialize();

  /**
   * POST /v2/agents/certificates/sign
   * 
   * Bootstraps an agent by signing its CSR and registering the node.
   * Requires a valid one-time bootstrap token.
   */
  fastify.post(
    '/certificates/sign',
    {
      config: { public: true },
      schema: {
        tags: ['agents'],
        summary: 'Bootstrap agent certificate and register node',
        body: {
          type: 'object',
          required: ['csr', 'bootstrapToken', 'nodeName', 'region'],
          properties: {
            csr: { type: 'string', description: 'PEM encoded Certificate Signing Request' },
            bootstrapToken: { type: 'string', description: 'One-time bootstrap token' },
            nodeName: { type: 'string' },
            region: { type: 'string' },
            ipAddress: { type: 'string' },
            port: { type: 'number' },
            cpuCores: { type: 'number' },
            memoryGB: { type: 'number' },
            storageGB: { type: 'number' },
            hardwareId: { type: 'string' },
          },
        },
        response: {
          200: {
            type: 'object',
            properties: {
              certificate: { type: 'string' },
              caCertificate: { type: 'string' },
              nodeId: { type: 'string' },
              expiresAt: { type: 'string', format: 'date-time' },
            },
          },
          400: { $ref: 'ErrorSchema#' },
          401: { $ref: 'ErrorSchema#' },
          403: { $ref: 'ErrorSchema#' },
        },
      },
    },
    async (request, reply) => {
      try {
        const result = await registrationService.registerAgent(request.body as any);
        return result;
      } catch (error: unknown) {
        const err = error as Error;
        request.log.error({ err }, 'Agent registration failed');
        return reply.status(400).send({
          code: 'REGISTRATION_FAILED',
          message: err.message,
          requestId: request.id,
          timestamp: new Date().toISOString(),
        });
      }
    }
  );

  /**
   * GET /v2/agents/ca
   * 
   * Public endpoint to get the CA certificate for server verification.
   */
  fastify.get(
    '/ca',
    {
      config: { public: true },
      schema: {
        tags: ['agents'],
        summary: 'Get CA certificate',
        response: {
          200: {
            type: 'object',
            properties: {
              certificate: { type: 'string' },
            },
          },
        },
      },
    },
    async () => {
      return {
        certificate: caManager.getCACertificate(),
      };
    }
  );

  /**
   * GET /v2/agents/tasks/pending
   * 
   * Polls for the next pending task assigned to this agent.
   */
  fastify.get(
    '/tasks/pending',
    {
      config: { public: true },
      schema: {
        tags: ['agents'],
        summary: 'Poll for pending tasks',
        response: {
          200: {
            type: 'object',
            properties: {
              task_id: { type: 'string' },
              runtime: { type: 'string' },
              image: { type: 'string' },
              input: { type: 'object', additionalProperties: true },
              memory_limit_mb: { type: 'number' },
              cpu_fuel: { type: 'number', nullable: true },
              timeout_seconds: { type: 'number' },
            },
          },
          404: {
            type: 'object',
            properties: {
              message: { type: 'string' },
            },
          },
        },
      },
    },
    async (request, reply) => {
      // Extract nodeId from certificate
      const cert = (request.raw.socket as any).getPeerCertificate?.();
      
      // In production, we ONLY trust the certificate CN.
      // In development/test, we allow a header fallback if no certificate is present.
      const nodeId = cert?.subject?.CN || (process.env.NODE_ENV !== 'production' ? request.headers['x-node-id'] : null);

      if (!nodeId) {
        return reply.status(401).send({ error: 'Valid node certificate required' });
      }

      // Resolve tenant context for the node to enable Prisma tenant filtering
      const node = await fastify.prisma.edgeNode.findUnique({
        where: { id: nodeId as string },
        select: { tenantId: true }
      });

      if (!node) {
        return reply.status(401).send({ error: 'Node not registered or deactivated' });
      }

      // Set tenant context for this asynchronous execution branch
      const { enterWithTenantContext } = await import('@edgecloud/shared-kernel');
      enterWithTenantContext(node.tenantId);

      // Find oldest pending task assigned to this node
      const task = await fastify.prisma.task.findFirst({
        where: {
          nodeId: nodeId as string,
          status: 'PENDING',
        },
        orderBy: {
          priority: 'asc', // Higher priority first (if priority is mapped correctly)
          // or just FIFO:
          // submittedAt: 'asc'
        },
        include: {
          executions: {
            where: { status: 'PENDING' },
            take: 1,
          },
        },
      });

      if (!task) {
        return reply.status(404).send({ message: 'No tasks pending' });
      }

      // Map to TaskSpec format expected by agent
      const taskSpec = {
        task_id: task.id,
        runtime: task.type === 'IMAGE_CLASSIFICATION' ? 'wasm' : 'wasm', // Defaulting to wasm for now
        image: 'main.wasm', // In reality, this would be determined by task type/input
        input: task.input || {},
        memory_limit_mb: 512,
        cpu_fuel: null,
        timeout_seconds: 60,
        // Propagate trace context
        trace_id: (task as any).traceId || trace.getActiveSpan()?.spanContext().traceId,
        span_id: (task as any).spanId || trace.getActiveSpan()?.spanContext().spanId,
      };

      return taskSpec;
    }
  );

  /**
   * POST /v2/agents/heartbeat
   * 
   * Receives heartbeat and metrics from an agent.
   */
  fastify.post(
    '/heartbeat',
    {
      config: { public: true },
      schema: {
        tags: ['agents'],
        summary: 'Agent heartbeat',
        body: {
          type: 'object',
          properties: {
            timestamp: { type: 'number' },
            status: { type: 'string' },
            metrics: {
              type: 'object',
              properties: {
                cpu_usage: { type: 'number' },
                memory_usage: { type: 'number' },
              },
            },
          },
        },
      },
    },
    async (request, reply) => {
      const cert = (request.raw.socket as any).getPeerCertificate?.();
      const nodeId = cert?.subject?.CN || (process.env.NODE_ENV !== 'production' ? request.headers['x-node-id'] : null);

      if (!nodeId) {
        return reply.status(401).send({ error: 'Valid node certificate required' });
      }

      // Resolve tenant context
      const node = await fastify.prisma.edgeNode.findUnique({
        where: { id: nodeId as string },
        select: { tenantId: true }
      });

      if (!node) {return reply.status(401).send({ error: 'Node not found' });}
      const { enterWithTenantContext } = await import('@edgecloud/shared-kernel');
      enterWithTenantContext(node.tenantId);

      // Update node status and metrics
      const data = request.body as Record<string, unknown>;
      await fastify.prisma.edgeNode.update({
        where: { id: nodeId as string },
        data: {
          status: 'ONLINE',
          lastHeartbeat: new Date((data.timestamp as number) * 1000),
          // Optionally store metrics in NodeMetric table
        },
      });

      return { status: 'OK' };
    }
  );

  /**
   * POST /v2/agents/tasks/:taskId/status
   * 
   * Updates the status of a task execution (e.g. to RUNNING).
   */
  fastify.post(
    '/tasks/:taskId/status',
    {
      config: { public: true },
      schema: {
        tags: ['agents'],
        summary: 'Update task execution status',
        params: {
          type: 'object',
          required: ['taskId'],
          properties: {
            taskId: { type: 'string' },
          },
        },
        body: {
          type: 'object',
          required: ['status'],
          properties: {
            status: { type: 'string' },
          },
        },
      },
    },
    async (request, reply) => {
      const { taskId } = request.params as any;
      const { status } = request.body as any;
      const cert = (request.raw.socket as any).getPeerCertificate?.();
      const nodeId = cert?.subject?.CN || (process.env.NODE_ENV !== 'production' ? request.headers['x-node-id'] : null);

      if (!nodeId) {
        return reply.status(401).send({ error: 'Valid node certificate required' });
      }

      // Resolve tenant context
      const node = await fastify.prisma.edgeNode.findUnique({
        where: { id: nodeId as string },
        select: { tenantId: true }
      });
      if (!node) {return reply.status(401).send({ error: 'Node not found' });}
      
      const { enterWithTenantContext } = await import('@edgecloud/shared-kernel');
      enterWithTenantContext(node.tenantId);

      // Update task status to RUNNING in TaskExecution
      const execution = await fastify.prisma.taskExecution.findFirst({
        where: { taskId, nodeId: nodeId as string, status: { in: ['PENDING', 'SCHEDULED'] } },
        orderBy: { attemptNumber: 'desc' },
      });

      if (!execution) {
        // If it's already RUNNING, just return OK (idempotency)
        const alreadyRunning = await fastify.prisma.taskExecution.findFirst({
          where: { taskId, nodeId: nodeId as string, status: 'RUNNING' }
        });
        if (alreadyRunning) {return { status: 'OK' };}
        
        request.log.warn({ taskId, nodeId }, 'No pending or scheduled execution found for task status update');
        return reply.status(404).send({ error: 'No pending or scheduled execution found' });
      }

      await fastify.prisma.$transaction([
        fastify.prisma.taskExecution.update({
          where: { id: execution.id },
          data: { status: (status as string).toUpperCase() as any },
        }),
        fastify.prisma.task.update({
          where: { id: taskId },
          data: { status: (status as string).toUpperCase() as any },
        }),
      ]);

      return { status: 'OK' };
    }
  );

  /**
   * POST /v2/agents/tasks/:taskId/result
   * 
   * Receives the execution result of a task from an agent.
   */
  fastify.post(
    '/tasks/:taskId/result',
    {
      config: { public: true },
      schema: {
        tags: ['agents'],
        summary: 'Report task result',
        params: {
          type: 'object',
          required: ['taskId'],
          properties: {
            taskId: { type: 'string' },
          },
        },
        body: {
          type: 'object',
          required: ['status', 'exit_code'],
          properties: {
            status: { type: 'string' },
            exit_code: { type: 'number' },
            stdout: { type: 'string' },
            stderr: { type: 'string' },
            duration_ms: { type: 'number' },
            error: { type: 'string', nullable: true },
            metrics: {
              type: 'object',
              properties: {
                cpu_usage_avg: { type: 'number' },
                memory_usage_max: { type: 'number' },
                network_ingress_bytes: { type: 'number' },
                network_egress_bytes: { type: 'number' },
              }
            }
          },
        },
      },
    },
    async (request, reply) => {
      const { taskId } = request.params as any;
      const cert = (request.raw.socket as any).getPeerCertificate?.();
      const nodeId = cert?.subject?.CN || (process.env.NODE_ENV !== 'production' ? request.headers['x-node-id'] : null);

      if (!nodeId) {
        return reply.status(401).send({ error: 'Valid node certificate required' });
      }

      // Resolve tenant context
      const node = await fastify.prisma.edgeNode.findUnique({
        where: { id: nodeId as string },
        select: { tenantId: true }
      });

      if (!node) {return reply.status(401).send({ error: 'Node not found' });}
      const { enterWithTenantContext } = await import('@edgecloud/shared-kernel');
      enterWithTenantContext(node.tenantId);

      const result = request.body as Record<string, unknown>;
      const status = (result.status as string || 'FAILED').toUpperCase();

      // Update task and execution state in a transaction
      await fastify.prisma.$transaction(async (tx) => {
        // Find the execution record
        const execution = await tx.taskExecution.findFirst({
          where: { taskId, nodeId: nodeId as string, status: 'RUNNING' },
          orderBy: { attemptNumber: 'desc' },
        });

        if (execution) {
          request.log.info({ taskId, nodeId, executionId: execution.id, status }, 'Updating task execution result');
          await tx.taskExecution.update({
            where: { id: execution.id },
            data: {
              status: status as any,
              exitCode: result.exit_code as number,
              durationMs: result.duration_ms as number,
              error: result.error as string | null,
              completedAt: new Date(),
            },
          });
        } else {
          request.log.warn({ taskId, nodeId }, 'No RUNNING execution found for task result report');
          // If no running execution found for this node/task, reject
          throw new Error('No running execution found for this node and task');
        }

        await tx.task.update({
          where: { id: taskId },
          data: {
            status: status as any,
            nodeId: nodeId as string,
          },
        });
      });
      
      const metrics = result.metrics as Record<string, number> | undefined;
      fastify.taskScheduler.recordTaskOutcome(
        taskId,
        (result.duration_ms as number) || 0,
        status as any,
        metrics ? {
          cpuUsageAvg: metrics.cpu_usage_avg,
          memoryUsageMax: metrics.memory_usage_max,
          networkIngressBytes: metrics.network_ingress_bytes,
          networkEgressBytes: metrics.network_egress_bytes,
        } : undefined
      ).catch((err: Error) => request.log.error({ err, taskId }, 'Failed to record task outcome'));

      // Broadcast update
      fastify.wsManager.broadcast('task:updated', { id: taskId, status }, node.tenantId);

      return { status: 'OK' };
    }
  );
};

export default agentRoutes;

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';

import { getAlertingService } from '../services/alerting-service.js';

export default async function alertRoutes(fastify: FastifyInstance) {
  // Get alert history
  fastify.get<{
    Querystring: { severity?: 'critical' | 'warning' | 'info' };
  }>(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ALERT_READ)],
      schema: {
        tags: ['alerts'],
        summary: 'Get alert history',
        querystring: {
          type: 'object',
          properties: {
            severity: { type: 'string', enum: ['critical', 'warning', 'info'] },
          },
        },
      },
    },
    async (request, _reply) => {
      const alerting = getAlertingService();
      if (!alerting) {
        return { alerts: [] };
      }
      return { alerts: alerting.getAlertHistory(request.user!.tenantId!, request.query.severity) };
    },
  );

  // Clear alert history (admin only)
  fastify.delete(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ALERT_MANAGE)],
      schema: {
        tags: ['alerts'],
        summary: 'Clear alert history',
      },
    },
    async (request, reply) => {
      const alerting = getAlertingService();
      if (!alerting) {
        return reply.status(500).send({ 
          code: 'SERVICE_UNAVAILABLE', 
          message: 'Alerting not initialized' 
        });
      }
      alerting.clearHistory(request.user!.tenantId!);
      return { success: true, message: 'Alert history cleared' };
    },
  );

  // Test alert (admin only)
  fastify.post<{
    Body: {
      severity: 'critical' | 'warning' | 'info';
      title: string;
      message: string;
    };
  }>(
    '/test',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ALERT_MANAGE)],
      schema: {
        tags: ['alerts'],
        summary: 'Send test alert',
        body: {
          type: 'object',
          required: ['severity', 'title', 'message'],
          properties: {
            severity: { type: 'string', enum: ['critical', 'warning', 'info'] },
            title: { type: 'string' },
            message: { type: 'string' },
          },
        },
      },
    },
    async (request, reply) => {
      const alerting = getAlertingService();
      if (!alerting) {
        return reply.status(500).send({ 
          code: 'SERVICE_UNAVAILABLE', 
          message: 'Alerting not initialized' 
        });
      }

      await alerting.alert(
        request.body.severity,
        request.body.title,
        request.body.message,
        'test',
        request.user!.tenantId!,
      );

      return { success: true, message: 'Test alert sent' };
    },
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';

export default async function analyticsRoutes(fastify: FastifyInstance) {
  /**
   * GET /v2/analytics/cost
   * 
   * Returns aggregated cost analytics for the dashboard.
   */
  fastify.get(
    '/cost',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.COST_READ)],
      schema: {
        tags: ['analytics'],
        summary: 'Get cost analytics',
        querystring: {
          type: 'object',
          properties: {
            from: { type: 'string', format: 'date-time' },
            to: { type: 'string', format: 'date-time' },
            nodeId: { type: 'string' },
          }
        },
        response: {
          200: {
            type: 'object',
            properties: {
              totalActualCost: { type: 'number' },
              totalSavings: { type: 'number' },
              costByNode: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    nodeId: { type: 'string' },
                    nodeName: { type: 'string' },
                    cost: { type: 'number' },
                    taskCount: { type: 'number' }
                  }
                }
              },
              costOverTime: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    date: { type: 'string' },
                    cost: { type: 'number' }
                  }
                }
              }
            }
          }
        }
      }
    },
    async (request) => {
      const { from, to, nodeId } = request.query as { from?: string; to?: string; nodeId?: string };
      const tenantId = request.user!.tenantId!;

      const startTime = from ? new Date(from) : new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
      const endTime = to ? new Date(to) : new Date();

      // 1. Total Cost from TaskExecution
      const totalCostResult = await request.tPrisma.taskExecution.aggregate({
        where: {
          tenantId,
          completedAt: { gte: startTime, lte: endTime },
          status: 'COMPLETED',
          ...(nodeId && { nodeId })
        },
        _sum: { costUSD: true }
      });

      // 2. Cost By Node
      const costByNode = await request.tPrisma.taskExecution.groupBy({
        by: ['nodeId'],
        where: {
          tenantId,
          completedAt: { gte: startTime, lte: endTime },
          status: 'COMPLETED',
          ...(nodeId && { nodeId })
        },
        _sum: { costUSD: true },
        _count: { id: true }
      });

      // Enrich with node names
      const nodes = await request.tPrisma.edgeNode.findMany({
        where: { id: { in: costByNode.map(n => n.nodeId).filter((id): id is string => !!id) } },
        select: { id: true, name: true }
      });
      const nodeMap = nodes.reduce((acc: Record<string, string>, n) => ({ ...acc, [n.id]: n.name }), {});

      // 3. Cost Over Time (Daily)
      // Note: This is simplified. In production we'd use a more robust time-series query.
      const rawRecords = await request.tPrisma.costRecord.findMany({
        where: {
          tenantId,
          recordedAt: { gte: startTime, lte: endTime },
          ...(nodeId && { nodeId })
        },
        orderBy: { recordedAt: 'asc' }
      });

      const dailyMap = new Map<string, number>();
      rawRecords.forEach(r => {
        const date = r.recordedAt.toISOString().split('T')[0];
        if (date) {
          dailyMap.set(date, (dailyMap.get(date) || 0) + (Number(r.cost) || 0));
        }
      });

      const costOverTime = Array.from(dailyMap.entries()).map(([date, cost]) => ({
        date,
        cost: Math.round(cost * 100) / 100
      }));

      // 4. Savings Calculation (Estimated)
      // Placeholder: In a real system, we'd compare against a baseline (e.g. standard cloud pricing)
      const totalSavings = ((totalCostResult as any)._sum.costUSD || 0) * 0.25; // Assume 25% savings for now

      return {
        totalActualCost: Math.round(((totalCostResult as any)._sum.costUSD || 0) * 100) / 100,
        totalSavings: Math.round(totalSavings * 100) / 100,
        costByNode: costByNode.map(n => ({
          nodeId: n.nodeId || 'unknown',
          nodeName: (n.nodeId && nodeMap[n.nodeId]) || 'Unknown',
          cost: Math.round(((n as any)._sum.costUSD || 0) * 100) / 100,
          taskCount: (n as any)._count.id
        })),
        costOverTime
      };
    }
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';
import { z } from 'zod';

import { createApiKeySchema, idParamSchema } from '../schemas';
import { zodToFastifySchema } from '../utils/zod-schema';

export default async function apiKeyRoutes(fastify: FastifyInstance) {
  // List API keys for the current user
  fastify.get(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.API_KEY_MANAGE)],
      schema: {
        tags: ['api-keys'],
        summary: 'List my API keys',
      },
    },
    async (request, _reply) => {
      const apiKeys = await (fastify.prisma as any).apiKey.findMany({
        where: { userId: request.user!.id },
        select: {
          id: true,
          name: true,
          keyPrefix: true,
          permissions: true,
          expiresAt: true,
          createdAt: true,
          lastUsedAt: true,
        },
        orderBy: { createdAt: 'desc' },
      });

      return apiKeys;
    },
  );

  // Create API key
  fastify.post<{ Body: z.infer<typeof createApiKeySchema> }>(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.API_KEY_MANAGE)],
      schema: {
        body: zodToFastifySchema(createApiKeySchema),
        tags: ['api-keys'],
        summary: 'Create a new API key',
      },
    },
    async (request, reply) => {
      const { name, permissions, expiresAt } = request.body;
      const {apiKeyService} = (fastify as any);

      const result = await apiKeyService.createApiKey(
        request.user!.id,
        name,
        permissions
      );

      // Add expiresAt if provided
      if (expiresAt) {
        await (fastify.prisma as any).apiKey.update({
          where: { name_userId: { name, userId: request.user!.id } }, // Assuming unique constraint or find by name
          data: { expiresAt: new Date(expiresAt) },
        });
      }

      return reply.status(201).send(result);
    },
  );

  // Revoke API key
  fastify.delete<{ Params: { id: string } }>(
    '/:id',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.API_KEY_MANAGE)],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['api-keys'],
        summary: 'Revoke an API key',
      },
    },
    async (request, _reply) => {
      const {apiKeyService} = (fastify as any);
      await apiKeyService.revokeApiKey(request.params.id, request.user!.id);
      return { success: true };
    },
  );
}

