import { FastifyInstance, FastifyPluginAsync } from 'fastify';


import { AuthController } from '../controllers/auth.controller';
import { idParamSchema,loginSchema, refreshTokenSchema,registerSchema  } from '../schemas';
import { zodToFastifySchema } from '../utils/zod-schema';

const authRoutes: FastifyPluginAsync = async (fastify: FastifyInstance) => {
  // 1. Initialize Controller with decorated services
  const controller = new AuthController(
    fastify.authService,
    fastify.rateLimitService,
  );

  // 2. Register new user
  fastify.post(
    '/register',
    {
      config: { public: true },
      schema: {
        body: zodToFastifySchema(registerSchema),
        tags: ['auth'],
        summary: 'Register a new user',
        response: {
          400: { $ref: 'ErrorSchema#' },
          409: { $ref: 'ErrorSchema#' },
        },
      },
    },
    controller.register.bind(controller),
  );

  // 3. Login
  fastify.post(
    '/login',
    {
      config: { public: true },
      schema: {
        body: zodToFastifySchema(loginSchema),
        tags: ['auth'],
        summary: 'Login and get tokens',
        response: {
          401: { $ref: 'ErrorSchema#' },
          429: { $ref: 'ErrorSchema#' },
        },
      },
    },
    controller.login.bind(controller),
  );

  // 4. Refresh token
  fastify.post(
    '/refresh',
    {
      config: { public: true },
      schema: {
        body: zodToFastifySchema(refreshTokenSchema),
        tags: ['auth'],
        summary: 'Refresh access token',
      },
    },
    controller.refresh.bind(controller),
  );

  // 5. Logout
  fastify.post(
    '/logout',
    {
      preHandler: [async (req, reply) => { 
        if (typeof fastify.authenticate !== 'function') {
          throw new Error('fastify.authenticate is not a function. Auth plugin might not be registered correctly.');
        }
        return fastify.authenticate(req, reply); 
      }],
      schema: {

        tags: ['auth'],
        summary: 'Logout and invalidate session',
        response: {
          200: {
            type: 'object',
            properties: {
              success: { type: 'boolean' },
            },
          },
        },
      },
    },
    controller.logout.bind(controller),
  );

  // 6. Get current user
  fastify.get(
    '/me',
    {
      preHandler: [async (req, reply) => { 
        if (typeof fastify.authenticate !== 'function') {
          throw new Error('fastify.authenticate is not a function. Auth plugin might not be registered correctly.');
        }
        return fastify.authenticate(req, reply); 
      }],

      schema: {
        tags: ['auth'],
        summary: 'Get current user profile',
      },
    },
    controller.me.bind(controller),
  );

  // 7. Session management
  fastify.get(
    '/sessions',
    {
      preHandler: [fastify.authenticate],
      schema: {
        tags: ['auth'],
        summary: 'List active user sessions',
      },
    },
    controller.listSessions.bind(controller),
  );

  fastify.delete(
    '/sessions/:id',
    {
      preHandler: [fastify.authenticate],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['auth'],
        summary: 'Revoke a specific session',
      },
    },
    controller.revokeSession.bind(controller),
  );

  fastify.delete(
    '/sessions',
    {
      preHandler: [fastify.authenticate],
      schema: {
        tags: ['auth'],
        summary: 'Revoke all user sessions (logout everywhere)',
      },
    },
    controller.revokeAllSessions.bind(controller),
  );
};

export default authRoutes;

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance, FastifyReply,FastifyRequest } from 'fastify';

/**
 * Carbon & Eco-Scheduling Routes (v2)
 */
export default async function carbonRoutes(fastify: FastifyInstance) {
  const { taskScheduler } = fastify as any;

  // GET /api/v2/carbon/intensity
  fastify.get(
    '/intensity',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.CARBON_READ)],
      schema: {
        tags: ['carbon'],
        summary: 'Get regional carbon intensity',
        response: {
          200: {
            type: 'object',
            properties: {
              regions: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    zone: { type: 'string' },
                    carbonIntensityGco2: { type: 'number' },
                    lastUpdatedAt: { type: 'string' },
                    source: { type: 'string' }
                  }
                }
              }
            }
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      if (!taskScheduler) {return { regions: [] };}
      return taskScheduler.getCarbonIntensityData();
    }
  );

  // GET /api/v2/carbon/savings
  fastify.get(
    '/savings',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.CARBON_READ)],
      schema: {
        tags: ['carbon'],
        summary: 'Get carbon savings metrics',
        querystring: {
          type: 'object',
          properties: {
            days: { type: 'number', default: 7 }
          }
        },
        response: {
          200: {
            type: 'object',
            properties: {
              totalSavedGco2Today: { type: 'number' },
              totalSavedGco2Week: { type: 'number' },
              equivalentTreesPlanted: { type: 'number' },
              savingsHistory: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    date: { type: 'string' },
                    savedGco2: { type: 'number' }
                  }
                }
              }
            }
          }
        }
      },
    },
    async (request: FastifyRequest, _reply: FastifyReply) => {
      const { days } = (request.query as any) || { days: 7 };
      if (!taskScheduler) {return { totalSavedGco2Today: 0, totalSavedGco2Week: 0, equivalentTreesPlanted: 0, savingsHistory: [] };}
      return taskScheduler.getCarbonSavingsData(days);
    }
  );

  // GET /api/v2/carbon/policy
  fastify.get(
    '/policy',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.CARBON_READ)],
      schema: {
        tags: ['carbon'],
        summary: 'Get active carbon optimization policy',
        response: {
          200: {
            type: 'object',
            properties: {
              carbonWeight: { type: 'number' },
              isActive: { type: 'boolean' },
              activePolicy: { type: 'string' }
            }
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      if (!taskScheduler) {return { carbonWeight: 0.2, isActive: false, activePolicy: 'None' };}
      return taskScheduler.getCarbonPolicyData();
    }
  );

  // PATCH /api/v2/carbon/policy
  fastify.patch(
    '/policy',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.CARBON_POLICY_WRITE)],
      schema: {
        tags: ['carbon'],
        summary: 'Update carbon optimization weight',
        body: {
          type: 'object',
          required: ['carbonWeight'],
          properties: {
            carbonWeight: { type: 'number', minimum: 0, maximum: 1 }
          }
        },
        response: {
          200: {
            type: 'object',
            properties: {
              success: { type: 'boolean' },
              carbonWeight: { type: 'number' }
            }
          }
        }
      },
    },
    async (request: FastifyRequest, _reply: FastifyReply) => {
      const { carbonWeight } = request.body as any;
      if (!taskScheduler) {return { success: false, carbonWeight: 0 };}
      return taskScheduler.updateCarbonPolicy(carbonWeight);
    }
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';
import { z } from 'zod';

import { costQuerySchema } from '../schemas';
import { zodToFastifySchema } from '../utils/zod-schema';

export default async function costRoutes(fastify: FastifyInstance) {
  // Get cost summary
  fastify.get(
    '/summary',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.COST_READ)],
      schema: {
        tags: ['cost'],
        summary: 'Get cost summary',
      },
    },
    async (request, _reply) => {
      const now = new Date();
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
      const startOfLastMonth = new Date(
        now.getFullYear(),
        now.getMonth() - 1,
        1,
      );

      const [currentMonth, lastMonth, byResourceType] = await Promise.all([
        request.tPrisma.costRecord.aggregate({
          where: { 
            recordedAt: { gte: startOfMonth },
            tenantId: request.user!.tenantId!
          },
          _sum: { cost: true },
        }),
        request.tPrisma.costRecord.aggregate({
          where: {
            recordedAt: { gte: startOfLastMonth, lt: startOfMonth },
            tenantId: request.user!.tenantId!
          },
          _sum: { cost: true },
        }),
        request.tPrisma.costRecord.groupBy({
          by: ['resourceType'],
          where: { tenantId: request.user!.tenantId! },
          _sum: { cost: true },
        }),
      ]);

      const currentTotal = currentMonth._sum.cost || 0;
      const lastTotal = lastMonth._sum.cost || 0;
      const change =
        lastTotal > 0 ? ((currentTotal - lastTotal) / lastTotal) * 100 : 0;

      return {
        currentMonth: currentTotal,
        lastMonth: lastTotal,
        changePercent: change.toFixed(2),
        byResourceType: byResourceType.reduce(
          (acc: Record<string, number>, r) => ({
            ...acc,
            [r.resourceType]: Number(r._sum.cost) || 0,
          }),
          {},
        ),
      };
    },
  );

  // Get cost records
  fastify.get<{ Querystring: z.infer<typeof costQuerySchema> }>(
    '/records',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.COST_READ)],
      schema: {
        querystring: zodToFastifySchema(costQuerySchema),
        tags: ['cost'],
        summary: 'Get cost records',
      },
    },
    async (request, _reply) => {
      const {
        nodeId,
        resourceType,
        from,
        to,
        granularity: _granularity,
      } = request.query;

      const records = await request.tPrisma.costRecord.findMany({
        where: {
          tenantId: request.user!.tenantId!,
          ...(nodeId && { nodeId }),
          ...(resourceType && { resourceType }),
          ...(from && { recordedAt: { gte: new Date(from as string) } }),
          ...(to && { recordedAt: { lte: new Date(to as string) } }),
        },
        orderBy: { recordedAt: 'desc' },
        take: 1000,
      });

      return records;
    },
  );

  // Get cost by node
  fastify.get(
    '/by-node',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.COST_READ)],
      schema: {
        tags: ['cost'],
        summary: 'Get cost breakdown by node',
      },
    },
    async (request, _reply) => {
      const byNode = await request.tPrisma.costRecord.groupBy({
        by: ['nodeId'],
        where: { tenantId: request.user!.tenantId! },
        _sum: { cost: true },
        _count: true,
      });

      // Get node names
      const nodeIds = byNode.map(n => n.nodeId).filter((id): id is string => !!id);
      const nodes = await request.tPrisma.edgeNode.findMany({
        where: { id: { in: nodeIds }, tenantId: request.user!.tenantId! },
        select: { id: true, name: true, region: true },
      });

      const nodeMap = nodes.reduce(
        (acc: Record<string, (typeof nodes)[0]>, n) => ({ ...acc, [n.id]: n }),
        {} as Record<string, (typeof nodes)[0]>,
      );

      return byNode.map(n => ({
        nodeId: n.nodeId,
        node: n.nodeId ? nodeMap[n.nodeId] : null,
        totalCost: Number(n._sum.cost) || 0,
        recordCount: n._count,
      }));
    },
  );

  // Cost projections
  fastify.get(
    '/projections',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.COST_READ)],
      schema: {
        tags: ['cost'],
        summary: 'Get cost projections',
      },
    },
    async (request, _reply) => {
      const now = new Date();
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
      const dayOfMonth = now.getDate();
      const daysInMonth = new Date(
        now.getFullYear(),
        now.getMonth() + 1,
        0,
      ).getDate();

      const monthToDate = await request.tPrisma.costRecord.aggregate({
        where: { 
          recordedAt: { gte: startOfMonth },
          tenantId: request.user!.tenantId!
        },
        _sum: { cost: true },
      });

      const mtdCost = Number(monthToDate._sum.cost) || 0;
      const dailyAvg = mtdCost / dayOfMonth;
      const projectedMonth = dailyAvg * daysInMonth;

      return {
        monthToDate: mtdCost,
        dailyAverage: dailyAvg,
        projectedMonth,
        daysRemaining: daysInMonth - dayOfMonth,
      };
    },
  );
}

import { FastifyInstance } from 'fastify';
import { z } from 'zod';

import {
  createFLModelSchema,
  idParamSchema,
  startFLSessionSchema,
} from '../schemas';
import { zodToFastifySchema } from '../utils/zod-schema';

export default async function flRoutes(fastify: FastifyInstance) {
  // List models
  fastify.get(
    '/models',
    {
      preHandler: [fastify.authenticate],
      schema: { tags: ['federated-learning'], summary: 'List FL models' },
    },
    async (request) => {
      const models = await (fastify.prisma as any).fLModel.findMany({
        where: { tenantId: request.user!.tenantId! },
        include: {
          _count: { select: { sessions: true } },
        },
        orderBy: { createdAt: 'desc' },
      });
      return models;
    },
  );

  // Create model
  fastify.post<{ Body: z.infer<typeof createFLModelSchema> }>(
    '/models',
    {
      preHandler: [fastify.authenticate],
      schema: {
        body: zodToFastifySchema(createFLModelSchema),
        tags: ['federated-learning'],
        summary: 'Register a FL model',
      },
    },
    async (request, reply) => {
      const { name, version, architecture, parameters, weightsUrl, weightsSize } = request.body;

      const model = await (fastify.prisma as any).fLModel.create({
        data: { 
          name, 
          version, 
          architecture, 
          parameters, 
          weightsUrl: weightsUrl ?? null, 
          weightsSize: weightsSize ?? null, 
          tenantId: request.user!.tenantId! 
        },
      });

      return reply.status(201).send(model);
    },
  );

  // Get model
  fastify.get<{ Params: { id: string } }>(
    '/models/:id',
    {
      preHandler: [fastify.authenticate],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['federated-learning'],
        summary: 'Get FL model',
      },
    },
    async (request, reply) => {
      const model = await (fastify.prisma as any).fLModel.findUnique({
        where: { id: request.params.id, tenantId: request.user!.tenantId! },
        include: {
          sessions: {
            orderBy: { startedAt: 'desc' },
            take: 10,
          },
        },
      });

      if (!model) {
        return reply.status(404).send({ error: 'Model not found' });
      }

      return model;
    },
  );

  // Upload model weights
  fastify.post<{ Params: { id: string } }>(
    '/models/:id/weights',
    {
      preHandler: [fastify.authenticate],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['federated-learning'],
        summary: 'Upload weights for a FL model',
      },
    },
    async (request, reply) => {
      const data = await request.file();
      if (!data) {
        return reply.status(400).send({ error: 'No file uploaded' });
      }

      const buffer = await data.toBuffer();
      const modelId = request.params.id;

      const model = await (fastify.prisma as any).fLModel.findUnique({
        where: { id: modelId, tenantId: request.user!.tenantId! },
      });

      if (!model) {
        return reply.status(404).send({ error: 'Model not found' });
      }

      try {
        const { url: weightsUrl, checksum: weightsChecksum } = await (fastify as any).modelStorage.uploadWeights(modelId, buffer);

        await (fastify.prisma as any).fLModel.update({
          where: { id: modelId, tenantId: request.user!.tenantId! },
          data: {
            weightsUrl,
            weightsSize: buffer.length,
            weightsChecksum,
          },
        });

        return { success: true, weightsUrl, weightsChecksum, size: buffer.length };
      } catch (err: any) {
        fastify.log.error({ err }, 'Failed to upload weights to S3');
        return reply.status(500).send({ error: 'Storage backend error', details: err.message });
      }
    },
  );

  // Download model weights
  fastify.get<{ Params: { id: string } }>(
    '/models/:id/weights',
    {
      preHandler: [fastify.authenticate],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['federated-learning'],
        summary: 'Download weights for a FL model',
      },
    },
    async (request, reply) => {
      const model = await (fastify.prisma as any).fLModel.findUnique({
        where: { id: request.params.id, tenantId: request.user!.tenantId! },
      });

      if (!model || !model.weightsUrl) {
        return reply.status(404).send({ error: 'Weights not found' });
      }

      try {
        const buffer = await (fastify as any).modelStorage.downloadWeights(
          model.weightsUrl, 
          model.weightsChecksum || undefined
        );

        void reply.header('Content-Type', 'application/octet-stream');        void reply.header('Content-Disposition', `attachment; filename="weights_${model.version}.bin"`);        return reply.send(buffer);
      } catch (err: any) {
        fastify.log.error({ err }, 'Failed to download weights from S3');
        return reply.status(500).send({ error: 'Storage backend error', details: err.message });
      }
    },
  );

  // Start training session
  fastify.post<{ Body: z.infer<typeof startFLSessionSchema> }>(
    '/sessions',
    {
      preHandler: [fastify.authenticate],
      schema: {
        body: zodToFastifySchema(startFLSessionSchema),
        tags: ['federated-learning'],
        summary: 'Start FL training session',
      },
    },
    async (request, reply) => {
      const { modelId, totalRounds, config } = request.body;

      const model = await (fastify.prisma as any).fLModel.findUnique({
        where: { id: modelId, tenantId: request.user!.tenantId! },
      });

      if (!model) {
        return reply.status(404).send({ error: 'Model not found' });
      }

      const nodes = await (fastify.prisma.edgeNode as any).findMany({
        where: { status: 'ONLINE', isMaintenanceMode: false, tenantId: request.user!.tenantId! },
        take: config?.maxClients || 10,
      });

      if (nodes.length < (config?.minClients || 3)) {
        return reply.status(400).send({
          error: 'Insufficient clients',
          available: nodes.length,
          required: config?.minClients || 3,
        });
      }

      const session = await (fastify.prisma as any).fLSession.create({
        data: {
          modelId,
          totalRounds,
          config: (config as any) || {},
          status: 'RUNNING',
          tenantId: request.user!.tenantId!,
        },
      });

      return reply.status(201).send(session);
    },
  );

  // Get session
  fastify.get<{ Params: { id: string } }>(
    '/sessions/:id',
    {
      preHandler: [fastify.authenticate],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['federated-learning'],
        summary: 'Get FL session',
      },
    },
    async (request, reply) => {
      const session = await (fastify.prisma as any).fLSession.findUnique({
        where: { id: request.params.id, model: { tenantId: request.user!.tenantId! } },
        include: { model: true },
      });

      if (!session) {
        return reply.status(404).send({ error: 'Session not found' });
      }

      return session;
    },
  );

  // Stop session
  fastify.post<{ Params: { id: string } }>(
    '/sessions/:id/stop',
    {
      preHandler: [fastify.authenticate],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['federated-learning'],
        summary: 'Stop FL session',
      },
    },
    async (request) => {
      const session = await (fastify.prisma as any).fLSession.update({
        where: { id: request.params.id, model: { tenantId: request.user!.tenantId! } },
        data: {
          status: 'COMPLETED',
          completedAt: new Date(),
        },
      });

      return session;
    },
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';
import { z } from 'zod';

import { zodToFastifySchema } from '../utils/zod-schema.js';

const LogQuerySchema = z.object({
  taskId: z.string().optional(),
  nodeId: z.string().optional(),
  level: z.enum(['DEBUG', 'INFO', 'WARN', 'ERROR']).optional(),
  limit: z.coerce.number().default(100),
  offset: z.coerce.number().default(0),
});

export default async function logRoutes(fastify: FastifyInstance) {
  // Get global logs
  fastify.get(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.TASK_READ)],
      schema: {
        querystring: zodToFastifySchema(LogQuerySchema),
        tags: ['logs'],
        summary: 'Get system-wide logs',
      },
    },
    async (request, _reply) => {
      const { taskId, nodeId, level, limit, offset } = request.query as any;
      const tenantId = request.user!.tenantId!;

      const logs = await fastify.prisma.taskLog.findMany({
        where: {
          tenantId,
          ...(taskId ? { taskId } : {}),
          ...(nodeId ? { execution: { nodeId } } : {}),
          ...(level ? { level } : {}),
        },
        orderBy: { timestamp: 'desc' },
        take: limit,
        skip: offset,
        include: {
          task: { select: { name: true } },
        },
      });

      return logs;
    },
  );

  // Get log statistics
  fastify.get(
    '/stats',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.TASK_READ)],
      schema: {
        tags: ['logs'],
        summary: 'Get log statistics',
      },
    },
    async (request, _reply) => {
      const tenantId = request.user!.tenantId!;

      const [total, errors] = await Promise.all([
        fastify.prisma.taskLog.count({ where: { tenantId } }),
        fastify.prisma.taskLog.count({ 
          where: { 
            tenantId, 
            level: 'ERROR',
            timestamp: { gte: new Date(Date.now() - 24 * 60 * 60 * 1000) }
          } 
        }),
      ]);

      return {
        total,
        errorsLast24h: errors,
        storageUsageGB: 1.2,
      };
    },
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';

import { register } from '../services/metrics-service.js';

export default async function metricsRoutes(fastify: FastifyInstance) {
  // Helper to build system metrics response
  async function buildSystemMetrics(tenantId: string) {
    const [
      totalNodes,
      onlineNodes,
      totalTasks,
      pendingTasks,
      runningTasks,
      completedTasks,
      failedTasks,
    ] = await Promise.all([
      fastify.prisma.edgeNode.count({ where: { tenantId } }),
      fastify.prisma.edgeNode.count({ where: { status: 'online' as any, tenantId } }),
      fastify.prisma.task.count({ where: { tenantId } }),
      fastify.prisma.task.count({ where: { status: 'pending' as any, tenantId } }),
      fastify.prisma.task.count({ where: { status: 'running' as any, tenantId } }),
      fastify.prisma.task.count({ where: { status: 'completed' as any, tenantId } }),
      fastify.prisma.task.count({ where: { status: 'failed' as any, tenantId } }),
    ]);

    const avgLatency = await (fastify.prisma.edgeNode as any).aggregate({
      where: { status: 'online', tenantId },
      _avg: { latency: true },
    });

    const totalCost = await (fastify.prisma.costRecord as any).aggregate({
      where: { tenantId },
      _sum: { cost: true },
    });

    const offlineNodes = totalNodes - onlineNodes;
    const healthScore =
      totalNodes > 0 ? Math.round((onlineNodes / totalNodes) * 100) : 100;
    const completionRate =
      totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    return {
      totalNodes,
      onlineNodes,
      offlineNodes,
      degradedNodes: 0,
      totalTasks,
      pendingTasks,
      runningTasks,
      completedTasks,
      failedTasks,
      avgLatency: avgLatency._avg?.latency || 0,
      totalCost: totalCost._sum?.cost || 0,
      edgeUtilization: onlineNodes > 0 ? Math.min(95, runningTasks * 10) : 0,
      cloudUtilization: 30,
      throughput: completedTasks,
      healthScore,
      completionRate,
      cpuHistory: [],
      taskDistribution: {
        edge: Math.round(totalTasks * 0.6),
        cloud: Math.round(totalTasks * 0.4),
      },
      costOverTime: [],
      timestamp: new Date().toISOString(),
    };
  }

  // /api/metrics/system
  fastify.get(
    '/system',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SYSTEM_READ)],
      schema: { 
        tags: ['metrics'], 
        summary: 'Get system metrics',
        response: {
          401: { $ref: 'ErrorSchema#' }
        }
      },
    },
    async (request: FastifyRequest, _reply: FastifyReply) => {
      return buildSystemMetrics(request.user!.tenantId!);
    },
  );

  // /api/metrics
  fastify.get(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SYSTEM_READ)],
      schema: { tags: ['metrics'], summary: 'Get system metrics' },
    },
    async (request: FastifyRequest, _reply: FastifyReply) => {
      return buildSystemMetrics(request.user!.tenantId!);
    },
  );

  // /api/metrics/requests
  fastify.get(
    '/requests',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SYSTEM_READ)],
      schema: { tags: ['metrics'], summary: 'Get request metrics' },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      return {
        date: new Date().toISOString().split('T')[0],
        total: 0,
        responseTime: 0,
        status2xx: 0,
        status4xx: 0,
        status5xx: 0,
      };
    },
  );

  // /api/metrics/nodes
  fastify.get(
    '/nodes',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.NODE_READ)],
      schema: { tags: ['metrics'], summary: 'Get node metrics summary' },
    },
    async (request: FastifyRequest, _reply: FastifyReply) => {
      const nodes = await fastify.prisma.edgeNode.findMany({
        where: { status: 'online' as any, tenantId: request.user!.tenantId! },
      });
      return { total: nodes.length, nodes };
    },
  );

  // /api/metrics/ml
  fastify.get(
    '/ml',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_READ)],
      schema: { 
        tags: ['metrics'], 
        summary: 'Get ML-specific metrics',
        response: {
          200: {
            type: 'object',
            properties: {
              activeModels: { type: 'number' },
              trainingJobs: { type: 'number' },
              avgAccuracy: { type: 'number' },
              totalPredictions: { type: 'number' },
            },
          }
        }
      },
    },
    async (request: FastifyRequest, _reply: FastifyReply) => {
      const tenantId = request.user!.tenantId!;
      const [activeModels, trainingJobs] = await Promise.all([
        fastify.prisma.fLModel.count({ where: { tenantId, isActive: true } }),
        fastify.prisma.fLSession.count({ where: { tenantId, status: 'RUNNING' } }),
      ]);

      return {
        activeModels,
        trainingJobs,
        avgAccuracy: 0.94,
        totalPredictions: 12500,
      };
    },
  );

  // /api/metrics/network
  fastify.get(
    '/network',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SYSTEM_READ)],
      schema: { 
        tags: ['metrics'], 
        summary: 'Get network performance metrics',
        response: {
          200: {
            type: 'object',
            properties: {
              ingressGbps: { type: 'number' },
              egressGbps: { type: 'number' },
              avgLatency: { type: 'number' },
              packetLoss: { type: 'number' },
            },
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      return {
        ingressGbps: 1.2,
        egressGbps: 0.8,
        avgLatency: 45,
        packetLoss: 0.01,
      };
    },
  );

  // Prometheus metrics endpoint - /api/metrics/prometheus
  fastify.get(
    '/prometheus',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SYSTEM_READ)],
      schema: {
        tags: ['metrics'],
        summary: 'Get Prometheus metrics',
        description: 'Returns metrics in Prometheus exposition format',
      },
    },
    async (_request: FastifyRequest, reply: FastifyReply) => {
      const metrics = await register.metrics();
      void reply.header('Content-Type', register.contentType);      return metrics;
    },
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance, FastifyReply,FastifyRequest } from 'fastify';

/**
 * ML Pipeline Monitoring Routes (v2)
 */
export default async function mlRoutes(fastify: FastifyInstance) {
  const { taskScheduler } = fastify as any;

  // GET /api/v2/ml/drift/current
  fastify.get(
    '/drift/current',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_READ)],
      schema: {
        tags: ['ml'],
        summary: 'Get current ML drift status',
        response: {
          200: {
            type: 'object',
            properties: {
              driftScore: { type: 'number' },
              isDrifting: { type: 'boolean' },
              lastCheckedAt: { type: 'string' },
              featureDrift: { type: 'object', additionalProperties: { type: 'number' } }
            }
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      if (!taskScheduler) {return { driftScore: 0, isDrifting: false, lastCheckedAt: new Date().toISOString(), featureDrift: {} };}
      return await taskScheduler.getMLDriftState();
    }
  );

  // GET /api/v2/ml/drift/history
  fastify.get(
    '/drift/history',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_READ)],
      schema: {
        tags: ['ml'],
        summary: 'Get ML drift history',
        querystring: {
          type: 'object',
          properties: {
            hours: { type: 'number', default: 24 }
          }
        },
        response: {
          200: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                timestamp: { type: 'string' },
                score: { type: 'number' }
              }
            }
          }
        }
      },
    },
    async (request: FastifyRequest, _reply: FastifyReply) => {
      const { hours } = (request.query as any) || { hours: 24 };
      if (!taskScheduler) {return [];}
      return taskScheduler.getMLDriftHistory(hours);
    }
  );

  // GET /api/v2/ml/model/current
  fastify.get(
    '/model/current',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_READ)],
      schema: {
        tags: ['ml'],
        summary: 'Get current ML model status',
        response: {
          200: {
            type: 'object',
            properties: {
              version: { type: 'string' },
              trainedAt: { type: 'string' },
              accuracy: { type: 'number' },
              fallbackRate: { type: 'number' },
              lastUpdatedAt: { type: 'string' },
              modelType: { type: 'string' }
            }
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      if (!taskScheduler) {return null;}
      return taskScheduler.getMLModelCurrent();
    }
  );

  // GET /api/v2/ml/outcomes/stats
  fastify.get(
    '/outcomes/stats',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_READ)],
      schema: {
        tags: ['ml'],
        summary: 'Get ML outcome collection stats',
        response: {
          200: {
            type: 'object',
            properties: {
              outcomesBuffered: { type: 'number' },
              banditExplorationRate: { type: 'number' },
              predictionErrorP99Ms: { type: 'number' },
              nextUpdateAt: { type: 'number' }
            }
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      if (!taskScheduler) {return { outcomesBuffered: 0, banditExplorationRate: 0.1, predictionErrorP99Ms: 0, nextUpdateAt: 500 };}
      return taskScheduler.getMLOutcomeStats();
    }
  );

  // POST /api/v2/ml/retrain
  fastify.post(
    '/retrain',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_RETRAIN)],
      schema: {
        tags: ['ml'],
        summary: 'Manually trigger model retraining',
        response: {
          200: {
            type: 'object',
            properties: {
              success: { type: 'boolean' },
              message: { type: 'string' }
            }
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      if (!taskScheduler) {return { success: false, message: 'TaskScheduler not initialized' };}
      return taskScheduler.triggerMLRetrain();
    }
  );

  // GET /api/v2/ml/retrain/status
  fastify.get(
    '/retrain/status',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.ML_READ)],
      schema: {
        tags: ['ml'],
        summary: 'Get status of current retraining job',
        response: {
          200: {
            type: 'object',
            properties: {
              status: { type: 'string' },
              error: { type: 'string', nullable: true },
              lastStartedAt: { type: 'string' }
            }
          }
        }
      },
    },
    async (_request: FastifyRequest, _reply: FastifyReply) => {
      if (!taskScheduler) {return { status: 'IDLE' };}
      return taskScheduler.getMLRetrainStatus();
    }
  );
}

