import { Permissions,v1NodeContracts } from '@edgecloud/shared-kernel';
import { FastifyInstance, FastifyRequest } from 'fastify';
import { EdgeNode } from '@prisma/client';

import { idParamSchema } from '../schemas';
import { zodToFastifySchema } from '../utils/zod-schema';

const NodeStatus = {
  ONLINE: 'ONLINE',
  OFFLINE: 'OFFLINE',
  DEGRADED: 'DEGRADED',
  MAINTENANCE: 'MAINTENANCE',
} as const;



/**
  * Transform flat Prisma node model to versioned API response schema
  */
 function transformNode(node: EdgeNode & { _count?: { tasks: number } }) {
   if (!node) {return null;}

   const { cpuCores, memoryGB, storageGB, ...rest } = node;

   return {
     ...rest,
     specs: {
       cpuCores: cpuCores || 0,
       memoryGB: memoryGB || 0,
       storageGB: storageGB || 0,
     },
     // Ensure status is uppercase as per schema
     status: (node.status || 'OFFLINE').toUpperCase(),
     lastHeartbeat: (node.lastHeartbeat || node.createdAt || new Date()).toISOString(),
     taskCount: node._count?.tasks || 0,
   };
 }

 export default async function nodeRoutes(fastify: FastifyInstance) {
  // List nodes
  fastify.get<{ Querystring: v1NodeContracts.NodeQueryV1 }>(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.NODE_READ)],
      schema: {
        querystring: zodToFastifySchema(v1NodeContracts.NodeQueryV1Schema),
        tags: ['nodes'],
        summary: 'List edge nodes',
        response: {
          200: {
            type: 'object',
            properties: {
              data: { type: 'array', items: zodToFastifySchema(v1NodeContracts.NodeV1ResponseSchema) },
              pagination: {
                type: 'object',
                properties: {
                  page: { type: 'number' },
                  limit: { type: 'number' },
                  total: { type: 'number' },
                  totalPages: { type: 'number' },
                },
              },
            },
          },
        },
      },
    },
    async (request: FastifyRequest<{ Querystring: v1NodeContracts.NodeQueryV1 }>, _reply) => {
      const { region, status, page, limit, sortBy, sortOrder } = request.query;

      const where: any = {
        ...(region && { region }),
        ...(status && {
          status: status,
        }),
      };

      const [nodes, total] = await Promise.all([
        request.tPrisma.edgeNode.findMany({
          where,
          orderBy: { [sortBy]: sortOrder },
          skip: (page - 1) * limit,
          take: limit,
          include: {
            _count: { select: { tasks: true } },
          },
        }),
        request.tPrisma.edgeNode.count({ where }),
      ]);

      return {
        data: nodes.map(transformNode),
        pagination: {
          page,
          limit,
          total,
          totalPages: Math.ceil(total / limit),
        },
      };
    },
  );

  // Get node by ID
  fastify.get<{ Params: { id: string } }>(
    '/:id',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.NODE_READ)],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['nodes'],
        summary: 'Get node by ID',
        response: {
          200: zodToFastifySchema(v1NodeContracts.NodeV1ResponseSchema),
          404: {
            $ref: 'ErrorSchema#',
          },
        },
      },
    },
    async (request, reply) => {
      const node = await request.tPrisma.edgeNode.findFirst({
        where: { id: request.params.id },
        include: {
          tasks: {
            where: { status: 'RUNNING' },
            select: { id: true, name: true, type: true, submittedAt: true },
          },
          metrics: {
            orderBy: { timestamp: 'desc' },
            take: 100,
          },
        },
      });

      if (!node) {
        return reply.status(404).send({ 
          code: 'RESOURCE_NOT_FOUND',
          message: 'Node not found',
          requestId: request.id,
          timestamp: new Date().toISOString()
        });
      }

      return transformNode(node);
    },
  );

  // Create node
  fastify.post<{ Body: v1NodeContracts.RegisterNodeV1 }>(
    '/',
    {
      preHandler: [
        fastify.authenticate,
        fastify.requirePermission(Permissions.NODE_REGISTER),
      ],
      schema: {
        body: zodToFastifySchema(v1NodeContracts.RegisterNodeV1Schema),
        tags: ['nodes'],
        summary: 'Register a new edge node',
        response: {
          201: zodToFastifySchema(v1NodeContracts.NodeV1ResponseSchema),
          409: {
            $ref: 'ErrorSchema#',
          },
        },
      },
    },
    async (request: FastifyRequest<{ Body: v1NodeContracts.RegisterNodeV1 }>, reply) => {
      const data = request.body;

      // Check for duplicate name within the same tenant
      const existing = await (request.tPrisma as any).edgeNode.findFirst({
        where: { 
          name: data.name
        },
      });

      if (existing) {
        return reply
          .status(409)
          .send({ 
            code: 'RESOURCE_CONFLICT',
            message: 'Node with this name already exists in your tenant',
            requestId: request.id,
            timestamp: new Date().toISOString()
          });
      }

      const node = await (request.tPrisma as any).edgeNode.create({
        data: {
          name: data.name,
          location: data.location,
          region: data.region,
          ipAddress: data.ipAddress,
          port: data.port,
          cpuCores: data.cpuCores,
          memoryGB: data.memoryGB,
          storageGB: data.storageGB,
          url: `http://${data.ipAddress}:${data.port}`,
          status: 'OFFLINE',
          ...(data.maxTasks !== undefined && { maxTasks: data.maxTasks }),
          ...(data.costPerHour !== undefined && {
            costPerHour: data.costPerHour,
          }),
          ...(data.bandwidthInMbps !== undefined && {
            bandwidthInMbps: data.bandwidthInMbps,
          }),
          ...(data.bandwidthOutMbps !== undefined && {
            bandwidthOutMbps: data.bandwidthOutMbps,
          }),
          tenantId: request.user!.tenantId!,
        },
      });

      // Audit log
      await (request.tPrisma as any).auditLog.create({
        data: {
          userId: (request.user as any).id,
          tenantId: request.user!.tenantId!,
          action: 'node.created',
          entityType: 'node',
          entityId: node.id,
          details: { name: node.name, region: node.region } as any,
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return reply.status(201).send(transformNode(node));
    },
  );

  // Update node
  fastify.patch<{
    Params: { id: string };
    Body: v1NodeContracts.UpdateNodeV1;
  }>(
    '/:id',
    {
      preHandler: [
        fastify.authenticate,
        fastify.requirePermission(Permissions.NODE_REGISTER),
      ],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        body: zodToFastifySchema(v1NodeContracts.UpdateNodeV1Schema),
        tags: ['nodes'],
        summary: 'Update node configuration',
      },
    },
    async (request, reply) => {
      const { id } = request.params;
      const data = request.body;

      const existingNode = await fastify.prisma.edgeNode.findFirst({
        where: { id, tenantId: request.user!.tenantId! },
      });

      if (!existingNode) {
        return reply.status(404).send({
          code: 'RESOURCE_NOT_FOUND',
          message: 'Node not found',
          requestId: request.id,
          timestamp: new Date().toISOString()
        });
      }

      const node = await (request.tPrisma as any).edgeNode.update({
        where: { id },
        data: data as any,
      });

      // Audit log
      await (request.tPrisma as any).auditLog.create({
        data: {
          userId: (request.user as any).id,
          tenantId: request.user!.tenantId!,
          action: 'node.updated',
          entityType: 'node',
          entityId: node.id,
          details: { changes: data } as any,
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return transformNode(node);
    },
  );

  // Delete node
  fastify.delete<{ Params: { id: string } }>(
    '/:id',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.NODE_REGISTER)],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['nodes'],
        summary: 'Deregister an edge node',
      },
    },
    async (request, reply) => {
      const { id } = request.params;

      // Check for running tasks
      const runningTasks = await (request.tPrisma as any).task.count({
        where: { nodeId: id, status: 'RUNNING' },
      });

      if (runningTasks > 0) {
        return reply.status(400).send({
          code: 'VALIDATION_ERROR',
          message: 'Cannot delete node with running tasks',
          details: { runningTasks } as any,
        });
      }

      const existingNode = await fastify.prisma.edgeNode.findFirst({
        where: { id, tenantId: request.user!.tenantId! },
      });

      if (!existingNode) {
        return reply.status(404).send({
          code: 'RESOURCE_NOT_FOUND',
          message: 'Node not found',
          requestId: request.id,
          timestamp: new Date().toISOString()
        });
      }

      await (request.tPrisma as any).edgeNode.delete({ 
        where: { id } 
      });

      // Audit log
      await (request.tPrisma as any).auditLog.create({
        data: {
          userId: (request.user as any).id,
          tenantId: request.user!.tenantId!,
          action: 'node.deleted',
          entityType: 'node',
          entityId: id,
          details: {},
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return { success: true };
    },
  );

  // Node heartbeat (called by edge agent)
  fastify.post<{
    Params: { id: string };
    Body: {
      cpuUsage: number;
      memoryUsage: number;
      storageUsage?: number;
      latency?: number;
      tasksRunning?: number;
      networkIn?: number;
      networkOut?: number;
    };
  }>(
    '/:id/heartbeat',
    {
      preHandler: [fastify.authenticate],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        body: {
          type: 'object',
          properties: {
            cpuUsage: { type: 'number' },
            memoryUsage: { type: 'number' },
            storageUsage: { type: 'number' },
            latency: { type: 'number' },
            tasksRunning: { type: 'number' },
            networkIn: { type: 'number' },
            networkOut: { type: 'number' },
          },
          required: ['cpuUsage', 'memoryUsage'],
        },
        tags: ['nodes'],
        summary: 'Receive heartbeat from edge agent',
      },
    },
    async (request, reply) => {
      const { id } = request.params;
      const metrics = (request as any).body;

      // Verify node belongs to user's tenant
      const node = await (request.tPrisma as any).edgeNode.findFirst({
        where: { id }
      });

      if (!node) {
        return reply.status(404).send({ 
          code: 'RESOURCE_NOT_FOUND',
          message: 'Node not found or access denied',
          requestId: request.id,
          timestamp: new Date().toISOString()
        });
      }

      await (request.tPrisma as any).edgeNode.update({
        where: { id },
        data: {
          cpuUsage: metrics.cpuUsage,
          memoryUsage: metrics.memoryUsage,
          storageUsage: metrics.storageUsage ?? 0,
          latency: metrics.latency ?? 0,
          tasksRunning: metrics.tasksRunning ?? 0,
          lastHeartbeat: new Date(),
          status: 'ONLINE',
        },
      });

      if (node && (node).metrics?.length > 0) {
        (node).status = 'ONLINE';
        (node).lastHeartbeat = (node).metrics[0].timestamp;
      }

      // Store metrics
      await (request.tPrisma as any).nodeMetric.create({
        data: {
          nodeId: id,
          cpuUsage: metrics.cpuUsage,
          memoryUsage: metrics.memoryUsage,
          storageUsage: metrics.storageUsage ?? 0,
          latency: metrics.latency ?? 0,
          tasksRunning: metrics.tasksRunning ?? 0,
          networkIn: metrics.networkIn ?? 0,
          networkOut: metrics.networkOut ?? 0,
        },
      });

      // Publish to WebSocket subscribers
      fastify.wsManager.broadcast('node:heartbeat', {
        nodeId: id,
        metrics,
        timestamp: new Date().toISOString(),
      }, node.tenantId);

      return { success: true, timestamp: new Date().toISOString() };
    },
  );

  // Get node metrics
  fastify.get<{
    Params: { id: string };
    Querystring: { from?: string; to?: string; limit?: number };
  }>(
    '/:id/metrics',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.NODE_READ)],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        querystring: {
          type: 'object',
          properties: {
            from: { type: 'string', format: 'date-time' },
            to: { type: 'string', format: 'date-time' },
            limit: { type: 'number', default: 100 },
          },
        },
        tags: ['nodes'],
        summary: 'Get node metrics history',
      },
    },
    async (request, _reply) => {
      const { id } = request.params;
      const { from, to, limit = 100 } = request.query;

      const metrics = await (request.tPrisma as any).nodeMetric.findMany({
        where: {
          nodeId: id,
          ...(from && { timestamp: { gte: new Date(from) } }),
          ...(to && { timestamp: { lte: new Date(to) } }),
        },
        orderBy: { timestamp: 'desc' },
        take: limit,
      });

      return metrics;
    },
  );

  // Set maintenance mode
  fastify.post<{ Params: { id: string }; Body: { enabled: boolean } }>(
    '/:id/maintenance',
    {
      preHandler: [
        fastify.authenticate,
        fastify.requirePermission(Permissions.NODE_DRAIN),
      ],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        body: {
          type: 'object',
          properties: {
            enabled: { type: 'boolean' },
          },
          required: ['enabled'],
        },
        tags: ['nodes'],
        summary: 'Enable/disable maintenance mode',
      },
    },
    async (request, _reply) => {
      const { id } = request.params;
      const { enabled } = request.body;

      const node = await (request.tPrisma as any).edgeNode.update({
        where: { id },
        data: {
          isMaintenanceMode: enabled,
          status: enabled ? NodeStatus.MAINTENANCE : NodeStatus.ONLINE,
        },
      });

      // Audit log
      await (request.tPrisma as any).auditLog.create({
        data: {
          userId: (request.user as any).id,
          tenantId: request.user!.tenantId!,
          action: enabled
            ? 'node.maintenance_enabled'
            : 'node.maintenance_disabled',
          entityType: 'node',
          entityId: id,
          details: {},
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return node;
    },
  );

  // Drain node (stop accepting new tasks)
  fastify.post<{ Params: { id: string } }>(
    '/:id/drain',
    {
      preHandler: [
        fastify.authenticate,
        fastify.requirePermission(Permissions.NODE_DRAIN),
      ],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['nodes'],
        summary: 'Start draining a node (stop accepting new tasks)',
        response: {
          200: {
            type: 'object',
            properties: {
              success: { type: 'boolean' },
              message: { type: 'string' },
            },
          },
        },
      },
    },
    async (request, _reply) => {
      const { id } = request.params;

      await (request.tPrisma as any).edgeNode.update({
        where: { id },
        data: {
          isMaintenanceMode: true,
          status: NodeStatus.MAINTENANCE, // For now, we use MAINTENANCE as the underlying status
        },
      });

      // Audit log
      await (request.tPrisma as any).auditLog.create({
        data: {
          userId: (request.user as any).id,
          tenantId: request.user!.tenantId!,
          action: 'node.drain_started',
          entityType: 'node',
          entityId: id,
          details: {} as any,
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return { success: true, message: 'Node is now draining' };
    },
  );

  // Force node offline
  fastify.post<{ Params: { id: string } }>(
    '/:id/offline',
    {
      preHandler: [
        fastify.authenticate,
        fastify.requirePermission(Permissions.NODE_DRAIN),
      ],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        tags: ['nodes'],
        summary: 'Force a node to OFFLINE status',
        response: {
          200: {
            type: 'object',
            properties: {
              success: { type: 'boolean' },
              message: { type: 'string' },
            },
          },
        },
      },
    },
    async (request, _reply) => {
      const { id } = request.params;

      await request.tPrisma.edgeNode.update({
        where: { id },
        data: {
          status: NodeStatus.OFFLINE,
        },
      });

      // Audit log
      await request.tPrisma.auditLog.create({
        data: {
          userId: request.user!.id,
          tenantId: request.user!.tenantId!,
          action: 'node.forced_offline',
          entityType: 'node',
          entityId: id,
          details: {},
          ipAddress: request.ip,
          userAgent: request.headers['user-agent'] ?? null,
        },
      });

      return { success: true, message: 'Node forced offline' };
    },
  );

  // Get scheduling history for a node
  fastify.get<{ Params: { id: string }; Querystring: { days?: number } }>(
    '/:id/scheduling-history',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.NODE_READ)],
      schema: {
        params: zodToFastifySchema(idParamSchema),
        querystring: {
          type: 'object',
          properties: {
            days: { type: 'number', default: 7 },
          },
        },
        tags: ['nodes'],
        summary: 'Get scheduling history for a node',
      },
    },
    async (request, _reply) => {
      const { id } = request.params;
      const { days = 7 } = request.query;

      const startDate = new Date();
      startDate.setDate(startDate.getDate() - days);

      const history = await request.tPrisma.schedulingDecision.findMany({
        where: {
          selectedNodeId: id,
          timestamp: { gte: startDate },
        },
        orderBy: { timestamp: 'desc' },
        take: 1000,
      });

      return history;
    },
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';
import { z } from 'zod';

import { zodToFastifySchema } from '../utils/zod-schema.js';

const PolicySchema = z.object({
  policy: z.string(),
});

const ThresholdsSchema = z.object({
  cpu: z.number().min(0).max(100).optional(),
  memory: z.number().min(0).max(100).optional(),
  latency: z.number().min(0).optional(),
});

export default async function policyRoutes(fastify: FastifyInstance) {
  // Get all policies
  fastify.get(
    '/',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SCHEDULER_READ)],
      schema: {
        tags: ['policies'],
        summary: 'List available scheduling policies',
      },
    },
    async (_request, _reply) => {
      const policies = [
        { id: 'balanced', name: 'Balanced', description: 'Equal weight to all factors' },
        { id: 'cost', name: 'Cost Optimized', description: 'Minimize infrastructure spend' },
        { id: 'latency', name: 'Latency Optimized', description: 'Minimize response time' },
        { id: 'ml', name: 'ML Enhanced', description: 'Predictive placement using ML' },
      ];

      return {
        active: 'balanced', // Mocking active policy for now
        available: policies,
      };
    },
  );

  // Get active policy
  fastify.get(
    '/active',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SCHEDULER_READ)],
      schema: {
        tags: ['policies'],
        summary: 'Get the currently active scheduling policy',
      },
    },
    async (_request, _reply) => {
      return {
        policy: 'balanced',
        updatedAt: new Date().toISOString(),
      };
    },
  );

  // Update active policy
  fastify.patch<{ Body: z.infer<typeof PolicySchema> }>(
    '/active',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SCHEDULER_MANAGE)],
      schema: {
        body: zodToFastifySchema(PolicySchema),
        tags: ['policies'],
        summary: 'Update the active scheduling policy',
      },
    },
    async (request, _reply) => {
      const { policy } = request.body;

      // In a real app, we would update this in DB or Redis
      return {
        success: true,
        policy,
        updatedAt: new Date().toISOString(),
      };
    },
  );

  // Get policy config
  fastify.get(
    '/config',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SCHEDULER_READ)],
      schema: {
        tags: ['policies'],
        summary: 'Get detailed configuration for all policies',
      },
    },
    async (_request, _reply) => {
      return {
        balanced: { latency: 0.25, cost: 0.25, cpu: 0.25, memory: 0.25 },
        cost: { latency: 0.1, cost: 0.6, cpu: 0.15, memory: 0.15 },
        latency: { latency: 0.6, cost: 0.1, cpu: 0.15, memory: 0.15 },
      };
    },
  );

  // Get thresholds
  fastify.get(
    '/thresholds',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SCHEDULER_READ)],
      schema: {
        tags: ['policies'],
        summary: 'Get system health thresholds',
      },
    },
    async (_request, _reply) => {
      return {
        cpu: 80,
        memory: 85,
        latency: 200,
      };
    },
  );

  // Update thresholds
  fastify.patch<{ Body: z.infer<typeof ThresholdsSchema> }>(
    '/thresholds',
    {
      preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SCHEDULER_MANAGE)],
      schema: {
        body: zodToFastifySchema(ThresholdsSchema),
        tags: ['policies'],
        summary: 'Update system health thresholds',
      },
    },
    async (request, _reply) => {
      const thresholds = request.body;
      return {
        success: true,
        thresholds,
        updatedAt: new Date().toISOString(),
      };
    },
  );
}

import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyPluginAsync } from 'fastify';

import { 
  getAllCircuitBreakerStates, 
  globalCircuitBreakerRegistry 
} from '../utils/circuit-breakers.js';

const resilienceRoutes: FastifyPluginAsync = async (fastify) => {
  /**
   * GET /api/v2/circuit-breakers
   * Returns state of all registered circuit breakers
   */
  fastify.get('/', {
    preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.SYSTEM_READ)],
    schema: {
      tags: ['resilience'],
      summary: 'Get all circuit breaker states',
      response: {
        200: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              name: { type: 'string' },
              state: { type: 'string', enum: ['CLOSED', 'OPEN', 'HALF_OPEN'] },
              failureRate: { type: 'number' },
              lastStateChange: { type: 'string' },
              successCount: { type: 'number' },
              failureCount: { type: 'number' },
              nextRetryAt: { type: 'string' }
            }
          }
        }
      }
    }
  }, async () => {
    return getAllCircuitBreakerStates();
  });

  /**
   * POST /api/v2/circuit-breakers/:name/reset
   * Force a circuit breaker into CLOSED (or HALF_OPEN) state
   */
  fastify.post('/:name/reset', {
    schema: {
      tags: ['resilience'],
      summary: 'Force reset a circuit breaker',
      params: {
        type: 'object',
        properties: {
          name: { type: 'string' }
        },
        required: ['name']
      },
      response: {
        200: {
          type: 'object',
          properties: {
            success: { type: 'boolean' },
            message: { type: 'string' }
          }
        },
        404: {
          type: 'object',
          properties: {
            error: { type: 'string' }
          }
        }
      }
    },
    preHandler: [fastify.authenticate, fastify.requirePermission(Permissions.CIRCUIT_BREAKER_RESET)]
  }, async (request, reply) => {
    const { name } = request.params as { name: string };
    const breaker = globalCircuitBreakerRegistry.get(name);

    if (!breaker) {
      return reply.code(404).send({ error: `Circuit breaker '${name}' not found` });
    }

    // Force close transitions it to CLOSED, which allows new calls (effectively HALF_OPEN in behavior for recovery)
    breaker.forceClose();

    fastify.log.warn({ adminId: (request as any).user?.id, breaker: name }, 'Admin force-closed circuit breaker');

    return { 
      success: true, 
      message: `Circuit breaker '${name}' has been force-closed and is now attempting recovery.` 
    };
  });
};

export default resilienceRoutes;

/**
 * Scheduler Configuration API Routes
 *
 * Endpoints for managing scheduler weights and configuration
 */

import { ScoreWeights } from '@edgecloud/ml-scheduler';
import { Permissions } from '@edgecloud/shared-kernel';
import { FastifyInstance } from 'fastify';
import { z } from 'zod';

// Validation schema for weights
const WeightsSchema = z.object({
  latency: z.number().min(0).max(1).optional(),
  cpu: z.number().min(0).max(1).optional(),
  memory: z.number().min(0).max(1).optional(),
  cost: z.number().min(0).max(1).optional(),
  network: z.number().min(0).max(1).optional(),
  ml: z.number().min(0).max(1).optional(),
  health: z.number().min(0).max(1).optional(),
});

interface SchedulerConfigRoutesOptions {
  getWeights: () => ScoreWeights;
  setWeights: (weights: Partial<ScoreWeights>) => void;
  getCircuitBreakerHealth: () => Record<string, unknown>;
}


export async function schedulerConfigRoutes(
  fastify: FastifyInstance,
  options: SchedulerConfigRoutesOptions,
) {
  // Add authentication and role protection to all routes in this module
  fastify.addHook('preHandler', fastify.authenticate);
  fastify.addHook('preHandler', fastify.requirePermission(Permissions.SCHEDULER_READ));

  // Get current scheduler weights
  fastify.get('/weights', async (_, reply) => {
    const weights = options.getWeights();

    return reply.send({
      success: true,
      data: {
        weights,
        normalized: normalizeWeights(weights),
        updatedAt: new Date().toISOString(),
      },
    });
  });

  // Update scheduler weights
  fastify.put(
    '/weights',
    {
      preHandler: [fastify.requirePermission(Permissions.SCHEDULER_MANAGE)],
      schema: {
        body: {
          type: 'object',
          properties: {
            latency: { type: 'number', minimum: 0, maximum: 1 },
            cpu: { type: 'number', minimum: 0, maximum: 1 },
            memory: { type: 'number', minimum: 0, maximum: 1 },
            cost: { type: 'number', minimum: 0, maximum: 1 },
            network: { type: 'number', minimum: 0, maximum: 1 },
            ml: { type: 'number', minimum: 0, maximum: 1 },
            health: { type: 'number', minimum: 0, maximum: 1 },
          },
        },
      },
    },
    async (request, reply) => {
      const body = WeightsSchema.parse(request.body);

      options.setWeights(body as any);

      const updatedWeights = options.getWeights();

      return reply.send({
        success: true,
        message: 'Scheduler weights updated',
        data: {
          weights: updatedWeights,
          normalized: normalizeWeights(updatedWeights),
        },
      });
    },
  );

  // Reset weights to defaults
  fastify.post('/weights/reset', {
    preHandler: [fastify.requirePermission(Permissions.SCHEDULER_MANAGE)]
  }, async (_, reply) => {
    const defaultWeights: ScoreWeights = {
      latency: 0.2,
      cpu: 0.15,
      memory: 0.15,
      cost: 0.2,
      network: 0.1,
      ml: 0.1,
      health: 0.1,
    };

    options.setWeights(defaultWeights);

    return reply.send({
      success: true,
      message: 'Scheduler weights reset to defaults',
      data: {
        weights: defaultWeights,
      },
    });
  });

  // Get circuit breaker health
  fastify.get('/circuit-breakers', async (_, reply) => {
    const health = options.getCircuitBreakerHealth();

    return reply.send({
      success: true,
      data: {
        circuitBreakers: health,
        timestamp: new Date().toISOString(),
      },
    });
  });

  // Get scheduler presets
  fastify.get('/presets', async (_, reply) => {
    return reply.send({
      success: true,
      data: {
        presets: [
          {
            name: 'balanced',
            description: 'Balanced across all factors',
            weights: {
              latency: 0.15,
              cpu: 0.15,
              memory: 0.15,
              cost: 0.15,
              network: 0.1,
              ml: 0.15,
              health: 0.15,
            },
          },
          {
            name: 'cost-optimized',
            description: 'Prioritize cost efficiency',
            weights: {
              latency: 0.1,
              cpu: 0.1,
              memory: 0.1,
              cost: 0.4,
              network: 0.05,
              ml: 0.1,
              health: 0.15,
            },
          },
          {
            name: 'latency-optimized',
            description: 'Prioritize low latency',
            weights: {
              latency: 0.4,
              cpu: 0.1,
              memory: 0.1,
              cost: 0.1,
              network: 0.15,
              ml: 0.05,
              health: 0.1,
            },
          },
          {
            name: 'ml-enhanced',
            description: 'Trust ML predictions more',
            weights: {
              latency: 0.1,
              cpu: 0.1,
              memory: 0.1,
              cost: 0.1,
              network: 0.1,
              ml: 0.4,
              health: 0.1,
            },
          },
          {
            name: 'health-priority',
            description: 'Prioritize healthy nodes',
            weights: {
              latency: 0.1,
              cpu: 0.1,
              memory: 0.1,
              cost: 0.1,
              network: 0.1,
              ml: 0.1,
              health: 0.4,
            },
          },
        ],
      },
    });
  });

  // Apply a preset
  fastify.post('/presets/:name/apply', {
    preHandler: [fastify.requirePermission(Permissions.SCHEDULER_MANAGE)]
  }, async (request, reply) => {
    const { name } = request.params as { name: string };

    const presets: Record<string, ScoreWeights> = {
      balanced: {
        latency: 0.15,
        cpu: 0.15,
        memory: 0.15,
        cost: 0.15,
        network: 0.1,
        ml: 0.15,
        health: 0.15,
      },
      'cost-optimized': {
        latency: 0.1,
        cpu: 0.1,
        memory: 0.1,
        cost: 0.4,
        network: 0.05,
        ml: 0.1,
        health: 0.15,
      },
      'latency-optimized': {
        latency: 0.4,
        cpu: 0.1,
        memory: 0.1,
        cost: 0.1,
        network: 0.15,
        ml: 0.05,
        health: 0.1,
      },
      'ml-enhanced': {
        latency: 0.1,
        cpu: 0.1,
        memory: 0.1,
        cost: 0.1,
        network: 0.1,
        ml: 0.4,
        health: 0.1,
      },
      'health-priority': {
        latency: 0.1,
        cpu: 0.1,
        memory: 0.1,
        cost: 0.1,
        network: 0.1,
        ml: 0.1,
        health: 0.4,
      },
    };

    const preset = presets[name];
    if (!preset) {
      return reply.status(404).send({
        success: false,
        error: `Preset '${name}' not found`,
      });
    }

    options.setWeights(preset);

    return reply.send({
      success: true,
      message: `Applied preset: ${name}`,
      data: {
        weights: preset,
      },
    });
  });
}

/**
 * Normalize weights to sum to 1
 */
function normalizeWeights(weights: ScoreWeights): ScoreWeights {
  const sum = Object.values(weights).reduce((a: number, b: number) => a + b, 0);

  if (sum === 0) {
    return weights;
  }

  return {
    latency: weights.latency / sum,
    cpu: weights.cpu / sum,
    memory: weights.memory / sum,
    cost: weights.cost / sum,
    network: weights.network / sum,
    ml: weights.ml / sum,
    health: weights.health / sum,
  };
}

