import { tracer } from '@edgecloud/shared-kernel';
import { SpanStatusCode } from '@opentelemetry/api';
import { NodeStatus, PrismaClient } from '@prisma/client';
import Redis from 'ioredis';
import type { Logger } from 'pino';

import type { TaskScheduler } from './task-scheduler';
import type { WebSocketManager } from './websocket-manager';

const HEARTBEAT_TIMEOUT = 30000; // 30 seconds
const CHECK_INTERVAL = 10000; // 10 seconds

export class HeartbeatMonitor {
  private prisma: PrismaClient;
  private wsManager: WebSocketManager;
  private logger: Logger;
  private interval: NodeJS.Timeout | null = null;
  private taskScheduler: TaskScheduler | null = null;

  constructor(
    prisma: PrismaClient,
    _redis: Redis,
    wsManager: WebSocketManager,
    logger: Logger,
  ) {
    this.prisma = prisma;
    this.wsManager = wsManager;
    this.logger = logger;
  }

  start() {
    this.interval = setInterval(() => this.checkNodes(), CHECK_INTERVAL);
  }

  setTaskScheduler(taskScheduler: TaskScheduler) {
    this.taskScheduler = taskScheduler;
  }

  stop() {
    if (this.interval) {
      clearInterval(this.interval);
      this.interval = null;
    }
  }

  private async checkNodes() {
    await tracer.startActiveSpan('orchestrator:heartbeat_check', async (span) => {
      try {
        const now = new Date();
        const timeoutThreshold = new Date(now.getTime() - HEARTBEAT_TIMEOUT);

        // Find nodes that haven't sent heartbeat recently
        const staleNodes = await this.prisma.edgeNode.findMany({
          where: {
            status: NodeStatus.ONLINE,
            lastHeartbeat: { lt: timeoutThreshold },
            isMaintenanceMode: false,
          },
        });

        span.setAttribute('monitor.stale_nodes_count', staleNodes.length);

        for (const node of staleNodes) {
          // Update node status
          await this.prisma.edgeNode.update({
            where: { id: node.id },
            data: { status: NodeStatus.OFFLINE },
          });

          // Handle running tasks on this node
          await this.handleNodeFailure(node.id);

          // Broadcast status change
          this.wsManager.broadcast('node:status_changed', {
            nodeId: node.id,
            status: 'OFFLINE',
            reason: 'heartbeat_timeout',
            timestamp: now.toISOString(),
          }, node.tenantId);

          // Create alert
          await this.prisma.alert.create({
            data: {
              ruleId: 'heartbeat-timeout',
              entityId: node.id,
              entityType: 'node',
              severity: 'high',
              message: `Node ${node.name} went offline due to heartbeat timeout`,
              tenantId: node.tenantId,
            },
          });
        }

        // Check for degraded nodes
        const degradedNodes = await this.prisma.edgeNode.findMany({
          where: {
            status: NodeStatus.ONLINE,
            OR: [{ cpuUsage: { gt: 90 } }, { memoryUsage: { gt: 90 } }],
          },
        });

        span.setAttribute('monitor.degraded_nodes_count', degradedNodes.length);

        for (const node of degradedNodes) {
          await this.prisma.edgeNode.update({
            where: { id: node.id },
            data: { status: NodeStatus.DEGRADED },
          });

          this.wsManager.broadcast('node:status_changed', {
            nodeId: node.id,
            status: 'DEGRADED',
            reason: 'high_resource_usage',
            cpuUsage: node.cpuUsage,
            memoryUsage: node.memoryUsage,
            timestamp: now.toISOString(),
          }, node.tenantId);
        }

        // Check for recovered nodes (degraded -> online)
        const recoveredNodes = await this.prisma.edgeNode.findMany({
          where: {
            status: NodeStatus.DEGRADED,
            cpuUsage: { lt: 80 },
            memoryUsage: { lt: 80 },
            lastHeartbeat: { gte: timeoutThreshold },
          },
        });

        span.setAttribute('monitor.recovered_nodes_count', recoveredNodes.length);

        for (const node of recoveredNodes) {
          await this.prisma.edgeNode.update({
            where: { id: node.id },
            data: { status: NodeStatus.ONLINE },
          });

          this.wsManager.broadcast('node:status_changed', {
            nodeId: node.id,
            status: 'ONLINE',
            reason: 'recovered',
            timestamp: now.toISOString(),
          }, node.tenantId);
        }
        span.setStatus({ code: SpanStatusCode.OK });
      } catch (error: unknown) {
        const err = error as Error;
        span.recordException(err);
        span.setStatus({ code: SpanStatusCode.ERROR });
        this.logger.error({ error: err }, 'Error in heartbeat monitor');
      } finally {
        span.end();
      }
    });
  }

  private async handleNodeFailure(nodeId: string) {
    // Find running tasks on failed node
    const runningTasks = await this.prisma.task.findMany({
      where: {
        nodeId,
        status: 'RUNNING',
      },
    });

    for (const task of runningTasks) {
      this.logger.info(
        { taskId: task.id, nodeId },
        'Rescheduling task from failed node',
      );

      // Mark task as failed
      const previousExecution = await this.prisma.taskExecution.findFirst({
        where: { taskId: task.id },
        orderBy: { attemptNumber: 'desc' },
      });

      await this.prisma.$transaction([
        this.prisma.task.update({
          where: { id: task.id },
          data: {
            status: 'FAILED',
          },
        }),
        ...(previousExecution
          ? [
              this.prisma.taskExecution.update({
                where: { id: previousExecution.id },
                data: {
                  status: 'FAILED',
                  error: 'Node offline',
                  completedAt: new Date(),
                },
              }),
            ]
          : []),
      ]);

      // Create retry execution if under max retries
      const executionCount = await this.prisma.taskExecution.count({
        where: { taskId: task.id },
      });
      if (executionCount < task.maxRetries) {
        await this.prisma.taskExecution.create({
          data: {
            taskId: task.id,
            status: 'PENDING',
            attemptNumber: executionCount + 1,
            retryOf: previousExecution?.id ?? null,
            tenantId: task.tenantId,
          },
        });

        const updatedTask = await this.prisma.task.update({
          where: { id: task.id },
          data: {
            status: 'PENDING',
            nodeId: null,
          },
        });

        if (this.taskScheduler) {
          await this.taskScheduler.enqueue(updatedTask);
        }
      }

      this.wsManager.broadcast('task:failed', {
        taskId: task.id,
        nodeId,
        reason: 'node_offline',
      }, task.tenantId);
    }
  }
}

/**
 * Idempotency Service
 *
 * Ensures exactly-once processing across the distributed system.
 * Handles deduplication for:
 * - Kafka message processing
 * - API requests
 * - Saga steps
 * - Task execution
 */

import { PrismaClient } from '@prisma/client';
import { createHash } from 'crypto';
import Redis from 'ioredis';
import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export interface IdempotencyConfig {
  defaultTtlMs: number;
  cacheEnabled: boolean;
  cacheTtlMs: number;
}

export interface IdempotentRequest {
  idempotencyKey: string;
  resourceType: string;
  resourceId: string;
  requestHash?: string;
  ttlMs?: number;
}

export interface IdempotencyResult {
  isDuplicate: boolean;
  existingResult?: Record<string, unknown>;
  recordId?: string;
}

// ============================================================================
// Constants
// ============================================================================

const DEFAULT_CONFIG: IdempotencyConfig = {
  defaultTtlMs: 86400000, // 24 hours
  cacheEnabled: true,
  cacheTtlMs: 3600000, // 1 hour cache
};

const CACHE_KEY_PREFIX = 'idempotency:';
const LOCK_KEY_PREFIX = 'idempotency:lock:';

// ============================================================================
// IdempotencyService
// ============================================================================

export class IdempotencyService {
  private prisma: PrismaClient;
  private redis: Redis;
  private logger: Logger;
  private config: IdempotencyConfig;

  constructor(
    prisma: PrismaClient,
    redis: Redis,
    logger: Logger,
    config: Partial<IdempotencyConfig> = {},
  ) {
    this.prisma = prisma;
    this.redis = redis;
    this.logger = logger;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Check and record idempotency atomically
   * Returns true if this is a duplicate that should be skipped
   */
  async checkAndRecord(request: IdempotentRequest): Promise<IdempotencyResult> {
    const { idempotencyKey, resourceType, resourceId, requestHash, ttlMs } =
      request;
    const cacheKey = `${CACHE_KEY_PREFIX}${idempotencyKey}`;
    const lockKey = `${LOCK_KEY_PREFIX}${idempotencyKey}`;
    const ttl = ttlMs || this.config.defaultTtlMs;

    // 1. Check Redis cache first (fast path)
    if (this.config.cacheEnabled) {
      const cached = await this.redis.get(cacheKey);
      if (cached) {
        const result = JSON.parse(cached);
        this.logger.debug({ idempotencyKey }, 'Idempotency cache hit');
        return {
          isDuplicate: true,
          existingResult: result,
        };
      }
    }

    // 2. Acquire distributed lock to prevent race conditions
    const lockAcquired = await this.acquireLock(lockKey, 5000);
    if (!lockAcquired) {
      // Another process is handling this - wait and check
      await this.waitForLockRelease(lockKey);

      // Check again for existing record
      const existing = await this.findExisting(idempotencyKey);
      if (existing) {
        return { isDuplicate: true, existingResult: existing };
      }
    }

    try {
      // 3. Check database for existing record
      const existing = await this.prisma.idempotencyRecord.findUnique({
        where: { idempotencyKey },
      });

      if (existing) {
        // Update cache
        if (this.config.cacheEnabled && existing.result) {
          await this.redis.setex(
            cacheKey,
            Math.floor(this.config.cacheTtlMs / 1000),
            JSON.stringify(existing.result),
          );
        }

        return {
          isDuplicate: true,
          existingResult: existing.result as Record<string, unknown>,
        };
      }

      // 4. Create new record (PROCESSING status)
      const record = await this.prisma.idempotencyRecord.create({
        data: {
          idempotencyKey,
          resourceType,
          resourceId,
          requestHash: requestHash ?? null,
          status: 'PROCESSING',
          expiresAt: new Date(Date.now() + ttl),
        },
      });

      this.logger.debug(
        { idempotencyKey, recordId: record.id },
        'Created idempotency record',
      );

      return {
        isDuplicate: false,
        recordId: record.id,
      };
    } finally {
      // Release lock
      await this.releaseLock(lockKey);
    }
  }

  /**
   * Mark idempotency record as completed with result
   */
  async complete(
    idempotencyKey: string,
    result: Record<string, unknown>,
  ): Promise<void> {
    const cacheKey = `${CACHE_KEY_PREFIX}${idempotencyKey}`;

    // Update database
    await this.prisma.idempotencyRecord.update({
      where: { idempotencyKey },
      data: {
        status: 'COMPLETED',
        result: result as any,
      },
    });

    // Update cache
    if (this.config.cacheEnabled) {
      await this.redis.setex(
        cacheKey,
        Math.floor(this.config.cacheTtlMs / 1000),
        JSON.stringify(result),
      );
    }

    this.logger.debug({ idempotencyKey }, 'Marked idempotency as completed');
  }

  /**
   * Mark idempotency record as failed
   */
  async fail(idempotencyKey: string, error?: string): Promise<void> {
    await this.prisma.idempotencyRecord.update({
      where: { idempotencyKey },
      data: {
        status: 'FAILED',
        result: error ? { error } : ({} as any),
      },
    });

    this.logger.debug({ idempotencyKey }, 'Marked idempotency as failed');
  }

  /**
   * Generate idempotency key from components
   */
  static generateKey(
    prefix: string,
    ...components: (string | number)[]
  ): string {
    const combined = components.join(':');
    const hash = createHash('sha256')
      .update(combined)
      .digest('hex')
      .substring(0, 16);
    return `${prefix}:${hash}`;
  }

  /**
   * Generate key for Kafka message
   */
  static forKafkaMessage(
    topic: string,
    partition: number,
    offset: string,
  ): string {
    return this.generateKey('kafka', topic, partition, offset);
  }

  /**
   * Generate key for API request
   */
  static forApiRequest(
    userId: string,
    endpoint: string,
    requestHash: string,
  ): string {
    return this.generateKey('api', userId, endpoint, requestHash);
  }

  /**
   * Generate key for Saga step
   */
  static forSagaStep(
    sagaId: string,
    stepName: string,
    attempt: number,
  ): string {
    return this.generateKey('saga', sagaId, stepName, attempt);
  }

  /**
   * Generate key for Task execution
   */
  static forTaskExecution(taskId: string, nodeId: string): string {
    return this.generateKey('task', taskId, nodeId);
  }

  // Private methods

  private async acquireLock(key: string, ttlMs: number): Promise<boolean> {
    const result = await this.redis.set(key, '1', 'PX', ttlMs, 'NX');
    return result === 'OK';
  }

  private async releaseLock(key: string): Promise<void> {
    await this.redis.del(key);
  }

  private async waitForLockRelease(
    key: string,
    maxWaitMs: number = 5000,
  ): Promise<void> {
    const startTime = Date.now();
    while (Date.now() - startTime < maxWaitMs) {
      const exists = await this.redis.exists(key);
      if (!exists) {
        return;
      }
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  private async findExisting(
    idempotencyKey: string,
  ): Promise<Record<string, unknown> | null> {
    const record = await this.prisma.idempotencyRecord.findUnique({
      where: { idempotencyKey },
    });
    return record?.result as Record<string, unknown> | null;
  }

  /**
   * Cleanup expired records (run periodically)
   */
  async cleanupExpired(): Promise<number> {
    const result = await this.prisma.idempotencyRecord.deleteMany({
      where: {
        expiresAt: { lt: new Date() },
      },
    });

    this.logger.info(
      { count: result.count },
      'Cleaned up expired idempotency records',
    );
    return result.count;
  }
}

