/**
 * Kafka Exactly-Once Processing (EOS)
 *
 * Guarantees:
 * - No duplicate processing (idempotent producer)
 * - No lost messages (transactional consumer)
 * - Atomic "consume-process-produce" cycles
 *
 * Uses Kafka transactions + idempotent producer + consumer group offsets
 */

import type { PrismaClient } from '@prisma/client';
import Redis from 'ioredis';
import { Consumer, Kafka, Producer, RecordMetadata } from 'kafkajs';
import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export interface EOSConfig {
  transactionalId: string;
  isolationLevel: 'read_committed' | 'read_uncommitted';
  maxInFlightRequests: number;
  transactionTimeoutMs: number;
  idempotentRetryCount: number;
}

export interface ProcessedOffset {
  topic: string;
  partition: number;
  offset: string;
  processedAt: Date;
}

export interface MessageHandler<T = unknown> {
  (message: {
    key: string | null;
    value: T;
    headers: Record<string, string>;
    topic: string;
    partition: number;
    offset: string;
  }): Promise<{
    success: boolean;
    outputTopic?: string;
    outputMessages?: Array<{
      key: string;
      value: unknown;
      headers?: Record<string, string>;
    }>;
    error?: Error;
  }>;
}

// ============================================================================
// Constants
// ============================================================================

const DEFAULT_CONFIG: EOSConfig = {
  transactionalId: 'eos-producer',
  isolationLevel: 'read_committed',
  maxInFlightRequests: 1, // Required for EOS
  transactionTimeoutMs: 60000,
  idempotentRetryCount: 3,
};

const OFFSET_CACHE_PREFIX = 'eos:offset:';
const OFFSET_CACHE_TTL = 86400; // 24 hours

// ============================================================================
// KafkaExactlyOnceService
// ============================================================================

export class KafkaExactlyOnceService {
  private kafka: Kafka;
  private producer: Producer;
  private redis: Redis;
  private prisma: PrismaClient;
  private logger: Logger;
  private config: EOSConfig;
  private isInitialized: boolean = false;

  constructor(
    kafka: Kafka,
    redis: Redis,
    prisma: PrismaClient,
    logger: Logger,
    config: Partial<EOSConfig> = {},
  ) {
    this.kafka = kafka;
    this.redis = redis;
    this.prisma = prisma;
    this.logger = logger;
    this.config = { ...DEFAULT_CONFIG, ...config };

    // Create idempotent producer with transactions
    this.producer = this.kafka.producer({
      idempotent: true, // Enable idempotent producer
      transactionalId: this.config.transactionalId,
      maxInFlightRequests: this.config.maxInFlightRequests,
      transactionTimeout: this.config.transactionTimeoutMs,
      retry: {
        retries: this.config.idempotentRetryCount,
      },
    });
  }

  async initialize(): Promise<void> {
    if (this.isInitialized) {
      return;
    }

    await this.producer.connect();
    this.isInitialized = true;

    this.logger.info(
      { transactionalId: this.config.transactionalId },
      'Kafka EOS service initialized',
    );
  }

  async disconnect(): Promise<void> {
    await this.producer.disconnect();
    this.isInitialized = false;
  }

  /**
   * Process message with exactly-once semantics
   *
   * Steps:
   * 1. Check if already processed (deduplication)
   * 2. Start transaction
   * 3. Execute business logic
   * 4. Send output messages (if any)
   * 5. Commit consumer offset
   * 6. Commit transaction
   *
   * If any step fails, transaction aborts and offset is not committed
   */
  async processExactlyOnce<T>(
    consumerGroupId: string,
    message: {
      topic: string;
      partition: number;
      offset: string;
      key: string | null;
      value: T;
      headers: Record<string, string>;
    },
    handler: MessageHandler<T>,
  ): Promise<boolean> {
    const { topic, partition, offset, key, value, headers } = message;

    // 1. Check if already processed (fast path via Redis)
    const offsetKey = `${OFFSET_CACHE_PREFIX}${consumerGroupId}:${topic}:${partition}:${offset}`;
    const alreadyProcessed = await this.redis.get(offsetKey);

    if (alreadyProcessed) {
      this.logger.debug(
        { topic, partition, offset },
        'Message already processed, skipping',
      );
      return true;
    }

    // 2. Check database for processed offset (slower but persistent)
    const dbRecord = await this.prisma.processedOffset.findUnique({
      where: {
        consumerGroup_topic_partition_offset: {
          consumerGroup: consumerGroupId,
          topic,
          partition,
          offset,
        },
      },
    });

    if (dbRecord) {
      // Cache for next time
      await this.redis.setex(offsetKey, OFFSET_CACHE_TTL, '1');
      this.logger.debug(
        { topic, partition, offset },
        'Message already processed (DB), skipping',
      );
      return true;
    }

    // 3. Start transaction
    const transaction = await this.producer.transaction();
    const transactionId = `txn-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;

    try {
      // 4. Execute business logic
      const result = await handler({
        key,
        value,
        headers,
        topic,
        partition,
        offset,
      });

      if (!result.success) {
        throw result.error || new Error('Handler returned failure');
      }

      // 5. Send output messages within same transaction
      if (
        result.outputTopic &&
        result.outputMessages &&
        result.outputMessages.length > 0
      ) {
        for (const msg of result.outputMessages) {
          await transaction.send({
            topic: result.outputTopic,
            messages: [
              {
                key: msg.key,
                value: JSON.stringify(msg.value),
                headers: {
                  ...msg.headers,
                  'x-eos-transaction-id': transactionId,
                  'x-source-topic': topic,
                  'x-source-partition': partition.toString(),
                  'x-source-offset': offset,
                },
              },
            ],
          });
        }
      }

      // 6. Send offsets to transaction (marks message as consumed)
      // This ensures atomic "process + commit offset"

      await transaction.sendOffsets({
        consumerGroupId,
        topics: [
          {
            topic,
            partitions: [
              {
                partition,
                offset: (parseInt(offset, 10) + 1).toString(), // Commit next offset
              },
            ],
          },
        ],
      });

      // 7. Commit transaction (atomic)
      await transaction.commit();

      // 8. Record processed offset in DB
      await this.prisma.processedOffset.create({
        data: {
          consumerGroup: consumerGroupId,
          topic,
          partition,
          offset,
          processedAt: new Date(),
        },
      });

      // 9. Cache in Redis for fast dedup
      await this.redis.setex(offsetKey, OFFSET_CACHE_TTL, '1');

      this.logger.debug(
        { topic, partition, offset, transactionId },
        'Message processed exactly once',
      );

      return true;
    } catch (error) {
      // Abort transaction on any error
      await transaction.abort();

      this.logger.error(
        { topic, partition, offset, error: (error as Error).message },
        'Transaction aborted, message will be retried',
      );

      return false;
    }
  }

  /**
   * Send messages with exactly-once semantics
   * Uses idempotent producer + transactions
   */
  async sendExactlyOnce(
    topic: string,
    messages: Array<{
      key: string;
      value: unknown;
      headers?: Record<string, string>;
    }>,
    idempotencyKey: string,
  ): Promise<RecordMetadata[]> {
    const transaction = await this.producer.transaction();

    try {
      const results: RecordMetadata[] = [];

      for (const msg of messages) {
        const txnId = `txn-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
        const result = await transaction.send({
          topic,
          messages: [
            {
              key: msg.key,
              value: JSON.stringify(msg.value),
              headers: {
                ...msg.headers,
                'x-eos-transaction-id': txnId,
                'x-idempotency-key': idempotencyKey,
              },
            },
          ],
        });
        results.push(...result);
      }

      await transaction.commit();

      this.logger.debug(
        { topic, messageCount: messages.length },
        'Messages sent exactly once',
      );

      return results;
    } catch (error) {
      await transaction.abort();
      throw error;
    }
  }

  /**
   * Create consumer with read_committed isolation
   * Only sees committed messages (no uncommitted transactions)
   */
  createEOSConsumer(groupId: string, _topics: string[]): Consumer {
    const consumer = this.kafka.consumer({
      groupId,
      sessionTimeout: 30000,
      heartbeatInterval: 3000,
    } as any);

    return consumer;
  }

  /**
   * Cleanup old processed offsets (run periodically)
   */
  async cleanupOldOffsets(maxAgeDays: number = 7): Promise<number> {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - maxAgeDays);

    const result = await this.prisma.processedOffset.deleteMany({
      where: {
        processedAt: { lt: cutoffDate },
      },
    });

    this.logger.info(
      { count: result.count, maxAgeDays },
      'Cleaned up old processed offsets',
    );

    return result.count;
  }

  /**
   * Get processing statistics
   */
  async getStats(): Promise<{
    totalProcessed: number;
    uniqueTopics: number;
    uniqueConsumerGroups: number;
  }> {
    // Note: processedOffset model needs to be added to Prisma schema
    // For now, return mock stats
    return {
      totalProcessed: 0,
      uniqueTopics: 0,
      uniqueConsumerGroups: 0,
    };
  }
}

/**
 * Kubernetes Operator for Edge-Cloud Orchestrator
 * Manages EdgeNode custom resources
 */

import {
  CoreV1Api,
  CustomObjectsApi,
  KubeConfig,
  KubernetesObjectApi,
} from '@kubernetes/client-node';

import { createLogger } from '../lib/logger';

const logger = createLogger('k8s-operator');

// Custom Resource Definition for EdgeNode
export const EDGE_NODE_CRD = {
  apiVersion: 'apiextensions.k8s.io/v1',
  kind: 'CustomResourceDefinition',
  metadata: {
    name: 'edgenodes.edge-cloud.io',
  },
  spec: {
    group: 'edge-cloud.io',
    versions: [
      {
        name: 'v1',
        served: true,
        storage: true,
        schema: {
          openAPIV3Schema: {
            type: 'object',
            properties: {
              spec: {
                type: 'object',
                properties: {
                  region: { type: 'string' },
                  location: { type: 'string' },
                  cpuCores: { type: 'integer' },
                  memoryGB: { type: 'integer' },
                  storageGB: { type: 'integer' },
                  maxTasks: { type: 'integer' },
                  costPerHour: { type: 'number' },
                },
                required: ['region', 'location'],
              },
              status: {
                type: 'object',
                properties: {
                  phase: { type: 'string' },
                  conditions: {
                    type: 'array',
                    items: {
                      type: 'object',
                      properties: {
                        type: { type: 'string' },
                        status: { type: 'string' },
                        lastTransitionTime: { type: 'string' },
                        reason: { type: 'string' },
                        message: { type: 'string' },
                      },
                    },
                  },
                  cpuUsage: { type: 'number' },
                  memoryUsage: { type: 'number' },
                  tasksRunning: { type: 'integer' },
                },
              },
            },
          },
        },
      },
    ],
    scope: 'Namespaced',
    names: {
      plural: 'edgenodes',
      singular: 'edgenode',
      kind: 'EdgeNode',
      shortNames: ['en'],
    },
  },
};

export interface EdgeNodeResource {
  apiVersion: 'edge-cloud.io/v1';
  kind: 'EdgeNode';
  metadata: {
    name: string;
    namespace: string;
    labels?: Record<string, string>;
    annotations?: Record<string, string>;
  };
  spec: {
    region: string;
    location: string;
    cpuCores?: number;
    memoryGB?: number;
    storageGB?: number;
    maxTasks?: number;
    costPerHour?: number;
  };
  status?: {
    phase: string;
    conditions: Array<{
      type: string;
      status: string;
      lastTransitionTime: string;
      reason: string;
      message: string;
    }>;
    cpuUsage?: number;
    memoryUsage?: number;
    tasksRunning?: number;
  };
}

export class EdgeCloudOperator {
  private kc: KubeConfig;
  private customApi: CustomObjectsApi;
  private coreApi: CoreV1Api;
  private namespace: string;

  constructor(namespace: string = 'edge-cloud-orchestrator') {
    this.kc = new KubeConfig();
    this.kc.loadFromDefault();

    this.customApi = this.kc.makeApiClient(CustomObjectsApi);
    this.coreApi = this.kc.makeApiClient(CoreV1Api);
    this.namespace = namespace;
  }

  /**
   * Install CRDs to the cluster
   */
  async installCRDs(): Promise<void> {
    const api = this.kc.makeApiClient(KubernetesObjectApi);
    await api.create(EDGE_NODE_CRD as any);
    logger.info('EdgeNode CRD installed');
  }

  /**
   * Create an EdgeNode resource
   */
  async createEdgeNode(
    node: Omit<EdgeNodeResource, 'apiVersion' | 'kind'>,
  ): Promise<EdgeNodeResource> {
    const resource: EdgeNodeResource = {
      apiVersion: 'edge-cloud.io/v1',
      kind: 'EdgeNode',
      ...node,
    };

    const response = await (this.customApi as any).createNamespacedCustomObject(
      'edge-cloud.io',
      'v1',
      this.namespace,
      'edgenodes',
      resource,
    );

    return response.body as EdgeNodeResource;
  }

  /**
   * Get an EdgeNode by name
   */
  async getEdgeNode(name: string): Promise<EdgeNodeResource | null> {
    try {
      const response = await (this.customApi as any).getNamespacedCustomObject(
        'edge-cloud.io',
        'v1',
        this.namespace,
        'edgenodes',
        name,
      );
      return response.body as EdgeNodeResource;
    } catch {
      return null;
    }
  }

  /**
   * List all EdgeNodes
   */
  async listEdgeNodes(): Promise<EdgeNodeResource[]> {
    const response = await (this.customApi as any).listNamespacedCustomObject(
      'edge-cloud.io',
      'v1',
      this.namespace,
      'edgenodes',
    );
    return response.body.items as EdgeNodeResource[];
  }

  /**
   * Update EdgeNode status
   */
  async updateEdgeNodeStatus(
    name: string,
    status: EdgeNodeResource['status'],
  ): Promise<EdgeNodeResource> {
    const node = await this.getEdgeNode(name);
    if (!node) {
      throw new Error(`EdgeNode ${name} not found`);
    }

    const response = await (
      this.customApi as any
    ).patchNamespacedCustomObjectStatus(
      'edge-cloud.io',
      'v1',
      this.namespace,
      'edgenodes',
      name,
      { status },
    );

    return response.body as EdgeNodeResource;
  }

  /**
   * Delete an EdgeNode
   */
  async deleteEdgeNode(name: string): Promise<void> {
    await (this.customApi as any).deleteNamespacedCustomObject(
      'edge-cloud.io',
      'v1',
      this.namespace,
      'edgenodes',
      name,
    );
  }

  /**
   * Scale backend deployment
   */
  async scaleBackend(replicas: number): Promise<void> {
    const patch = {
      spec: {
        replicas,
      },
    };

    await (this.coreApi as any).patchNamespacedDeployment(
      'backend',
      this.namespace,
      patch,
    );
  }

  /**
   * Get cluster nodes
   */
  async getClusterNodes(): Promise<any[]> {
    const response = await this.coreApi.listNode();
    return (response as any).body.items;
  }

  /**
   * Watch for EdgeNode changes
   */
  watchEdgeNodes(
    callback: (event: string, node: EdgeNodeResource) => void,
  ): void {
    const watch = new (require('@kubernetes/client-node').Watch)(this.kc);

    watch.watch(
      `/apis/edge-cloud.io/v1/namespaces/${this.namespace}/edgenodes`,
      {},
      (type: string, obj: any) => {
        callback(type, obj as EdgeNodeResource);
      },
      (err: Error) => {
        logger.error({ err }, 'Watch error');
      },
    );
  }
}

import {
  collectDefaultMetrics,
  Counter,
  Gauge,
  Histogram,
  Registry,
  Summary,
} from 'prom-client';

// ============================================================================
// Prometheus Metrics System for Edge-Cloud Orchestrator
// ============================================================================

/**
 * METRIC NAMING CONVENTIONS
 *
 * Format: <namespace>_<subsystem>_<name>_<unit>
 *
 * Rules:
 * 1. Use snake_case for all metric names
 * 2. Namespace: 'edgecloud' (prefix for all metrics)
 * 3. Subsystem: scheduler, task, node, api
 * 4. Unit suffix: _seconds, _bytes, _total, _ratio
 * 5. Base unit: seconds (not ms), bytes (not KB)
 *
 * Examples:
 * - edgecloud_scheduler_queue_depth (gauge, no unit - count)
 * - edgecloud_task_duration_seconds (histogram)
 * - edgecloud_node_cpu_usage_ratio (gauge, 0-1)
 */

// Create a custom registry
export const register = new Registry();

// Add default Node.js metrics (event loop, memory, CPU)
collectDefaultMetrics({ register, prefix: 'edgecloud_nodejs_' });

