// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Record scheduling latency
 */
export function recordSchedulingLatency(
  policy: string,
  priority: string,
  result: 'assigned' | 'queued' | 'rejected',
  latencySeconds: number,
): void {
  schedulerSchedulingLatency
    .labels(policy, priority, result)
    .observe(latencySeconds);
  schedulerDecisionsTotal.labels(policy, result).inc();
}

/**
 * Update queue depth
 */
export function updateQueueDepth(priority: string, depth: number): void {
  schedulerQueueDepth.labels(priority).set(depth);
}

/**
 * Record task execution
 */
export function recordTaskExecution(
  taskType: string,
  priority: string,
  status: 'completed' | 'failed' | 'cancelled' | 'timeout',
  exitCode: number,
  durationSeconds: number,
  nodeRegion: string,
  costUsd: number,
): void {
  taskExecutionDuration
    .labels(taskType, priority, status, nodeRegion)
    .observe(durationSeconds);
  taskCompletedTotal.labels(taskType, status, String(exitCode)).inc();
  taskCostDollars.labels(taskType, nodeRegion).inc(costUsd);
}

/**
 * Update node metrics
 */
export function updateNodeMetrics(
  nodeId: string,
  nodeName: string,
  region: string,
  metrics: {
    cpuUsage: number;
    memoryUsage: number;
    memoryUsed: number;
    memoryTotal: number;
    containerCount: number;
    status: 'online' | 'offline' | 'degraded';
    latency: number;
    tasksRunning: number;
    tasksMax: number;
  },
): void {
  nodeCpuUsage.labels(nodeId, nodeName, region).set(metrics.cpuUsage);
  nodeMemoryUsage.labels(nodeId, nodeName, region).set(metrics.memoryUsage);
  nodeMemoryBytes
    .labels(nodeId, nodeName, region, 'used')
    .set(metrics.memoryUsed);
  nodeMemoryBytes
    .labels(nodeId, nodeName, region, 'total')
    .set(metrics.memoryTotal);
  nodeContainerCount
    .labels(nodeId, nodeName, region, 'running')
    .set(metrics.containerCount);
  nodeStatus
    .labels(nodeId, nodeName, region)
    .set(
      metrics.status === 'online' ? 1 : metrics.status === 'degraded' ? 0.5 : 0,
    );
  nodeLatency.labels(nodeId, nodeName, region).set(metrics.latency);
  nodeTaskCapacity
    .labels(nodeId, nodeName, 'running')
    .set(metrics.tasksRunning);
  nodeTaskCapacity.labels(nodeId, nodeName, 'max').set(metrics.tasksMax);
  nodeTaskCapacity
    .labels(nodeId, nodeName, 'available')
    .set(metrics.tasksMax - metrics.tasksRunning);
}

/**
 * Record API request
 */
export function recordApiRequest(
  method: string,
  endpoint: string,
  statusCode: number,
  durationSeconds: number,
): void {
  apiRequestLatency
    .labels(method, endpoint, String(statusCode))
    .observe(durationSeconds);
  apiRequestsTotal.labels(method, endpoint, String(statusCode)).inc();

  if (statusCode >= 400) {
    // Note: detailed error code is handled in the global error handler
    apiErrorsTotal
      .labels('UNKNOWN', endpoint, method)
      .inc();
  }
}

/**
 * Get metrics output for /metrics endpoint
 */
export async function getMetricsOutput(): Promise<string> {
  return register.metrics();
}

