// ============================================================================
// FASTIFY INTEGRATION
// ============================================================================

import { FastifyInstance, FastifyReply, FastifyRequest } from 'fastify';

/**
 * Register metrics endpoint and middleware with Fastify
 */
export async function registerMetricsPlugin(
  fastify: FastifyInstance,
): Promise<void> {
  // Metrics endpoint
  fastify.get(
    '/metrics',
    async (_request: FastifyRequest, reply: FastifyReply) => {
      const metrics = await getMetricsOutput();
      void reply.type('text/plain').send(metrics);    },
  );

  // Request timing middleware
  fastify.addHook('onRequest', async (request: FastifyRequest) => {
    request.startTime = Date.now();
  });

  fastify.addHook(
    'onResponse',
    async (request: FastifyRequest, reply: FastifyReply) => {
      const duration = (Date.now() - (request.startTime || Date.now())) / 1000;
      const endpoint = request.routeOptions?.url || request.url;

      recordApiRequest(request.method, endpoint, reply.statusCode, duration);
    },
  );
}

// Extend FastifyRequest type
declare module 'fastify' {
  interface FastifyRequest {
    startTime?: number;
  }
}

