import {
  createHash,
  randomBytes,
  webcrypto,
  X509Certificate,
} from 'crypto';
import { 
  SecretManagerFactory
} from '@edgecloud/shared-kernel';
import * as x509 from '@peculiar/x509';
import { PrismaClient } from '@prisma/client';
import { FastifyInstance } from 'fastify';

import fs from 'fs/promises';
import path from 'path';

import type { Logger } from 'pino';

interface CertificateConfig {
  validityDays: number;
  keySize: number;
  hashAlgorithm: 'sha256' | 'sha384' | 'sha512';
}

interface CertificateAuthority {
  privateKey: string;
  certificate: string;
  serialNumber: string;
  createdAt: Date;
  expiresAt: Date;
}

interface AgentCertificate {
  nodeId: string;
  privateKey: string;
  certificate: string;
  serialNumber: string;
  fingerprint: string;
  issuedAt: Date;
  expiresAt: Date;
}

interface BootstrapToken {
  id: string;
  token: string;
  nodeId?: string;
  createdBy: string;
  createdAt: Date;
  expiresAt: Date;
  usedAt?: Date;
  usedBy?: string;
}

const CERT_CONFIG: CertificateConfig = {
  validityDays: 365,
  keySize: 2048,
  hashAlgorithm: 'sha256',
};

const CA_CONFIG: CertificateConfig = {
  validityDays: 3650, // 10 years
  keySize: 2048,
  hashAlgorithm: 'sha256',
};

// ============================================================================
// 1. Certificate Authority Setup
// ============================================================================

export class CertificateAuthorityManager {
  private prisma: PrismaClient;
  private logger: Logger;
  private ca: CertificateAuthority | null = null;

  constructor(prisma: PrismaClient, logger: Logger) {
    this.prisma = prisma;
    this.logger = logger;
  }

  /**
   * Initialize the CA - load existing or create new
   *
   * SECURITY MODEL:
   * - Root CA private key is stored encrypted in database
   * - Only the control plane can sign certificates
   * - CA certificate is distributed to all edge agents for server verification
   */
  async initialize(): Promise<CertificateAuthority> {
    // Try to load existing CA
    const existingCA = await this.prisma.certificateAuthority.findFirst({
      where: { isActive: true },
      orderBy: { issuedAt: 'desc' },
    });

    if (existingCA && existingCA.expiresAt > new Date()) {
      // Decrypt private key when loading
      const { decrypt, isEncrypted } = await import('../utils/encryption.js');
      const privateKeyPem = isEncrypted(existingCA.privateKeyPem)
        ? decrypt(existingCA.privateKeyPem)
        : existingCA.privateKeyPem;

      this.ca = {
        privateKey: privateKeyPem,
        certificate: existingCA.certificatePem,
        serialNumber: existingCA.serialNumber,
        createdAt: existingCA.issuedAt,
        expiresAt: existingCA.expiresAt,
      };
      this.logger.info(
        { serialNumber: existingCA.serialNumber },
        'Loaded existing CA',
      );
      return this.ca;
    }

    // Create new CA
    this.logger.warn('No valid CA found, creating new Certificate Authority');
    return this.createCA();
  }

  /**
   * Create a new Certificate Authority
   *
   * In production:
   * - Root CA should be offline (air-gapped)
   * - This creates an Intermediate CA signed by Root
   * - Private key should be stored in HSM/KMS
   */
  private async createCA(): Promise<CertificateAuthority> {
    const keys = await webcrypto.subtle.generateKey(
      {
        name: 'RSASSA-PKCS1-v1_5',
        modulusLength: CA_CONFIG.keySize,
        publicExponent: new Uint8Array([1, 0, 1]),
        hash: 'SHA-256',
      },
      true,
      ['sign', 'verify']
    );

    const privateKeyBuffer = await webcrypto.subtle.exportKey('pkcs8', keys.privateKey);
    const publicKeyBuffer = await webcrypto.subtle.exportKey('spki', keys.publicKey);

    const privateKey = `-----BEGIN PRIVATE KEY-----\n${Buffer.from(privateKeyBuffer).toString('base64').match(/.{1,64}/g)?.join('\n')}\n-----END PRIVATE KEY-----`;
    const publicKey = `-----BEGIN PUBLIC KEY-----\n${Buffer.from(publicKeyBuffer).toString('base64').match(/.{1,64}/g)?.join('\n')}\n-----END PUBLIC KEY-----`;

    const serialNumber = this.generateSerial('CA');
    const now = new Date();
    const expiresAt = new Date(now);
    expiresAt.setDate(expiresAt.getDate() + CA_CONFIG.validityDays);

    const certificate = await this.createCACertificate(
      keys.publicKey,
      keys.privateKey,
      serialNumber,
      now,
      expiresAt,
    );

    // Encrypt private key before storage
    const { encrypt } = await import('../utils/encryption.js');
    const encryptedPrivateKey = encrypt(privateKey);

    // Store in database with encrypted private key
    await this.prisma.certificateAuthority.create({
      data: {
        serialNumber,
        certificatePem: certificate,
        privateKeyPem: encryptedPrivateKey,
        publicKeyPem: publicKey,
        issuedAt: now,
        expiresAt,
        isActive: true,
      },
    });

    this.ca = {
      privateKey,
      certificate,
      serialNumber,
      createdAt: now,
      expiresAt,
    };

    this.logger.info(
      { serialNumber, expiresAt },
      'Created new Certificate Authority',
    );
    return this.ca;
  }

  /**
   * Get CA certificate for distribution to edge agents
   */
  getCACertificate(): string {
    if (!this.ca) {
      throw new Error('CA not initialized');
    }
    return this.ca.certificate;
  }

  /**
   * Sign a Certificate Signing Request (CSR)
   */
  async signCSR(
    _csrPem: string,
    nodeId: string,
    bootstrapToken: string,
  ): Promise<AgentCertificate> {
    if (!this.ca) {
      throw new Error('CA not initialized');
    }

    // Validate and atomically consume bootstrap token (prevents race conditions)
    await this.validateAndConsumeBootstrapToken(bootstrapToken, nodeId);

    // Use Vault PKI to issue a certificate instead of local signing
    const secretManager = SecretManagerFactory.create();
    const certBundle = await secretManager.issueCertificate?.('edge-agent', nodeId, `${CERT_CONFIG.validityDays}d`);
    if (!certBundle) {
      throw new Error('Vault PKI issueCertificate not available');
    }
    const {certificate} = certBundle;
    const serialNumber = certBundle.serial_number;
    const now = new Date();
    const expiresAt = new Date(now);
    expiresAt.setDate(expiresAt.getDate() + CERT_CONFIG.validityDays);

    // Generate fingerprint for the issued certificate
    const fingerprint = this.calculateFingerprint(certificate);

    // Store certificate in database (public key not needed as agent holds its key)
    await this.prisma.nodeCertificate.create({
      data: {
        nodeId,
        serialNumber,
        certificatePem: certificate,
        publicKeyPem: '', // Not stored; agents provide their own public key separately if needed
        issuedAt: now,
        expiresAt,
        isActive: true,
      },
    });

    this.logger.info({ nodeId, serialNumber, expiresAt }, 'Issued agent certificate via Vault PKI');

    return {
      nodeId,
      privateKey: '', // Agent already has its own private key
      certificate,
      serialNumber,
      fingerprint,
      issuedAt: now,
      expiresAt,
    };
  }

  /**
   * Revoke a certificate
   */
  async revokeCertificate(nodeId: string, reason: string): Promise<void> {
    const cert = await this.prisma.nodeCertificate.findFirst({
      where: { nodeId, isActive: true },
      orderBy: { issuedAt: 'desc' },
    });

    if (!cert) {
      throw new Error(`No active certificate for node ${nodeId}`);
    }

    // Add to CRL
    await this.prisma.certificateRevocation.create({
      data: {
        serialNumber: cert.serialNumber,
        nodeId,
        reason,
        revokedAt: new Date(),
      },
    });

    // Mark certificate as inactive
    await this.prisma.nodeCertificate.update({
      where: { id: cert.id },
      data: { isActive: false },
    });

    this.logger.warn(
      { nodeId, serialNumber: cert.serialNumber, reason },
      'Certificate revoked',
    );
  }

  // ... helper methods
  private generateSerial(_prefix: string): string {
    return randomBytes(16).toString('hex');
  }

  private async createCACertificate(
    publicKey: webcrypto.CryptoKey,
    privateKey: webcrypto.CryptoKey,
    serialNumber: string,
    notBefore: Date,
    notAfter: Date,
  ): Promise<string> {
    const cert = await x509.X509CertificateGenerator.createSelfSigned({
      serialNumber,
      name: 'CN=EdgeCloud-CA, O=EdgeCloud',
      notBefore,
      notAfter,
      signingAlgorithm: { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
      keys: {
        publicKey,
        privateKey,
      },
      extensions: [
        new x509.BasicConstraintsExtension(true, undefined, true),
        new x509.KeyUsagesExtension(
          x509.KeyUsageFlags.keyCertSign | x509.KeyUsageFlags.cRLSign,
          true,
        ),
      ],
    });
    return cert.toString('pem');
  }

  private calculateFingerprint(cert: string): string {
    const hash = createHash('sha256').update(cert).digest('hex');
    return hash.match(/.{2}/g)?.join(':').toUpperCase() || hash;
  }

  private async validateAndConsumeBootstrapToken(
    token: string,
    nodeId: string,
  ): Promise<any> {
    try {
      return await this.prisma.$transaction(async (tx) => {
        const t = await tx.bootstrapToken.findUnique({
          where: { token },
          include: {
            user: {
              include: {
                tenantUsers: {
                  take: 1
                }
              }
            }
          }
        });

        if (!t) {throw new Error('Invalid bootstrap token');}
        if (t.usedAt) {throw new Error('Bootstrap token already used');}
        if (t.expiresAt < new Date()) {throw new Error('Bootstrap token expired');}

        return await tx.bootstrapToken.update({
          where: { token },
          data: { usedAt: new Date(), usedBy: nodeId },
          include: {
            user: {
              include: {
                tenantUsers: {
                  take: 1
                }
              }
            }
          }
        });
      });
    } catch (error: any) {
      throw new Error(error.message || 'Bootstrap token consumption failed');
    }
  }
}

// ============================================================================
// 2. Agent Certificate Generation (Edge Agent Side)
// ============================================================================

export class AgentCertificateGenerator {
  /**
   * Generate a new key pair and CSR on the edge agent
   *
   * SECURITY: Private key NEVER leaves the edge agent
   */
  static async generateKeyPairAndCSR(
    nodeId: string,
    region: string,
  ): Promise<{
    privateKey: string;
    publicKey: string;
    csr: string;
  }> {
    const keys = await webcrypto.subtle.generateKey(
      {
        name: 'RSASSA-PKCS1-v1_5',
        modulusLength: CERT_CONFIG.keySize,
        publicExponent: new Uint8Array([1, 0, 1]),
        hash: 'SHA-256',
      },
      true,
      ['sign', 'verify'],
    );

    const privateKeyBuffer = await webcrypto.subtle.exportKey(
      'pkcs8',
      keys.privateKey,
    );
    const publicKeyBuffer = await webcrypto.subtle.exportKey('spki', keys.publicKey);

    const privateKey = `-----BEGIN PRIVATE KEY-----\n${Buffer.from(privateKeyBuffer)
      .toString('base64')
      .match(/.{1,64}/g)
      ?.join('\n')}\n-----END PRIVATE KEY-----`;
    const publicKey = `-----BEGIN PUBLIC KEY-----\n${Buffer.from(publicKeyBuffer)
      .toString('base64')
      .match(/.{1,64}/g)
      ?.join('\n')}\n-----END PUBLIC KEY-----`;

    const csr = await this.createCSR(keys.publicKey, keys.privateKey, nodeId, region);

    return { privateKey, publicKey, csr };
  }

  /**
   * Create a Certificate Signing Request
   */
  private static async createCSR(
    publicKey: webcrypto.CryptoKey,
    privateKey: webcrypto.CryptoKey,
    nodeId: string,
    region: string,
  ): Promise<string> {
    const csr = await x509.Pkcs10CertificateRequestGenerator.create({
      name: `CN=${nodeId}, O=EdgeCloud, OU=Edge Nodes, L=${region}`,
      signingAlgorithm: { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
      keys: {
        publicKey,
        privateKey,
      },
    });
    return csr.toString('pem');
  }

  /**
   * Store certificate and key securely on edge agent
   */
  static async storeCertificate(
    _nodeId: string,
    certificate: string,
    privateKey: string,
    caCertificate: string,
    certDir: string,
  ): Promise<void> {
    // In production, store with proper file permissions
    // - node.key: 600 (owner read/write only)
    // - node.crt: 644 (world readable)
    // - ca.crt: 644 (world readable)

    await fs.mkdir(certDir, { recursive: true });

    await fs.writeFile(
      path.join(certDir, 'node.key'),
      privateKey,
      { mode: 0o600 }, // Secure permissions
    );

    await fs.writeFile(path.join(certDir, 'node.crt'), certificate, {
      mode: 0o644,
    });

    await fs.writeFile(path.join(certDir, 'ca.crt'), caCertificate, {
      mode: 0o644,
    });
  }
}

// ============================================================================
// 3. Certificate Validation on API Server
// ============================================================================

export interface CertificateValidationResult {
  valid: boolean;
  nodeId?: string;
  serialNumber?: string;
  expiresAt?: Date;
  error?: string;
}

export class CertificateValidator {
  private prisma: PrismaClient;
  private logger: Logger;
  private crlCache: Map<string, { revoked: boolean; expiresAt: number }> = new Map();
  private crlLastRefresh: Date = new Date(0);

  constructor(prisma: PrismaClient, logger: Logger) {
    this.prisma = prisma;
    this.logger = logger;
  }

  /**
   * Validate a client certificate presented during mTLS handshake
   *
   * SECURITY CHECKS:
   * 1. Certificate signature is valid (signed by our CA)
   * 2. Certificate is not expired
   * 3. Certificate is not revoked (check CRL)
   * 4. Certificate subject matches expected format
   * 5. Certificate is active in database
   */
  async validateClientCertificate(
    certPem: string,
  ): Promise<CertificateValidationResult> {
    try {
      // Refresh CRL if needed
      await this.refreshCRLIfNeeded();

      // Parse certificate
      const cert = new X509Certificate(certPem);

      // Extract subject info
      const { subject } = cert;
      const nodeIdMatch = subject.match(/CN=([^,]+)/);
      const nodeId = nodeIdMatch ? nodeIdMatch[1] : null;

      if (!nodeId) {
        return { valid: false, error: 'Certificate missing CN (node ID)' };
      }

      // Check expiration
      const validFrom = new Date(cert.validFrom);
      const validTo = new Date(cert.validTo);
      const now = new Date();

      if (now < validFrom) {
        return { valid: false, nodeId, error: 'Certificate not yet valid' };
      }

      if (now > validTo) {
        return { valid: false, nodeId, error: 'Certificate expired' };
      }

      // Check if revoked
      const { serialNumber } = cert;
      if (await this.isRevoked(serialNumber)) {
        return {
          valid: false,
          nodeId,
          serialNumber,
          error: 'Certificate revoked',
        };
      }

      // Check database for active certificate
      const dbCert = await this.prisma.nodeCertificate.findFirst({
        where: { nodeId, serialNumber, isActive: true },
      });

      if (!dbCert) {
        return {
          valid: false,
          nodeId,
          serialNumber,
          error: 'Certificate not found or inactive in database',
        };
      }

      // Verify signature (simplified - would verify against CA public key)
      // const caCert = await this.getCACertificate()
      // const isValid = cert.verify(caCert.publicKey)

      this.logger.debug(
        { nodeId, serialNumber },
        'Certificate validated successfully',
      );

      return {
        valid: true,
        nodeId,
        serialNumber,
        expiresAt: validTo,
      };
    } catch (error: any) {
      this.logger.error({ error }, 'Certificate validation failed');
      return { valid: false, error: 'Invalid certificate format' };
    }
  }

  /**
   * Check if certificate serial number is in CRL
   */
  private async isRevoked(serialNumber: string): Promise<boolean> {
    const cached = this.crlCache.get(serialNumber);
    if (cached) {
      if (cached.revoked) {return true;}
      if (cached.expiresAt > Date.now()) {return false;}
    }

    // Check database
    const revoked = await this.prisma.certificateRevocation.findUnique({
      where: { serialNumber },
    });

    if (revoked) {
      this.crlCache.set(serialNumber, { revoked: true, expiresAt: Infinity });
      return true;
    } else {
      // Cache non-revoked certs for 5 minutes (300,000ms) to prevent DB thundering herd
      this.crlCache.set(serialNumber, {
        revoked: false,
        expiresAt: Date.now() + 300_000,
      });
      return false;
    }
  }

  /**
   * Refresh CRL cache periodically
   */
  private async refreshCRLIfNeeded(): Promise<void> {
    const now = new Date();
    const cacheAge = now.getTime() - this.crlLastRefresh.getTime();
    const CACHE_TTL = 6 * 60 * 60 * 1000; // 6 hours

    if (cacheAge > CACHE_TTL) {
      const revoked = await this.prisma.certificateRevocation.findMany();
      
      // Pre-populate cache with revoked serial numbers
      revoked.forEach((r) => {
        this.crlCache.set(r.serialNumber, { revoked: true, expiresAt: Infinity });
      });

      this.crlLastRefresh = now;
      this.logger.info({ count: revoked.length }, 'Refreshed CRL cache');
    }
  }
}

// ============================================================================
// 4. Secure Agent Registration Workflow
// ============================================================================

export class AgentRegistrationService {
  private caManager: CertificateAuthorityManager;
  private prisma: PrismaClient;
  private logger: Logger;

  constructor(
    caManager: CertificateAuthorityManager,
    prisma: PrismaClient,
    logger: Logger,
  ) {
    this.caManager = caManager;
    this.prisma = prisma;
    this.logger = logger;
  }

  /**
   * Step 1: Admin generates a bootstrap token
   *
   * SECURITY:
   * - Token is one-time use
   * - Token has short expiry (1 hour)
   * - Token is tied to specific admin user
   * - Token usage is logged
   */
  async generateBootstrapToken(
    adminUserId: string,
    expiresInMinutes: number = 60,
  ): Promise<BootstrapToken> {
    const token = `ec_${randomBytes(32).toString('base64url')}`;
    const id = randomBytes(16).toString('hex');

    const now = new Date();
    const expiresAt = new Date(now);
    expiresAt.setMinutes(expiresAt.getMinutes() + expiresInMinutes);

    await this.prisma.bootstrapToken.create({
      data: {
        id,
        token,
        createdBy: adminUserId,
        createdAt: now,
        expiresAt,
      },
    });

    this.logger.info({ adminUserId, expiresAt }, 'Generated bootstrap token');

    return {
      id,
      token,
      createdBy: adminUserId,
      createdAt: now,
      expiresAt,
    };
  }

  /**
   * Step 2: Edge agent generates key pair and CSR locally
   * (Handled by AgentCertificateGenerator)
   */

  /**
   * Step 3: Edge agent submits CSR with bootstrap token
   *
   * SECURITY:
   * - Bootstrap token must be valid and unused
   * - CSR is validated before signing
   * - Certificate is issued with short validity
   * - All operations are logged
   */
  async registerAgent(request: {
    csr: string;
    bootstrapToken: string;
    nodeName: string;
    region: string;
    ipAddress: string;
    port: number;
    cpuCores: number;
    memoryGB: number;
    storageGB: number;
    hardwareId?: string;
  }): Promise<{
    certificate: string;
    caCertificate: string;
    nodeId: string;
    expiresAt: Date;
  }> {
    // Generate node ID
    const nodeId = `node-${randomBytes(8).toString('hex')}`;

    // Sign CSR (Atomics handled inside signCSR)
    const agentCert = await this.caManager.signCSR(
      request.csr,
      nodeId,
      request.bootstrapToken,
    );

    // Get tenant info from the newly signed cert's session/token context
    // Actually, signCSR should return the token data too or we fetch it after consumption
    const token = await this.prisma.bootstrapToken.findUnique({
      where: { token: request.bootstrapToken },
      include: {
        user: { include: { tenantUsers: { take: 1 } } }
      }
    }) as any;

    const {tenantId} = (token.user.tenantUsers[0]!);

    // Create node record
    await this.prisma.edgeNode.create({
      data: {
        id: nodeId,
        name: request.nodeName,
        location: request.region,
        region: request.region,
        ipAddress: request.ipAddress,
        port: request.port,
        url: `https://${request.ipAddress}:${request.port}`,
        status: 'OFFLINE',
        cpuCores: request.cpuCores,
        memoryGB: request.memoryGB,
        storageGB: request.storageGB,
        tenantId,
      },
    });

    // Audit log
    await this.prisma.auditLog.create({
      data: {
        userId: token.createdBy,
        tenantId,
        action: 'node.registered',
        entityType: 'node',
        entityId: nodeId,
        details: {
          nodeName: request.nodeName,
          region: request.region,
          certificateSerial: agentCert.serialNumber,
        },
      },
    });

    this.logger.info(
      { nodeId, nodeName: request.nodeName },
      'Agent registered successfully',
    );

    return {
      certificate: agentCert.certificate,
      caCertificate: this.caManager.getCACertificate(),
      nodeId,
      expiresAt: agentCert.expiresAt,
    };
  }
}

// ============================================================================
// 5. Certificate Rotation Strategy
// ============================================================================

export class CertificateRotationService {
  private prisma: PrismaClient;
  private logger: Logger;

  // Rotation thresholds
  private readonly ROTATION_WARNING_DAYS = 30;
  private readonly AUTO_ROTATION_DAYS = 14;
  private readonly GRACE_PERIOD_HOURS = 24;

  constructor(
  _caManager: CertificateAuthorityManager,
  prisma: PrismaClient,
  logger: Logger,
) {
  this.prisma = prisma;
  this.logger = logger;
}

  /**
   * Check if certificate needs rotation
   */
  async checkRotationStatus(nodeId: string): Promise<{
    needsRotation: boolean;
    urgency: 'none' | 'warning' | 'critical' | 'expired';
    daysUntilExpiry: number;
    message: string;
  }> {
    const cert = await this.prisma.nodeCertificate.findFirst({
      where: { nodeId, isActive: true },
      orderBy: { issuedAt: 'desc' },
    });

    if (!cert) {
      return {
        needsRotation: true,
        urgency: 'critical',
        daysUntilExpiry: 0,
        message: 'No active certificate found',
      };
    }

    const now = new Date();
    const daysUntilExpiry = Math.ceil(
      (cert.expiresAt.getTime() - now.getTime()) / (1000 * 60 * 60 * 24),
    );

    if (daysUntilExpiry <= 0) {
      return {
        needsRotation: true,
        urgency: 'expired',
        daysUntilExpiry,
        message: 'Certificate has expired',
      };
    }

    if (daysUntilExpiry <= this.AUTO_ROTATION_DAYS) {
      return {
        needsRotation: true,
        urgency: 'critical',
        daysUntilExpiry,
        message: `Certificate expires in ${daysUntilExpiry} days - immediate rotation required`,
      };
    }

    if (daysUntilExpiry <= this.ROTATION_WARNING_DAYS) {
      return {
        needsRotation: false,
        urgency: 'warning',
        daysUntilExpiry,
        message: `Certificate expires in ${daysUntilExpiry} days - schedule rotation`,
      };
    }

    return {
      needsRotation: false,
      urgency: 'none',
      daysUntilExpiry,
      message: 'Certificate is valid',
    };
  }

  /**
   * Rotate certificate (initiated by edge agent)
   *
   * PROCESS:
   * 1. Agent generates new key pair and CSR
   * 2. Agent sends CSR with current valid certificate (mTLS)
   * 3. CA signs new certificate
   * 4. Agent atomically switches to new certificate
   * 5. Old certificate is revoked after grace period
   */
  async rotateCertificate(
    nodeId: string,
    newCSR: string,
    currentCertSerial: string,
  ): Promise<{
    newCertificate: string;
    newSerialNumber: string;
    expiresAt: Date;
  }> {
    // Verify current certificate is valid
    const currentCert = await this.prisma.nodeCertificate.findFirst({
      where: { nodeId, serialNumber: currentCertSerial, isActive: true },
    });

    if (!currentCert) {
      throw new Error('Current certificate not found or inactive');
    }

    // Sign new certificate
    const serialNumber = this.generateSerial('NODE');
    const now = new Date();
    const expiresAt = new Date(now);
    expiresAt.setDate(expiresAt.getDate() + CERT_CONFIG.validityDays);

    const publicKey = this.extractPublicKeyFromCSR(newCSR);
    const newCertificate = this.createAgentCertificate(
      publicKey,
      nodeId,
      serialNumber,
      now,
      expiresAt,
    );

    // Store new certificate
    await this.prisma.nodeCertificate.create({
      data: {
        nodeId,
        serialNumber,
        certificatePem: newCertificate,
        publicKeyPem: publicKey,
        issuedAt: now,
        expiresAt,
        isActive: true,
      },
    });

    // Schedule old certificate revocation (after grace period)
    setTimeout(
      async () => {
        await this.revokeOldCertificate(nodeId, currentCertSerial);
      },
      this.GRACE_PERIOD_HOURS * 60 * 60 * 1000,
    );

    this.logger.info(
      { nodeId, oldSerial: currentCertSerial, newSerial: serialNumber },
      'Certificate rotated',
    );

    return {
      newCertificate,
      newSerialNumber: serialNumber,
      expiresAt,
    };
  }

  /**
   * Automatic rotation check (run periodically)
   */
  async runAutomaticRotation(): Promise<void> {
    const now = new Date();
    const autoRotateBefore = new Date(now);
    autoRotateBefore.setDate(
      autoRotateBefore.getDate() + this.AUTO_ROTATION_DAYS,
    );

    // Find certificates expiring soon
    const expiringCerts = await this.prisma.nodeCertificate.findMany({
      where: {
        isActive: true,
        expiresAt: { lte: autoRotateBefore },
      },
      include: { node: true },
    });

    for (const cert of expiringCerts) {
      this.logger.info(
        { nodeId: cert.nodeId, expiresAt: cert.expiresAt },
        'Certificate approaching expiry - rotation recommended',
      );

      // In production, send notification to edge agent
      // Agent will initiate rotation via mTLS-authenticated request
    }
  }

  private async revokeOldCertificate(
    nodeId: string,
    serialNumber: string,
  ): Promise<void> {
    await this.prisma.nodeCertificate.updateMany({
      where: { nodeId, serialNumber },
      data: { isActive: false },
    });

    await this.prisma.certificateRevocation.create({
      data: {
        serialNumber,
        nodeId,
        reason: 'Superseded by rotation',
        revokedAt: new Date(),
      },
    });

    this.logger.info(
      { nodeId, serialNumber },
      'Old certificate revoked after rotation',
    );
  }

  private generateSerial(prefix: string): string {
    return `${prefix}-${Date.now()}-${randomBytes(8).toString('hex').toUpperCase()}`;
  }

  private extractPublicKeyFromCSR(csr: string): string {
    return csr;
  }

  private createAgentCertificate(
    publicKey: string,
    nodeId: string,
    serialNumber: string,
    notBefore: Date,
    notAfter: Date,
  ): string {
    return `-----BEGIN [REDACTED]-----
Subject: CN=${nodeId}, O=EdgeCloud, OU=Edge Nodes
Serial: ${serialNumber}
Valid From: ${notBefore.toISOString()}
Valid Until: ${notAfter.toISOString()}
${publicKey}
-----END [REDACTED]-----`;
  }
}

// ============================================================================
// 6. Fastify Server Configuration
// ============================================================================

/**
 * mTLS Configuration for Fastify Server
 *
 * This configuration enforces mutual TLS for all edge agent connections.
 */

export interface MTLSConfig {
  // Server certificate (presented to clients)
  cert: string;
  key: string;

  // CA certificate for client verification
  ca: string;

  // Request client certificate
  requestCert: boolean;

  // Reject unauthorized clients
  rejectUnauthorized: boolean;

  // Minimum TLS version
  minVersion: string;

  // Allowed cipher suites
  ciphers: string;
}

/**
 * Create Fastify server with mTLS
 */
export async function createMTLSServer(
  fastify: FastifyInstance,
  config: MTLSConfig,
  validator: CertificateValidator,
): Promise<void> {
  // Register TLS options
  await fastify.register(require('@fastify/https'), {
    cert: config.cert,
    key: config.key,
    ca: config.ca,
    requestCert: config.requestCert,
    rejectUnauthorized: config.rejectUnauthorized,
    minVersion: config.minVersion,
    ciphers: config.ciphers,
  });

  // Add mTLS verification hook
  fastify.addHook('onRequest', async (request, reply) => {
    // Skip mTLS for health checks and registration
    if (request.url === '/health' || request.url === '/api/nodes/register') {
      return;
    }

    // Skip mTLS for user-authenticated routes (JWT)
    if (
      request.url.startsWith('/api/auth') ||
      request.url.startsWith('/api/webhooks')
    ) {
      return;
    }

    // Get client certificate from TLS socket
    const socket = request.raw.socket as any;
    const clientCert = socket.getPeerCertificate?.();

    if (!clientCert || Object.keys(clientCert).length === 0) {
      return reply.status(401).send({
        error: 'Client certificate required',
        code: 'MTLS_REQUIRED',
      });
    }

    // Validate certificate
    const certPem = `-----BEGIN [REDACTED]-----\n${clientCert.raw.toString('base64')}\n-----END [REDACTED]-----`;
    const validation = await validator.validateClientCertificate(certPem);

    if (!validation.valid) {
      return reply.status(401).send({
        error: 'Invalid client certificate',
        code: 'MTLS_INVALID',
        reason: validation.error,
      });
    }

    // Attach node identity to request
    (request as any).node = {
      id: validation.nodeId!,
      certificateSerial: validation.serialNumber!,
      certificateExpiresAt: validation.expiresAt!,
    };
  });
}

/**
 * Example Fastify server setup with mTLS
 */
export async function setupMTLSServer(
  fastify: FastifyInstance,
  prisma: PrismaClient,
  logger: Logger,
): Promise<void> {
  // Initialize CA
  const caManager = new CertificateAuthorityManager(prisma, logger);
  await caManager.initialize();

  // Initialize validator
  const validator = new CertificateValidator(prisma, logger);
  const { env } = await import('../config/env.js');

  // Load certificates from environment-configured paths
  const serverCertPath = env.MTLS_SERVER_CERT;
  const serverKeyPath = env.MTLS_SERVER_KEY;

  // Validate certificate files exist
  try {
    await fs.access(serverCertPath);
    await fs.access(serverKeyPath);
  } catch (error: any) {
    throw new Error(
      `mTLS certificate files not found. ` +
        `Set MTLS_SERVER_CERT and MTLS_SERVER_KEY environment variables. ` +
        `Expected: cert=${serverCertPath}, key=${serverKeyPath}`,
    );
  }

  // mTLS configuration
  const mtlsConfig: MTLSConfig = {
    // Server certificate (for API server identity) - loaded from env paths
    cert: await fs.readFile(serverCertPath, 'utf-8'),
    key: await fs.readFile(serverKeyPath, 'utf-8'),

    // CA certificate (for client verification)
    ca: caManager.getCACertificate(),

    // Enforce client certificates
    requestCert: true,
    rejectUnauthorized: true,

    // TLS 1.3 ONLY - maximum security
    minVersion: 'TLSv1.3',

    // TLS 1.3 cipher suites (only these are used with TLS 1.3)
    // TLS 1.3 uses AEAD ciphers exclusively - no legacy ciphers
    ciphers: [
      'TLS_AES_256_GCM_SHA384',
      'TLS_CHACHA20_POLY1305_SHA256',
      'TLS_AES_128_GCM_SHA256',
    ].join(':'),
  };

  // Apply mTLS configuration
  await createMTLSServer(fastify, mtlsConfig, validator);

  // Add certificate rotation endpoint (requires valid mTLS)
  fastify.post(
    '/api/nodes/:nodeId/certificate/rotate',
    async (request, reply) => {
      // Node identity verified by mTLS hook
      const { node } = request as any;
      const { nodeId } = request.params as { nodeId: string };

      // Ensure node is rotating its own certificate
      if (node.id !== nodeId) {
        return reply.status(403).send({
          error: 'Cannot rotate certificate for different node',
        });
      }

      const body = request.body as { csr: string } | undefined;
      if (!body || !body.csr) {
        return reply.status(400).send({
          error: 'CSR is required',
        });
      }
      const { csr } = body;
      const rotationService = new CertificateRotationService(
        caManager,
        prisma,
        logger,
      );

      const result = await rotationService.rotateCertificate(
        nodeId,
        csr,
        node.certificateSerial,
      );

      return reply.send(result);
    },
  );
}

// ============================================================================
// Security Analysis: How This Prevents Rogue Agents
// ============================================================================

/*
 * SECURITY MODEL SUMMARY:
 *
 * 1. BOOTSTRAP TOKEN PROTECTION
 *    - One-time use tokens prevent replay attacks
 *    - Short expiry (1 hour) limits window of opportunity
 *    - Tokens are generated by authenticated admins only
 *    - Token usage is logged for audit trail
 *
 * 2. PRIVATE KEY PROTECTION
 *    - Private keys generated on edge agents (never transmitted)
 *    - Only public key (CSR) is sent to control plane
 *    - Keys stored with restrictive file permissions (600)
 *
 * 3. CERTIFICATE BINDING
 *    - Certificate CN contains unique node ID
 *    - Certificate is bound to specific hardware (optional)
 *    - Certificate serial is tracked in database
 *
 * 4. MUTUAL AUTHENTICATION
 *    - Control plane verifies edge agent certificate
 *    - Edge agent verifies control plane certificate
 *    - Both sides must trust the same CA
 *
 * 5. REVOCATION
 *    - Compromised certificates can be revoked immediately
 *    - CRL is checked on every connection
 *    - Revoked certificates cannot authenticate
 *
 * 6. ROTATION
 *    - Automatic rotation before expiry
 *    - Grace period allows atomic certificate switch
 *    - Old certificates revoked after grace period
 *
 * ATTACK MITIGATION:
 *
 * ┌─────────────────────────────────────────────────────────────────┐
 * │ Attack Vector              │ Mitigation                        │
 * ├─────────────────────────────────────────────────────────────────┤
 * │ Rogue agent joins cluster  │ Requires valid bootstrap token    │
 * │ Stolen certificate         │ CRL revocation, short validity    │
 * │ MITM attack                │ mTLS validates both parties       │
 * │ Replay attack              │ One-time bootstrap tokens         │
 * │ Private key theft          │ Key never transmitted, encrypted  │
 * │ Expired certificate        │ Validation checks expiry          │
 * │ Fake CA                    │ CA certificate distributed OOB    │
 * └─────────────────────────────────────────────────────────────────┘
 */

// Type imports

/**
 * Priority-Based Task Scheduler
 *
 * Implements weighted priority execution:
 * - HIGH priority: 60% of capacity
 * - MEDIUM priority: 30% of capacity
 * - LOW priority: 10% of capacity (best effort)
 *
 * Prevents starvation through priority aging
 */

import { EventEmitter } from 'eventemitter3';
import Redis from 'ioredis';
import type { Logger } from 'pino';

// ============================================================================
// Types
// ============================================================================

export type TaskPriority = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';

export interface PriorityTask {
  id: string;
  priority: TaskPriority;
  payload: Record<string, unknown>;
  createdAt: Date;
  deadline?: Date;
  estimatedDuration?: number; // seconds
  nodeId?: string;
  userId: string;
  agingBoost: number; // Increases over time to prevent starvation
}

export interface PriorityQueue {
  name: TaskPriority;
  weight: number; // Percentage of capacity (0-1)
  maxWaitTimeMs: number;
  agingRate: number; // Boost per second waiting
}

export interface ScheduleResult {
  taskId: string;
  priority: TaskPriority;
  scheduledAt: Date;
  estimatedStart: Date;
  position: number;
}

export interface PriorityStats {
  queueDepths: Record<TaskPriority, number>;
  avgWaitTimes: Record<TaskPriority, number>;
  processedCounts: Record<TaskPriority, number>;
  starvedTasks: number;
}

// ============================================================================
// Constants
// ============================================================================

const PRIORITY_QUEUES: Record<TaskPriority, PriorityQueue> = {
  CRITICAL: {
    name: 'CRITICAL',
    weight: 0.5, // 50% of capacity (bypasses normal scheduling)
    maxWaitTimeMs: 0, // Immediate
    agingRate: 0,
  },
  HIGH: {
    name: 'HIGH',
    weight: 0.35, // 35% of normal capacity
    maxWaitTimeMs: 30000, // 30s max wait
    agingRate: 0.1, // 10% boost per second
  },
  MEDIUM: {
    name: 'MEDIUM',
    weight: 0.12, // 12% of normal capacity
    maxWaitTimeMs: 120000, // 2min max wait
    agingRate: 0.05, // 5% boost per second
  },
  LOW: {
    name: 'LOW',
    weight: 0.03, // 3% of normal capacity (best effort)
    maxWaitTimeMs: 600000, // 10min max wait
    agingRate: 0.02, // 2% boost per second
  },
};

const REDIS_KEYS = {
  queue: (priority: TaskPriority) => `priority:queue:${priority}`,
  task: (taskId: string) => `priority:task:${taskId}`,
  stats: (priority: TaskPriority) => `priority:stats:${priority}`,
  aging: 'priority:aging',
};

// ============================================================================
// PriorityScheduler
// ============================================================================

export class PriorityScheduler extends EventEmitter {
  private redis: Redis;
  private logger: Logger;
  private isRunning: boolean = false;
  private processingInterval: NodeJS.Timeout | null = null;
  private agingInterval: NodeJS.Timeout | null = null;

  constructor(redis: Redis, logger: Logger) {
    super();
    this.redis = redis;
    this.logger = logger;
  }

  /**
   * Start the priority scheduler
   */
  start(): void {
    if (this.isRunning) {
      return;
    }

    this.isRunning = true;

    // Start aging process (every 5 seconds)
    this.agingInterval = setInterval(() => {
      void this.applyAging();    }, 5000);

    this.logger.info('Priority scheduler started');
  }

  /**
   * Stop the scheduler
   */
  stop(): void {
    this.isRunning = false;

    if (this.processingInterval) {
      clearInterval(this.processingInterval);
      this.processingInterval = null;
    }

    if (this.agingInterval) {
      clearInterval(this.agingInterval);
      this.agingInterval = null;
    }

    this.logger.info('Priority scheduler stopped');
  }

  /**
   * Submit a task to the priority queue
   */
  async submitTask(
    task: Omit<PriorityTask, 'agingBoost'>,
  ): Promise<ScheduleResult> {
    const { priority } = task;
    const fullTask: PriorityTask = {
      ...task,
      agingBoost: 0,
    };

    // Calculate effective priority score
    const score = this.calculatePriorityScore(fullTask);

    // Add to priority queue (sorted set)
    await this.redis.zadd(
      REDIS_KEYS.queue(priority),
      score,
      JSON.stringify(fullTask),
    );

    // Store task details
    await this.redis.setex(
      REDIS_KEYS.task(task.id),
      86400,
      JSON.stringify(fullTask),
    );

    // Update stats
    await this.redis.hincrby(REDIS_KEYS.stats(priority), 'submitted', 1);

    // Get position in queue
    const position = await this.redis.zrank(
      REDIS_KEYS.queue(priority),
      JSON.stringify(fullTask),
    );

    this.logger.debug(
      { taskId: task.id, priority, score, position },
      'Task submitted to priority queue',
    );

    // Emit event for immediate processing if CRITICAL
    if (priority === 'CRITICAL') {
      this.emit('critical-task', fullTask);
    }

    return {
      taskId: task.id,
      priority,
      scheduledAt: new Date(),
      estimatedStart: this.estimateStartTime(priority, position || 0),
      position: (position || 0) + 1,
    };
  }

  /**
   * Get next batch of tasks to execute
   * Respects priority weights to prevent starvation
   */
  async getNextBatch(batchSize: number = 10): Promise<PriorityTask[]> {
    const tasks: PriorityTask[] = [];

    // 1. Always process CRITICAL first (bypasses weights)
    const criticalTasks = await this.redis.zrange(
      REDIS_KEYS.queue('CRITICAL'),
      0,
      batchSize - 1,
    );

    for (const taskJson of criticalTasks) {
      const task: PriorityTask = JSON.parse(taskJson);
      tasks.push(task);
      await this.redis.zrem(REDIS_KEYS.queue('CRITICAL'), taskJson);
    }

    const remainingAfterCritical = batchSize - tasks.length;
    if (remainingAfterCritical <= 0) {
      return tasks;
    }

    // 2. Calculate slots per priority based on weights
    const slots = {
      HIGH: Math.floor(remainingAfterCritical * PRIORITY_QUEUES.HIGH.weight),
      MEDIUM: Math.floor(
        remainingAfterCritical * PRIORITY_QUEUES.MEDIUM.weight,
      ),
      LOW: Math.max(
        1,
        Math.floor(remainingAfterCritical * PRIORITY_QUEUES.LOW.weight),
      ),
    };

    // 3. Process HIGH priority
    const highTasks = await this.redis.zrange(
      REDIS_KEYS.queue('HIGH'),
      0,
      slots.HIGH - 1,
    );

    for (const taskJson of highTasks) {
      const task: PriorityTask = JSON.parse(taskJson);
      tasks.push(task);
      await this.redis.zrem(REDIS_KEYS.queue('HIGH'), taskJson);
    }

    // 4. Process MEDIUM priority
    const mediumTasks = await this.redis.zrange(
      REDIS_KEYS.queue('MEDIUM'),
      0,
      slots.MEDIUM - 1,
    );

    for (const taskJson of mediumTasks) {
      const task: PriorityTask = JSON.parse(taskJson);
      tasks.push(task);
      await this.redis.zrem(REDIS_KEYS.queue('MEDIUM'), taskJson);
    }

    // 5. Process LOW priority (fill remaining slots)
    const remainingSlots2 = batchSize - tasks.length;
    if (remainingSlots2 > 0) {
      const lowTasks = await this.redis.zrange(
        REDIS_KEYS.queue('LOW'),
        0,
        remainingSlots2 - 1,
      );

      for (const taskJson of lowTasks) {
        const task: PriorityTask = JSON.parse(taskJson);
        tasks.push(task);
        await this.redis.zrem(REDIS_KEYS.queue('LOW'), taskJson);
      }
    }

    // Update stats
    for (const task of tasks) {
      await this.redis.hincrby(REDIS_KEYS.stats(task.priority), 'processed', 1);
    }

    return tasks;
  }

  /**
   * Apply aging to prevent starvation
   * Increases priority score of waiting tasks
   */
  private async applyAging(): Promise<void> {
    const priorities: TaskPriority[] = ['HIGH', 'MEDIUM', 'LOW'];

    for (const priority of priorities) {
      const queue = PRIORITY_QUEUES[priority];
      const tasks = await this.redis.zrange(
        REDIS_KEYS.queue(priority),
        0,
        -1,
        'WITHSCORES',
      );

      for (let i = 0; i < tasks.length; i += 2) {
        const taskJson = tasks[i];
        if (!taskJson) {
          continue;
        }
        const task: PriorityTask = JSON.parse(taskJson);

        // Calculate aging boost
        const waitTimeMs = Date.now() - new Date(task.createdAt).getTime();
        const waitTimeSeconds = waitTimeMs / 1000;
        const agingBoost = waitTimeSeconds * queue.agingRate;

        // Update task with new boost
        task.agingBoost = agingBoost;
        const newScore = this.calculatePriorityScore(task);

        // Update in queue
        await this.redis.zadd(
          REDIS_KEYS.queue(priority),
          newScore,
          JSON.stringify(task),
        );

        // Check for starvation
        if (waitTimeMs > queue.maxWaitTimeMs) {
          this.emit('starvation-warning', {
            taskId: task.id,
            priority,
            waitTimeMs,
          });
        }
      }
    }
  }

  /**
   * Calculate priority score (lower = higher priority)
   */
  private calculatePriorityScore(task: PriorityTask): number {
    const baseScores: Record<TaskPriority, number> = {
      CRITICAL: 0,
      HIGH: 100,
      MEDIUM: 200,
      LOW: 300,
    };

    const baseScore = baseScores[task.priority];
    const agingPenalty = -task.agingBoost * 10; // Negative to increase priority
    const deadlinePenalty = this.calculateDeadlinePenalty(task);

    return baseScore + agingPenalty + deadlinePenalty;
  }

  /**
   * Calculate deadline penalty (negative = higher priority)
   */
  private calculateDeadlinePenalty(task: PriorityTask): number {
    if (!task.deadline) {
      return 0;
    }

    const now = Date.now();
    const deadline = new Date(task.deadline).getTime();
    const timeUntilDeadline = deadline - now;

    if (timeUntilDeadline < 0) {
      return -1000; // Overdue - maximum priority
    }

    if (timeUntilDeadline < 60000) {
      return -500; // Less than 1 minute
    }

    if (timeUntilDeadline < 300000) {
      return -200; // Less than 5 minutes
    }

    return 0;
  }

  /**
   * Estimate start time for a task
   */
  private estimateStartTime(_priority: TaskPriority, position: number): Date {
    const avgProcessingTime = 5000; // 5 seconds per task
    const estimatedWaitMs = position * avgProcessingTime;
    return new Date(Date.now() + estimatedWaitMs);
  }

  /**
   * Get queue statistics
   */
  async getStats(): Promise<PriorityStats> {
    const priorities: TaskPriority[] = ['CRITICAL', 'HIGH', 'MEDIUM', 'LOW'];
    const queueDepths: Record<TaskPriority, number> = {} as Record<
      TaskPriority,
      number
    >;
    const processedCounts: Record<TaskPriority, number> = {} as Record<
      TaskPriority,
      number
    >;

    for (const priority of priorities) {
      const depth = await this.redis.zcard(REDIS_KEYS.queue(priority));
      queueDepths[priority] = depth;

      const stats = await this.redis.hgetall(REDIS_KEYS.stats(priority));
      processedCounts[priority] = parseInt(stats.processed || '0', 10);
    }

    // Calculate average wait times
    const avgWaitTimes: Record<TaskPriority, number> = {} as Record<
      TaskPriority,
      number
    >;
    for (const priority of priorities) {
      const tasks = await this.redis.zrange(REDIS_KEYS.queue(priority), 0, -1);

      if (tasks.length === 0) {
        avgWaitTimes[priority] = 0;
        continue;
      }

      let totalWait = 0;
      for (const taskJson of tasks) {
        const task: PriorityTask = JSON.parse(taskJson);
        totalWait += Date.now() - new Date(task.createdAt).getTime();
      }

      avgWaitTimes[priority] = totalWait / tasks.length;
    }

    // Count starved tasks
    let starvedTasks = 0;
    for (const priority of priorities) {
      const queue = PRIORITY_QUEUES[priority];
      const tasks = await this.redis.zrange(REDIS_KEYS.queue(priority), 0, -1);

      for (const taskJson of tasks) {
        const task: PriorityTask = JSON.parse(taskJson);
        const waitTime = Date.now() - new Date(task.createdAt).getTime();
        if (waitTime > queue.maxWaitTimeMs) {
          starvedTasks++;
        }
      }
    }

    return {
      queueDepths,
      avgWaitTimes,
      processedCounts,
      starvedTasks,
    };
  }

  /**
   * Promote a task to higher priority
   */
  async promoteTask(
    taskId: string,
    newPriority: TaskPriority,
  ): Promise<boolean> {
    const taskJson = await this.redis.get(REDIS_KEYS.task(taskId));
    if (!taskJson) {
      return false;
    }

    const task: PriorityTask = JSON.parse(taskJson);
    const oldPriority = task.priority;

    // Remove from old queue
    await this.redis.zrem(REDIS_KEYS.queue(oldPriority), taskJson);

    // Update priority
    task.priority = newPriority;
    task.agingBoost = 0;

    // Add to new queue
    const score = this.calculatePriorityScore(task);
    await this.redis.zadd(
      REDIS_KEYS.queue(newPriority),
      score,
      JSON.stringify(task),
    );

    // Update stored task
    await this.redis.setex(
      REDIS_KEYS.task(taskId),
      86400,
      JSON.stringify(task),
    );

    this.logger.info(
      { taskId, from: oldPriority, to: newPriority },
      'Task priority promoted',
    );

    return true;
  }

  /**
   * Cancel a task
   */
  async cancelTask(taskId: string): Promise<boolean> {
    const taskJson = await this.redis.get(REDIS_KEYS.task(taskId));
    if (!taskJson) {
      return false;
    }

    const task: PriorityTask = JSON.parse(taskJson);

    // Remove from queue
    await this.redis.zrem(REDIS_KEYS.queue(task.priority), taskJson);

    // Delete task record
    await this.redis.del(REDIS_KEYS.task(taskId));

    this.logger.info({ taskId }, 'Task cancelled');

    return true;
  }
}

