import { IncomingMessage } from 'http';

import Redis from 'ioredis';
import jwt from 'jsonwebtoken';

import { v4 as uuidv4 } from 'uuid';
import { WebSocket } from 'ws';

import { env } from '../config/env';
import type { Logger } from 'pino';

// JWT_SECRET must be set - validated in index.ts
const getJwtSecret = () => env.JWT_SECRET;

// WebSocket authentication timeout
// const AUTH_TIMEOUT = 10000; // 10 seconds to authenticate

const HEARTBEAT_INTERVAL = 30000; // 30 seconds
const HEARTBEAT_TIMEOUT = 60000; // 60 seconds - close if no response

interface Client {
  id: string;
  ws: WebSocket;
  subscriptions: Set<string>;
  isAuthenticated: boolean;
  userId?: string | undefined;
  connectedAt: Date;
  lastPing: Date;
  isAlive: boolean;
  tenantId?: string | undefined;
  role?: string | undefined;
}

interface Message {
  type: string;
  payload: unknown;
  timestamp: string;
}

interface ClusterMessage {
  instanceId: string;
  eventType: string; // The base event type (e.g., "task:created")
  payload: unknown;
  excludeSender?: string | undefined;
  tenantId: string;
}

export class WebSocketManager {
  private clients: Map<string, Client> = new Map();
  private logger: Logger;
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null;
  private redis: Redis | undefined;
  private redisSubscriber: Redis | undefined;
  private instanceId: string;

  constructor(logger: Logger, redis?: Redis) {
    this.logger = logger;
    this.redis = redis;
    this.instanceId = `ws-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;

    if (redis) {
      void this.setupRedisClustering();    }

    this.startHeartbeatCheck();
  }

  /**
   * Setup Redis Pub/Sub for cross-instance messaging
   */
  private async setupRedisClustering(): Promise<void> {
    if (!this.redis) {
      return;
    }

    // Create a dedicated subscriber connection
    this.redisSubscriber = this.redis.duplicate();

    // Subscribe to all namespaced channels using a pattern
    // Pattern matches "event:type:tenantId"
    await this.redisSubscriber.psubscribe('*:*:*');
    // Also subscribe to specific events that might not fit the pattern perfectly if needed
    // but the task says clients subscribe to "task:created:tenantId"
    
    this.redisSubscriber.on('pmessage', (_pattern: string, _channel: string, message: string) => {
      try {
        const clusterMsg: ClusterMessage = JSON.parse(message);

        // Don't process messages from this instance
        if (clusterMsg.instanceId === this.instanceId) {
          return;
        }

        // Broadcast locally to clients on this instance
        const namespacedChannel = `${clusterMsg.eventType}:${clusterMsg.tenantId}`;
        this.broadcastLocally(
          namespacedChannel,
          clusterMsg.payload,
          clusterMsg.excludeSender,
        );
      } catch (error) {
        this.logger.error({ error }, 'Failed to parse cluster message');
      }
    });

    this.logger.info(
      { instanceId: this.instanceId },
      'WebSocket clustering enabled with tenant isolation',
    );
  }

  private startHeartbeatCheck() {
    this.heartbeatInterval = setInterval(() => {
      const now = Date.now();
      const staleClients: string[] = [];

      for (const [clientId, client] of this.clients.entries()) {
        // Check if client is still alive
        if (!client.isAlive) {
          staleClients.push(clientId);
          continue;
        }

        // Check for timeout
        const timeSinceLastPing = now - client.lastPing.getTime();
        if (timeSinceLastPing > HEARTBEAT_TIMEOUT) {
          this.logger.warn(
            { clientId, timeSinceLastPing },
            'Client heartbeat timeout',
          );
          staleClients.push(clientId);
          continue;
        }

        // Send ping and mark as not alive (expecting pong)
        client.isAlive = false;
        try {
          if (client.ws.readyState === WebSocket.OPEN) {
            client.ws.ping();
          }
        } catch (error) {
          // Socket may be closing
          staleClients.push(clientId);
        }
      }

      // Terminate stale connections
      for (const clientId of staleClients) {
        const client = this.clients.get(clientId);
        if (client) {
          this.logger.info(
            { clientId },
            'Terminating stale WebSocket connection',
          );
          try {
            client.ws.close(1001, 'Heartbeat timeout');
          } catch (error) {
            // Socket may already be closed
          }
          this.clients.delete(clientId);
        }
      }

      if (staleClients.length > 0) {
        this.logger.info(
          { count: staleClients.length, remaining: this.clients.size },
          'Cleaned up stale connections',
        );
      }
    }, HEARTBEAT_INTERVAL);
  }

  handleConnection(ws: WebSocket, req: IncomingMessage) {
    const clientId = uuidv4();

    // Extract token from Authorization header or ?token= query parameter
    const authHeader = req.headers.authorization;
    const url = new URL(req.url || '', `http://${req.headers.host || 'localhost'}`);
    const queryToken = url.searchParams.get('token');

    let token = queryToken;
    if (!token && authHeader?.startsWith('Bearer ')) {
      token = authHeader.substring(7);
    }

    if (!token) {
      this.logger.warn({ clientId }, 'WebSocket connection rejected: No token provided');
      ws.close(4001, 'Unauthorized');
      return;
    }

    try {
      // Verify JWT using the same secret as the REST auth plugin
      const decoded = jwt.verify(token, getJwtSecret()) as {
        id: string;
        email: string;
        role: string;
        tenantId?: string;
      };

      if (!decoded.tenantId && decoded.role !== 'SUPER_ADMIN') {
        this.logger.warn({ clientId }, 'WebSocket connection rejected: No tenantId in JWT');
        ws.close(4001, 'Unauthorized: Missing Tenant Context');
        return;
      }

      const client: Client = {
        id: clientId,
        ws,
        subscriptions: new Set(),
        isAuthenticated: true,
        userId: decoded.id,
        connectedAt: new Date(),
        lastPing: new Date(),
        isAlive: true,
        tenantId: decoded.tenantId,
      };

      // STEP 5 & 6: Automatic tenant subscriptions
      if (decoded.role === 'SUPER_ADMIN') {
        // Super admins see everything
        client.subscriptions.add('*');
        this.logger.info({ clientId }, 'Super admin connected with wildcard subscription');
      } else if (decoded.tenantId) {
        const {tenantId} = decoded;
        const tenantChannels = [
          `task:created:${tenantId}`,
          `task:scheduled:${tenantId}`,
          `task:completed:${tenantId}`,
          `task:failed:${tenantId}`,
          `task:cancelled:${tenantId}`,
          `node:heartbeat:${tenantId}`,
          `node:offline:${tenantId}`,
          `node:degraded:${tenantId}`,
          `scheduler:decision:${tenantId}`,
          `circuit_breaker:opened:${tenantId}`,
          `circuit_breaker:closed:${tenantId}`,
          `ml:drift_detected:${tenantId}`,
          `workflow:execution_started:${tenantId}`,
          `workflow:execution_completed:${tenantId}`,
          `workflow:execution_failed:${tenantId}`,
          `workflow:progress:${tenantId}`,
          `workflow:step:completed:${tenantId}`,
        ];
        
        for (const ch of tenantChannels) {
          client.subscriptions.add(ch);
        }
        this.logger.info({ clientId, tenantId, channelCount: tenantChannels.length }, 'Client auto-subscribed to tenant channels');
      }

      this.clients.set(clientId, client);
      this.logger.info(
        { clientId, userId: decoded.id, tenantId: decoded.tenantId, totalClients: this.clients.size },
        'WebSocket client connected and authenticated',
      );

      // Send welcome message
      this.sendToClient(client, 'connected', {
        clientId,
        userId: decoded.id,
      });

      // Handle pong responses
      ws.on('pong', () => {
        client.isAlive = true;
        client.lastPing = new Date();
      });

      ws.on('message', (data: any) => {
        const str = data instanceof Buffer ? data.toString() : String(data);
        this.logger.debug({ clientId: client.id, rawMessage: str }, 'WebSocket message received');
        // Mark as alive on any message
        client.isAlive = true;
        client.lastPing = new Date();

        try {
          const message = JSON.parse(str);
          this.logger.debug({ clientId: client.id, type: message.type }, 'WebSocket message parsed');
          this.handleMessage(client, message);
        } catch (error) {
          this.logger.warn(
            { clientId, error },
            'Failed to parse WebSocket message',
          );
          this.sendToClient(client, 'error', {
            message: 'Invalid message format',
          });
        }
      });

      ws.on('close', () => {
        this.clients.delete(clientId);
        this.logger.info(
          { clientId, totalClients: this.clients.size },
          'WebSocket client disconnected',
        );
      });

      ws.on('error', (error) => {
        this.logger.error({ clientId, error }, 'WebSocket error');
        this.clients.delete(clientId);
      });
    } catch (error) {
      this.logger.warn(
        { clientId, error: (error as Error).message },
        'WebSocket connection rejected: Invalid token',
      );
      ws.close(4001, 'Unauthorized');
    }
  }

  private handleMessage(
    client: Client,
    message: { type: string; payload?: unknown },
  ) {
    // Require authentication for all messages
    if (!client.isAuthenticated) {
      this.sendToClient(client, 'error', {
        message: 'Authentication required',
      });
      return;
    }

    this.logger.debug({ clientId: client.id, type: message.type }, 'Handling WebSocket message');
    switch (message.type) {
      case 'subscribe':
        this.handleSubscribe(client, message.payload as { channels: string[] });
        break;
      case 'unsubscribe':
        this.handleUnsubscribe(
          client,
          message.payload as { channels: string[] },
        );
        break;
      case 'ping':
        this.sendToClient(client, 'pong', {
          timestamp: new Date().toISOString(),
        });
        break;
      default:
        this.logger.warn(
          { clientId: client.id, type: message.type },
          'Unknown WebSocket message type',
        );
    }
  }

  public handleSubscribe(client: Client, payload: any) {
    let channels: string[] = [];
    
    if (payload?.channels && Array.isArray(payload.channels)) {
      channels = payload.channels;
    } else if (payload?.channel && typeof payload.channel === 'string') {
      channels = [payload.channel];
    } else {
      return this.sendToClient(client, 'error', {
        message: 'Invalid subscribe payload. Expected { channels: string[] } or { channel: string }',
      });
    }

    this.logger.info({ clientId: client.id, channels }, 'Handling subscription request');
    for (const channel of channels) {
      // Enforce tenant scoping if not a super admin
      if (client.tenantId && !channel.endsWith(`:${client.tenantId}`) && channel !== '*') {
        this.logger.warn({ clientId: client.id, channel, tenantId: client.tenantId }, 'Rejected subscription to unauthorized channel');
        continue;
      }
      
      client.subscriptions.add(channel);
      this.logger.debug({ clientId: client.id, channel, allSubscriptions: Array.from(client.subscriptions) }, 'Added subscription');
    }

    this.sendToClient(client, 'subscribed', { channels: Array.from(client.subscriptions) });
  }

  private handleUnsubscribe(client: Client, payload: { channels: string[] }) {
    if (!payload?.channels || !Array.isArray(payload.channels)) {
      return this.sendToClient(client, 'error', {
        message: 'Invalid unsubscribe payload',
      });
    }

    for (const channel of payload.channels) {
      client.subscriptions.delete(channel);
    }

    this.sendToClient(client, 'unsubscribed', { channels: payload.channels });
  }


  private sendToClient(client: Client, type: string, payload: unknown) {
    if (client.ws.readyState === WebSocket.OPEN) {
      const message: Message = {
        type,
        payload,
        timestamp: new Date().toISOString(),
      };
      client.ws.send(JSON.stringify(message));
    }
  }

  /**
   * Broadcast to local clients only
   */
  broadcastLocally(
    namespacedChannel: string,
    payload: unknown,
    excludeClientId?: string,
  ) {
    // Extract base event type to send to client (e.g. "task:created:tenant-a" -> "task:created")
    const lastColon = namespacedChannel.lastIndexOf(':');
    const eventType = lastColon !== -1 ? namespacedChannel.substring(0, lastColon) : namespacedChannel;

    // Map event prefixes to broad channels for frontend compatibility
    const prefix = eventType.split(':')[0];
    const channelMap: Record<string, string> = {
      task: 'tasks',
      node: 'nodes',
      scheduler: 'scheduler',
      ml: 'ml',
      circuit_breaker: 'circuit_breaker',
      saga: 'saga',
      workflow: 'workflows'
    };
    const broadChannel = channelMap[prefix as string] || prefix;

    const message = {
      type: eventType,
      channel: broadChannel,
      namespacedChannel,
      data: payload,
      timestamp: new Date().toISOString(),
    };

    const messageStr = JSON.stringify(message);
    let sent = 0;

    for (const client of this.clients.values()) {
      if (excludeClientId && client.id === excludeClientId) {
        continue;
      }

      // Check if client is authorized to receive this message
      // 1. Same tenant context
      // 2. Client is subscribed to the specific namespaced channel, OR broad channel, OR global wildcard
      const isSameTenant = client.role === 'SUPER_ADMIN' || (client.tenantId && namespacedChannel.endsWith(`:${client.tenantId}`));
      
      if (!isSameTenant) {continue;}

      const isSubscribed = 
        client.subscriptions.has(namespacedChannel) || 
        client.subscriptions.has(broadChannel as string) ||
        client.subscriptions.has('*');
      
      if (isSubscribed) {
        if (client.ws.readyState === WebSocket.OPEN) {
          client.ws.send(messageStr);
          sent++;
        }
      }
    }

    this.logger.debug({ namespacedChannel, eventType, sentCount: sent }, 'Local broadcast completed');
  }

  /**
   * Broadcast to all instances via Redis Pub/Sub
   */
  public broadcast(eventType: string, payload: unknown, tenantId: string, excludeClientId?: string): void {
    if (!tenantId) {
      this.logger.error({ eventType }, 'Broadcast called without tenantId');
      return;
    }

    const namespacedChannel = `${eventType}:${tenantId}`;

    // First, broadcast locally
    this.broadcastLocally(namespacedChannel, payload, excludeClientId);

    // Then, broadcast to other instances via Redis
    if (this.redis) {
      const clusterMsg: ClusterMessage = {
        instanceId: this.instanceId,
        eventType,
        payload,
        excludeSender: excludeClientId,
        tenantId,
      };

      // Publish to the namespaced Redis channel
      this.redis
        .publish(namespacedChannel, JSON.stringify(clusterMsg))
        .catch((error) => {
          this.logger.error({ error, namespacedChannel }, 'Failed to publish cluster message');
        });
    }
  }

  broadcastToUser(userId: string, type: string, payload: unknown) {
    for (const client of this.clients.values()) {
      if (client.userId === userId && client.ws.readyState === WebSocket.OPEN) {
        this.sendToClient(client, type, payload);
      }
    }
  }

  broadcastToTenant(tenantId: string, type: string, payload: unknown) {
    this.broadcast(type, payload, tenantId);
  }

  getStats() {
    return {
      totalClients: this.clients.size,
      authenticatedClients: Array.from(this.clients.values()).filter(
        (c) => c.isAuthenticated,
      ).length,
      subscriptions: Array.from(this.clients.values()).reduce(
        (acc, c) => {
          for (const sub of c.subscriptions) {
            acc[sub] = (acc[sub] || 0) + 1;
          }
          return acc;
        },
        {} as Record<string, number>,
      ),
    };
  }

  close() {
    // Stop heartbeat check
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }

    // Close all connections
    for (const client of this.clients.values()) {
      client.ws.close();
    }
    this.clients.clear();
    this.logger.info('WebSocket manager closed');
  }
}

