import { DAGExecutor, WorkflowNode } from '@edgecloud/shared-kernel';
import { PrismaClient } from '@prisma/client';
import type { Logger } from 'pino';

import type { TaskScheduler } from './task-scheduler';
import type { WebSocketManager } from './websocket-manager';

export class WorkflowEngine {
  private prisma: PrismaClient;
  private logger: Logger;
  private taskScheduler: TaskScheduler;
  private wsManager: WebSocketManager;
  private dagExecutor: DAGExecutor;

  constructor(
    prisma: PrismaClient,
    logger: Logger,
    taskScheduler: TaskScheduler,
    wsManager: WebSocketManager
  ) {
    this.prisma = prisma;
    this.logger = logger;
    this.taskScheduler = taskScheduler;
    this.wsManager = wsManager;
    this.dagExecutor = new DAGExecutor();

    // Listen for task outcomes to advance workflows
    this.taskScheduler.on('taskOutcome', async ({ taskId, status }) => {
      try {
        await this.handleTaskOutcome(taskId, status);
      } catch (error) {
        this.logger.error({ error, taskId }, 'Error handling task outcome in workflow engine');
      }
    });
  }

  /**
   * Start a new workflow execution
   */
  async executeWorkflow(workflowId: string, tenantId: string): Promise<string> {
    this.logger.info({ workflowId, tenantId }, 'Starting workflow execution');

    const workflow = await this.prisma.workflow.findUnique({
      where: { id: workflowId, tenantId },
    });

    if (!workflow) {
      throw new Error(`Workflow ${workflowId} not found`);
    }

    const definition = workflow.definition as any;
    const rawNodes = definition.nodes || [];
    const rawEdges = definition.edges || [];

    // Map to DAGExecutor format
    const nodes: WorkflowNode[] = this.mapToWorkflowNodes(rawNodes, rawEdges);

    // Validate DAG
    const validation = this.dagExecutor.validate(nodes);
    if (!validation.valid) {
      throw new Error(`Invalid DAG: ${validation.errors.join(', ')}`);
    }

    // Create execution record
    const execution = await this.prisma.workflowExecution.create({
      data: {
        workflowId,
        tenantId,
        status: 'RUNNING',
      },
    });

    // Find root nodes (no dependencies)
    const readyNodes = this.dagExecutor.getReadyNodes(nodes, new Set());

    if (readyNodes.length === 0 && nodes.length > 0) {
      throw new Error('No root nodes found in DAG');
    }

    // Trigger initial tasks
    for (const node of readyNodes) {
      await this.submitTaskForNode(execution.id, node, tenantId);
    }

    // If no nodes at all, complete immediately
    if (nodes.length === 0) {
      await this.prisma.workflowExecution.update({
        where: { id: execution.id },
        data: { status: 'COMPLETED', completedAt: new Date() },
      });
    }

    this.wsManager.broadcastToTenant(tenantId, 'workflow:execution_started', {
      executionId: execution.id,
      workflowId,
    });

    return execution.id;
  }

  /**
   * Handle task outcome and advance workflow if needed
   */
  private async handleTaskOutcome(taskId: string, status: 'COMPLETED' | 'FAILED') {
    const taskRun = await this.prisma.workflowTaskRun.findFirst({
      where: { taskId },
      include: { execution: { include: { workflow: true } } },
    });

    if (!taskRun) {return;} // Not part of a workflow

    this.logger.debug({ taskId, status, executionId: taskRun.executionId }, 'Processing task outcome for workflow');

    // Update task run status
    await this.prisma.workflowTaskRun.update({
      where: { id: taskRun.id },
      data: {
        status: status === 'COMPLETED' ? 'COMPLETED' : 'FAILED',
        completedAt: new Date(),
      },
    });

    const {executionId} = taskRun;
    const {tenantId} = taskRun.execution;

    if (status === 'FAILED') {
      // Fail the whole workflow for now (strict mode)
      await this.prisma.workflowExecution.update({
        where: { id: executionId },
        data: { status: 'FAILED', completedAt: new Date() },
      });

      this.wsManager.broadcastToTenant(tenantId, 'workflow:execution_failed', {
        executionId,
        taskId,
        error: 'Task failed',
      });
      return;
    }

    // Check if we can advance
    const allRuns = await this.prisma.workflowTaskRun.findMany({
      where: { executionId },
    });

    const completedIds = new Set(
      allRuns
        .filter((r) => r.status === 'COMPLETED')
        .map((r) => r.stepName) // We use stepName in dependencies
    );

    const {workflow} = taskRun.execution;
    const definition = workflow.definition as any;
    const nodes: WorkflowNode[] = this.mapToWorkflowNodes(definition.nodes || [], definition.edges || []);

    const readyNodes = this.dagExecutor.getReadyNodes(nodes, completedIds);

    // Filter out nodes that are already in progress
    const inProgressStepNames = new Set(
      allRuns
        .filter((r) => r.status === 'RUNNING' || r.status === 'SCHEDULED' || r.status === 'PENDING')
        .map((r) => r.stepName)
    );

    const nextNodes = readyNodes.filter((n) => !inProgressStepNames.has(n.stepName));

    if (nextNodes.length > 0) {
      for (const node of nextNodes) {
        await this.submitTaskForNode(executionId, node, tenantId);
      }
    } else {
      // Check if all nodes are completed
      const allStepNames = new Set(nodes.map((n) => n.id));
      const finishedAll = Array.from(allStepNames).every((id) => completedIds.has(id));

      if (finishedAll) {
        await this.prisma.workflowExecution.update({
          where: { id: executionId },
          data: { status: 'COMPLETED', completedAt: new Date() },
        });

        this.wsManager.broadcastToTenant(tenantId, 'workflow:execution_completed', {
          executionId,
        });
      }
    }

    // Broadcast progress update
    this.wsManager.broadcastToTenant(tenantId, 'workflow:progress', {
      executionId,
      completedSteps: Array.from(completedIds),
    });
  }

  private mapToWorkflowNodes(rawNodes: any[], rawEdges: any[]): WorkflowNode[] {
    return rawNodes.map((node) => {
      const dependsOn = rawEdges
        .filter((edge) => edge.to === node.id)
        .map((edge) => edge.from);

      return {
        id: node.id,
        stepName: node.name,
        taskSpec: {
          name: node.name,
          type: node.config?.taskType || 'CUSTOM',
          priority: node.config?.priority || 'MEDIUM',
          target: node.config?.target || 'EDGE',
          input: node.config?.input || {},
          metadata: node.config?.metadata || {},
          nodeId: node.config?.nodeId,
        },
        dependsOn,
      };
    });
  }

  private async submitTaskForNode(executionId: string, node: WorkflowNode, tenantId: string) {
    this.logger.info({ executionId, step: node.stepName }, 'Submitting task for workflow step');

    // Create the actual Task
    const task = await this.prisma.task.create({
      data: {
        name: `${node.stepName} (Workflow)`,
        type: node.taskSpec.type as any,
        priority: node.taskSpec.priority as any || 'MEDIUM',
        target: node.taskSpec.target as any || 'EDGE',
        tenantId,
        policy: node.taskSpec.nodeId ? 'manual' : 'ml-optimized',
        reason: `Workflow execution ${executionId} step ${node.stepName}`,
        input: (node.taskSpec.input ?? {}) as any,
        metadata: {
          ...(node.taskSpec.metadata as any || {}),
          workflowExecutionId: executionId,
          workflowStepName: node.stepName,
        },
        nodeId: node.taskSpec.nodeId,
        executions: {
          create: {
            status: 'PENDING',
            attemptNumber: 1,
            tenantId,
          },
        },
      } as any,
    });

    // Create WorkflowTaskRun record
    await this.prisma.workflowTaskRun.create({
      data: {
        executionId,
        taskId: task.id,
        stepName: node.id, // Using the node's stable ID as stepName for dependency tracking
        status: 'PENDING',
        startedAt: new Date(),
      },
    });

    // Enqueue in task scheduler
    await this.taskScheduler.enqueue(task as any);
  }
}

/**
 * Unit Tests for Reliable Service Call Layer
 *
 * Tests the reliableCall wrapper ensuring:
 * - Retry logic works correctly
 * - Timeout protection active
 * - Circuit breaker integration
 * - Error classification accurate
 */


import { CircuitBreaker } from '@edgecloud/circuit-breaker';
import axios from 'axios';

import {
  isRetryableError,
  reliableAxios,
  reliableCall,
  ReliableCallError,
  reliableFetch,
  TimeoutError,
} from '../reliableCall';

// Mock axios
vi.mock('axios');
const mockedAxios = axios as any;

describe('reliableCall', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe('successful execution', () => {
    it('should return result on first success', async () => {
      const fn = vi.fn().mockResolvedValue('success');

      const result = await reliableCall(fn);

      expect(result).toBe('success');
      expect(fn).toHaveBeenCalledTimes(1);
    });

    it('should not retry on success', async () => {
      const fn = vi.fn().mockResolvedValue('success');

      await reliableCall(fn);

      expect(fn).toHaveBeenCalledTimes(1);
    });
  });

  describe('retry behavior', () => {
    beforeEach(() => {
      vi.useFakeTimers();
    });

    afterEach(() => {
      vi.useRealTimers();
    });

    it('should retry after transient failure', async () => {
      let attempts = 0;
      const fn = vi.fn().mockImplementation(async () => {
        if (attempts++ < 2) {
          throw new Error('ECONNRESET');
        }
        return 'success';
      });

      const promise = reliableCall(fn, { retries: 3 });

      // Fast forward through retries
      await vi.runAllTimersAsync();

      const result = await promise;

      expect(result).toBe('success');
      expect(fn).toHaveBeenCalledTimes(3);
    });

    it('should throw ReliableCallError after max retries', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('ECONNRESET'));

      const promise = reliableCall(fn, { retries: 1 });

      await vi.runAllTimersAsync();

      await expect(promise).rejects.toThrow(ReliableCallError);
      expect(fn).toHaveBeenCalledTimes(2);
    });

    it('should include attempt count in error', async () => {
      const fn = vi.fn().mockRejectedValue(new Error('ECONNRESET'));

      const promise = reliableCall(fn, { retries: 3 });

      await vi.runAllTimersAsync();

      await expect(promise).rejects.toThrow(ReliableCallError);

      try {
        await promise;
      } catch (error: any) {
        expect(error.attemptCount).toBe(4);
      }
    });
  });

  describe('timeout protection', () => {
    it('should timeout slow operations', async () => {
      const slowFn = vi.fn().mockImplementation(async () => {
        await new Promise((resolve) => setTimeout(resolve, 10000));
        return 'too slow';
      });

      try {
        await reliableCall(slowFn, { timeoutMs: 100, retries: 0 });
        throw new Error('Should have thrown');
      } catch (e) {
        expect(slowFn).toHaveBeenCalledTimes(1);
      }
    });

    it('should include operation name in timeout error', async () => {
      const slowFn = vi.fn().mockImplementation(async () => {
        await new Promise((resolve) => setTimeout(resolve, 10000));
        return 'slow';
      });

      try {
        await reliableCall(slowFn, {
          timeoutMs: 100,
          operationName: 'test-operation',
        });
        throw new Error('Should have thrown');
      } catch (error: unknown) {
        if (error instanceof TimeoutError) {
          expect(error.message).toContain('test-operation');
          expect(error.message).toContain('100ms');
        }
      }
    });
  });

  describe('circuit breaker integration', () => {
    it('should respect open circuit breaker', async () => {
      const circuitBreaker = new CircuitBreaker({
        failureThreshold: 1,
        resetTimeout: 1000,
      });

      // Open the circuit
      try {
        await reliableCall(() => Promise.reject(new Error('Fail')), {
          circuitBreaker,
          retries: 0,
        });
      } catch (e) {}

      // Circuit should be open now
      const fn = vi.fn().mockResolvedValue('success');
      try {
        await reliableCall(fn, { circuitBreaker, retries: 0 });
        throw new Error('Should have thrown');
      } catch (e) {
        expect(fn).toHaveBeenCalledTimes(0);
      }
    });

    it('should close circuit after success', async () => {
      const circuitBreaker = new CircuitBreaker({
        failureThreshold: 2,
        resetTimeout: 10,
      });

      let fails = 0;
      const fn = vi.fn().mockImplementation(async () => {
        if (fails++ < 2) {throw new Error('Fail');}
        return 'success';
      });

      // First two calls fail, opening circuit
      try {
        await reliableCall(fn, { circuitBreaker, retries: 0 });
      } catch (e) {}
      try {
        await reliableCall(fn, { circuitBreaker, retries: 0 });
      } catch (e) {}

      // Third call succeeds, closing circuit
      await new Promise((resolve) => setTimeout(resolve, 50));
      const result = await reliableCall(fn, { circuitBreaker, retries: 0 });
      expect(result).toBe('success');
    });
  });

  describe('error classification', () => {
    it('should classify network errors as retryable', () => {
      expect(isRetryableError(new Error('ECONNRESET'))).toBe(true);
      expect(isRetryableError(new Error('ETIMEDOUT'))).toBe(true);
      expect(isRetryableError(new Error('ENOTFOUND'))).toBe(true);
    });

    it('should classify HTTP 5xx as retryable', () => {
      const error500 = { response: { status: 500 } };
      const err = new Error('Service Unavailable') as any;
      err.response = { status: 503 };

      expect(isRetryableError(error500)).toBe(true);
      expect(isRetryableError(err)).toBe(true);
    });

    it('should classify timeout errors as non-retryable', () => {
      const timeoutError = new TimeoutError('test', 1000);
      expect(isRetryableError(timeoutError)).toBe(false);
    });

    it('should classify client errors as non-retryable', () => {
      const error400 = { response: { status: 400 } };
      const error404 = { response: { status: 404 } };

      expect(isRetryableError(error400)).toBe(false);
      expect(isRetryableError(error404)).toBe(false);
    });
  });
});

describe('reliableAxios', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('should wrap axios.get with reliability', async () => {
    mockedAxios.get.mockResolvedValue({ data: 'test', status: 200 });

    const result = await reliableAxios('http://api.example.com/test');

    expect(mockedAxios.get).toHaveBeenCalledWith(
      'http://api.example.com/test',
      undefined,
    );
    expect((result as any).data).toBe('test');
  });

  it('should retry on 503 error', async () => {
    let attempts = 0;
    mockedAxios.get.mockImplementation(async () => {
      if (attempts++ < 2) {
        const error = new Error('Service Unavailable');
        (error as any).response = { status: 503 };
        throw error;
      }
      return { data: 'success', status: 200 };
    });

    const result = await reliableAxios(
      'http://api.example.com/test',
      undefined,
      { retries: 3 },
    );

    expect((result as any).data).toBe('success');
    expect(mockedAxios.get).toHaveBeenCalledTimes(3);
  });
});

describe('reliableFetch', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('should wrap fetch with reliability', async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      status: 200,
      json: async () => ({ data: 'test' }),
    });

    const result = await reliableFetch('http://api.example.com/test');

    expect(global.fetch).toHaveBeenCalledWith(
      'http://api.example.com/test',
      undefined,
    );
    expect((result as any).data).toBe('test');
  });

  it('should retry on 500 error', async () => {
    let attempts = 0;
    global.fetch = vi.fn().mockImplementation(async () => {
      if (attempts++ < 2) {
        const err = new Error('Internal Server Error') as any;
        err.status = 500;
        return Promise.reject(err);
      }
      return {
        ok: true,
        status: 200,
        json: async () => ({ data: 'success' }),
      };
    });

    const result = await reliableFetch(
      'http://api.example.com/test',
      undefined,
      { retries: 3 },
    );

    expect((result as any).data).toBe('success');
    expect(global.fetch).toHaveBeenCalledTimes(3);
  });
});

import {
  CircuitBreaker,
  type CircuitBreakerConfig,
  CircuitBreakerRegistry,
  RedisCircuitBreakerSync,
} from '@edgecloud/circuit-breaker';
import Redis from 'ioredis';

import { createLogger } from '../lib/logger';
import { WebSocketManager } from '../services/websocket-manager';

const logger = createLogger('circuit-breaker');

// Global registry for all circuit breakers
export const globalCircuitBreakerRegistry = new CircuitBreakerRegistry();
let wsManager: WebSocketManager | undefined;
let redisSync: RedisCircuitBreakerSync | undefined;

/**
 * Configure the registry to broadcast state changes via WebSocket
 */
export function setWebSocketManager(manager: WebSocketManager) {
  wsManager = manager;
}

/**
 * Configure the registry to synchronize state via Redis
 */
export async function initializeRedisSync(redis: Redis) {
  redisSync = new RedisCircuitBreakerSync(redis);

  // Pull initial state from Redis
  await redisSync.syncStateFromRedis(globalCircuitBreakerRegistry);

  // Subscribe to changes from other pods
  const subscriber = redis.duplicate();
  await redisSync.subscribeToStateChanges(globalCircuitBreakerRegistry, subscriber);

  return redisSync;
}

// Circuit breaker configurations for different service types
export const circuitBreakerConfigs = {
  // Database circuit breaker - conservative due to criticality
  database: {
    name: 'PostgreSQL',
    failureThreshold: 5,
    resetTimeout: 30000, // 30 seconds
    halfOpenMaxCalls: 3,
    successThreshold: 2,
  } as CircuitBreakerConfig,

  // Redis circuit breaker - more aggressive recovery
  redis: {
    name: 'Redis',
    failureThreshold: 3,
    resetTimeout: 10000, // 10 seconds
    halfOpenMaxCalls: 2,
    successThreshold: 1,
  } as CircuitBreakerConfig,

  // External API circuit breaker - conservative
  externalApi: {
    name: 'External-API',
    failureThreshold: 5,
    resetTimeout: 60000, // 60 seconds
    halfOpenMaxCalls: 3,
    successThreshold: 2,
  } as CircuitBreakerConfig,

  // Vault/PKI circuit breaker
  vaultPki: {
    name: 'VaultPKI',
    failureThreshold: 3,
    resetTimeout: 45000,
    halfOpenMaxCalls: 2,
    successThreshold: 1,
  } as CircuitBreakerConfig,

  // Node agent circuit breaker
  nodeAgent: {
    name: 'node-agent',
    failureThreshold: 3,
    resetTimeout: 30000, // 30 seconds
    halfOpenMaxCalls: 2,
    successThreshold: 1,
  } as CircuitBreakerConfig,

  // S3 Model Storage
  s3ModelStorage: {
    name: 's3-model-storage',
    failureThreshold: 3,
    successThreshold: 2,
    resetTimeout: 30000,
    halfOpenMaxCalls: 2,
  } as CircuitBreakerConfig,

  // Electricity Maps API
  electricityMapsApi: {
    name: 'electricity-maps-api',
    failureThreshold: 3,
    successThreshold: 1,
    resetTimeout: 300000, // 5 min
    halfOpenMaxCalls: 2,
  } as CircuitBreakerConfig,
};

/**
 * Get or create a circuit breaker for a service
 */
export function getCircuitBreaker(
  config: CircuitBreakerConfig,
): CircuitBreaker {
  const cb = globalCircuitBreakerRegistry.getOrCreate(config.name, config);

  // Add logging and WebSocket broadcasts for state changes if not already set
  if (cb.listenerCount('open') === 0) {
    cb.on('open', () => {
      logger.warn({ breaker: config.name }, 'Circuit breaker opened');
      wsManager?.broadcast('circuit_breaker:opened', { name: config.name, timestamp: new Date().toISOString() }, 'system');
    });

    cb.on('close', () => {
      logger.info({ breaker: config.name }, 'Circuit breaker closed (healthy)');
      wsManager?.broadcast('circuit_breaker:closed', { name: config.name, timestamp: new Date().toISOString() }, 'system');
    });

    cb.on('halfOpen', () => {
      logger.info(
        { breaker: config.name },
        'Circuit breaker half-open (testing)',
      );
      wsManager?.broadcast('circuit_breaker:half_open', { name: config.name, timestamp: new Date().toISOString() }, 'system');
    });

    // Add Redis sync hooks
    const syncState = async (state: any) => {
      if (redisSync) {
        await redisSync.publishStateChange(config.name, state, {
          failureRate: cb.getMetrics().failures / (cb.getMetrics().totalCalls || 1),
          lastFailureAt: cb.getMetrics().lastFailureTime
        });
      }
    };

    cb.on('open', () => syncState('OPEN'));
    cb.on('close', () => syncState('CLOSED'));
    cb.on('halfOpen', () => syncState('HALF_OPEN'));
  }

  return cb;
}

/**
 * Execute function with circuit breaker protection
 */
export async function withCircuitBreaker<T>(
  config: CircuitBreakerConfig,
  fn: () => Promise<T>,
  fallback?: () => T,
): Promise<T> {
  const cb = getCircuitBreaker(config);
  return cb.execute(fn, fallback);
}

/**
 * Get metrics for all circuit breakers
 */
export function getAllCircuitBreakerMetrics() {
  return globalCircuitBreakerRegistry.getAllMetrics();
}

/**
 * Get all circuit breaker states for the UI
 */
export function getAllCircuitBreakerStates() {
  return globalCircuitBreakerRegistry.getAllStates();
}

/**
 * Force close all circuit breakers (useful for testing or manual recovery)
 */
export function forceCloseAllCircuitBreakers(): void {
  globalCircuitBreakerRegistry.resetAll();
}

import { FastifyReply, FastifyRequest } from 'fastify';

/**
 * Utility for handling API deprecation and sunsetting.
 * Follows IETF draft-ietf-httpapi-deprecation-header and draft-ietf-httpapi-sunset-header.
 */

export interface DeprecationOptions {
  deprecationDate?: string; // ISO 8601 date when deprecation was announced
  sunsetDate?: string;      // ISO 8601 date when the endpoint will be removed
  link?: string;            // URL providing more information
}

/**
 * Sets deprecation headers on the response.
 */
export function setDeprecationHeaders(
  reply: FastifyReply,
  options: DeprecationOptions
) {
  if (options.deprecationDate) {
    void reply.header('Deprecation', options.deprecationDate);  } else {
    void reply.header('Deprecation', 'true');  }

  if (options.sunsetDate) {
    void reply.header('Sunset', options.sunsetDate);  }

  if (options.link) {
    void reply.header('Link', `<${options.link}>; rel="deprecation"; type="text/html"`);  }
}

/**
 * Higher-order function to wrap a route handler with deprecation logic.
 */
export function deprecated(
  options: DeprecationOptions,
  handler: (request: FastifyRequest, reply: FastifyReply) => Promise<any>
) {
  return async function(request: FastifyRequest, reply: FastifyReply) {
    // Log warning (once per endpoint/version in a real system we might use a cache)
    request.log.warn(
      { url: request.url, ...options },
      'Accessing deprecated API endpoint'
    );

    setDeprecationHeaders(reply, options);
    
    return handler(request, reply);
  };
}

/**
 * Simple encryption utility for sensitive database fields
 * Uses AES-256-GCM for authenticated encryption
 *
 * NOTE: For production, consider using a KMS (AWS KMS, Azure Key Vault, HashiCorp Vault)
 * This implementation provides a practical middle-ground for immediate security improvement
 */

import {
  createCipheriv,
  createDecipheriv,
  randomBytes,
  scryptSync,
} from 'crypto';

import { env } from '../config/env';

const ALGORITHM = 'aes-256-gcm';
const IV_LENGTH = 16;
const AUTH_TAG_LENGTH = 16;
const SALT_LENGTH = 32;

/**
 * Derive encryption key from environment variable
 * Uses scrypt for key derivation
 */
function getEncryptionKey(): Buffer {
  const encryptionKey = env.ENCRYPTION_KEY;

  // Use scrypt to derive a proper 256-bit key
  return scryptSync(encryptionKey, 'edgecloud-salt', 32);
}

/**
 * Encrypt sensitive data
 * @param plaintext - Data to encrypt
 * @returns Encrypted string in format: salt:iv:authTag:ciphertext (base64)
 */
export function encrypt(plaintext: string): string {
  if (!plaintext) {
    return plaintext;
  }

  try {
    const key = getEncryptionKey();
    const salt = randomBytes(SALT_LENGTH);
    const iv = randomBytes(IV_LENGTH);

    const cipher = createCipheriv(ALGORITHM, key, iv);

    let encrypted = cipher.update(plaintext, 'utf8', 'base64');
    encrypted += cipher.final('base64');

    const authTag = cipher.getAuthTag();

    // Combine salt + iv + authTag + ciphertext
    const result = Buffer.concat([
      salt,
      iv,
      authTag,
      Buffer.from(encrypted, 'base64'),
    ]).toString('base64');

    return result;
  } catch (error) {
    throw new Error(`Encryption failed: ${(error as Error).message}`);
  }
}

/**
 * Decrypt sensitive data
 * @param ciphertext - Encrypted string in format: salt:iv:authTag:ciphertext (base64)
 * @returns Decrypted plaintext
 */
export function decrypt(ciphertext: string): string {
  if (!ciphertext) {
    return ciphertext;
  }

  try {
    const key = getEncryptionKey();
    const buffer = Buffer.from(ciphertext, 'base64');

    // Extract components
    const iv = buffer.subarray(SALT_LENGTH, SALT_LENGTH + IV_LENGTH);
    const authTag = buffer.subarray(
      SALT_LENGTH + IV_LENGTH,
      SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH,
    );
    const encrypted = buffer.subarray(
      SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH,
    );

    const decipher = createDecipheriv(ALGORITHM, key, iv);
    decipher.setAuthTag(authTag);

    let decrypted = decipher.update(
      encrypted.toString('base64'),
      'base64',
      'utf8',
    );
    decrypted += decipher.final('utf8');

    return decrypted;
  } catch (error) {
    throw new Error(`Decryption failed: ${(error as Error).message}`);
  }
}

/**
 * Check if a string appears to be encrypted (basic heuristic)
 * @param value - String to check
 * @returns true if likely encrypted
 */
export function isEncrypted(value: string): boolean {
  if (!value || typeof value !== 'string') {
    return false;
  }

  try {
    const buffer = Buffer.from(value, 'base64');
    // Check if length matches expected encrypted format
    return buffer.length >= SALT_LENGTH + IV_LENGTH + AUTH_TAG_LENGTH + 1;
  } catch {
    return false;
  }
}

/**
 * Hash sensitive data for comparison (one-way)
 * Use for fields that don't need decryption (e.g., API key hashes)
 * @param data - Data to hash
 * @returns SHA-256 hash
 */
export function hashSensitive(data: string): string {
  const { createHash } = require('crypto');
  return createHash('sha256').update(data).digest('hex');
}

// ============================================================================
// Global Error Handler
// ============================================================================
//
// Catches all unhandled errors in the application
// Prevents silent failures and enables graceful degradation
// ============================================================================

import { createLogger } from '../lib/logger';

const logger = createLogger('global-error-handler');

let hasUnhandledErrors = false;
let unhandledErrorCount = 0;

/**
 * Register global error handlers
 * Should be called once at application startup
 */
export function registerGlobalErrorHandlers(): void {
  // Unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    unhandledErrorCount++;
    hasUnhandledErrors = true;

    logger.error(
      {
        reason,
        promise: promise.toString(),
        count: unhandledErrorCount,
      },
      'UNHANDLED REJECTION',
    );

    // Don't exit - allow application to continue
    // But log severity for monitoring
  });

  // Uncaught exceptions
  process.on('uncaughtException', (error) => {
    logger.fatal({ error }, 'UNCAUGHT EXCEPTION');

    // Log but don't exit immediately
    // Allow cleanup and graceful shutdown
    setTimeout(() => {
      logger.warn('Process continuing after uncaught exception');
    }, 1000);
  });

  // Warning before exit (for cleanup)
  process.on('exit', (code) => {
    if (hasUnhandledErrors) {
      logger.warn(
        { code, unhandledErrorCount },
        'Process exiting with unhandled errors',
      );
    } else {
      logger.info({ code }, 'Process exiting normally');
    }
  });

  logger.info('✅ Global error handlers registered');
}

/**
 * Get unhandled error statistics
 */
export function getUnhandledErrorStats(): {
  hasErrors: boolean;
  count: number;
} {
  return {
    hasErrors: hasUnhandledErrors,
    count: unhandledErrorCount,
  };
}

/**
 * Reset error state (for testing only)
 */
export function resetErrorState(): void {
  hasUnhandledErrors = false;
  unhandledErrorCount = 0;
}

